window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_021"]={"n":"区大相","dyn":"明","poems":[{"t":"初夏","f":"古风","c":["滔滔孟夏，品物洁齐。","日月于迈，我心孔凄。","中园有槿，其叶萋萋。","芰荷出水，桃李成蹊。","春花昨荣，落而为泥。","今者谈宴，诘旦乖暌。","大块劳生，形役志迷。","良会几何，用兹惋懠。","灼灼丹葩，煌煌赤圭。","君子服之，以和天倪。","山则多云，水则盈溪。","挐舟溯梁，渚钓林栖。","瞻彼白驹，驾我青鹥。","与二三子，于攀于跻。"]},{"t":"励志诗 其一","f":"古风","c":["有大人者，德业日新。","彼虽圣哲，聿用忧勤。","嗟余小子，舜我何人。","少也失学，壮而无闻。"]},{"t":"励志诗 其二","f":"古风","c":["在昔弱龄，粗事诗书。","鬒发其蓬，税驾焉如。","朝华夕殒，奄忽居诸。","我匪乔松，其能久欤。"]},{"t":"励志诗 其三","f":"古风","c":["不树不艺，曷望秋穫。","不斲不削，曷施丹雘。","我疆我室，是咨是度。","勿为胡成，不殖将落。"]},{"t":"励志诗 其四","f":"古风","c":["上善若水，是以有德。","下士闻道，笑而不识。","鹪鹩巢林，卑栖自溺。","大鹏扶摇，汝将安适。"]},{"t":"励志诗 其五","f":"古风","c":["嗟我不淑，实昧前算。","刚而不克，柔而靡断。","方覆一篑，废涂于半。","汎汎中流，茫茫道岸。"]},{"t":"励志诗 其六","f":"古风","c":["鸿鹄高飞，必用羽仪。","如何中路，弃我如遗。","非彼弃我，我实荒斯。","迁善改过，来犹可追。"]},{"t":"励志诗 其七","f":"古风","c":["人亦有言，下流莫处。","高岸为谷，百恶是注。","祸福之门，贤者所杜。","慎尔发机，荣辱之主。"]},{"t":"励志诗 其八","f":"古风","c":["人亦有言，功崇惟志。","云胡弗竞，希骥则骥。","大人所履，小子所视。","矧兹秽陋，能不思企。"]},{"t":"励志诗 其九","f":"古风","c":["畴能不细，而丰于大。","畴能不迩，而远是迈。","积水成渊，累土成岱。","不积不累，厥功攸替。"]},{"t":"励志诗 其十","f":"古风","c":["滔滔逝者，日月其遒。","烈士壮心，奚必凛秋。","嗟我怀思，在彼中洲。","望而不见，我心伤忧。"]},{"t":"三月三日拟兰亭体","f":"古风","c":["四时之乐，惟此暮春。","偕我良俦，祓彼涧滨。","兴言觞咏，陶写天真。","仰睇飞羽，俯察游鳞。"]},{"t":"朔风吹缨五章送焦弱侯修撰","f":"古风","c":["朔风吹缨，代马悲鸣。","往送我友，言返旧京。","我无羽翼，与子偕行。","匪耽爰处，永弃休明。","离觞未御，夙驾徂征。","瞻望靡及，言以宣情。","鸳鸯在梁，载戢其羽。","昕嬉玉水，夕宿兰渚。","虞者张罗，巧中其侣。","载飞载鸣，东西失所。","永乖形影，隔绝笑语。","岂不尔思，怅望伊阻。","翩翩玄隼，集于高隅。","矜彼腐鼠，逐我鹓雏。","我欲弯弓，畏彼狂且。","玄阴漠漠，雨雪载途。","子之去矣，敬慎尔躯。","清静恬淡，为道之腴。","我友自南，罹谗而逝。","悠悠彼天，而奸是惠。","蒙蒙棘榛，植于阶陛。","如何周道，容此芜秽。","有客有客，先子云迈。","心之烦矣，涕集于袂。","我谓我友，省已靡愆。","彼骄者子，狂言便便。","扃钥不慎，盗将入门。","利口覆邦，彼妇逐贤。","青蝇青蝇，白壁何冤。","是非之原，众所共惛。","如何君子，遽惑谗言。"]},{"t":"梦竹篇三章赠吴孝父","f":"楚辞体","c":["丛丛绿竹，傍渭临淇。","中通外直，露箨风枝。","其人虽往，其竹不移。","瞻望考兮，悠悠梦思。","丛丛绿竹，植于中林。","中林何有，有书有琴。","硕人所处，十亩其阴。","思而不见，梦也是寻。","我思绿竹，于焉游傲。","清风未泯，明月来照。","厥林维贤，厥笋维孝。","匪竹则梦，中心是悼。"]},{"t":"杨园之鹘六章伤贤者被谗去位也","f":"古风","c":["杨园之鹘，集于丛棘。","嗟尔百鸟，胡不深自匿。","君子有行，回车自北。","岂不尔援，畏彼谗慝。","杨园之鸮，集于棘丛。","嗟尔百鸟，胡不深自容。","君子有行，言归于东。","岂不尔留，谗言詾詾。","出宿于郊，饮饯于衢。","前有樽酒，傍有骊驹。","送车二辆，徐徐于于。","载歌载叠，靡笙靡竽。","班荆道侧，过者踟蹰。","送子于河，别子维棘。","畏彼谗慝，为鬼为蜮。","载色载笑，尔亲尔昵。","谗言或或，听言墨墨。","赠言戛戛，送车轧轧。","念我携手，于焉永隔。","子归东吴，庶几善息。","东吴何有，有园有庐，有图有书。","野有桑麻，泽有沮洳。","水事樯楫，陆事巾车。","君子至止，胡以不乐胥。","东吴何有，有陵有阿，有陂有沱。","修竹长林，白芷青莎。","紫笋包橘，菱芡芰荷。","浆酒鲙炙，其乐孔多。","君子至止，胡以不啸歌。"]},{"t":"庚子三月三日再效兰亭体","f":"古风","c":["春芳时暮，景和气融。","轻飙散霭，薄霞被峰。","临川叹逝，出谷吟风。","高揖巢许，远慕乔松。"]},{"t":"芦之水四章","f":"古风","c":["芦之水，不容舠。","炎夏仲月，火云熇熇。","我行无期，仆夫告劳。","虽劳矣，我心则敖。","芦之水，不容苇。","炎夏仲月，火云旆旆。","我行无极，仆夫告瘁。","虽瘁矣，我心则惠。","奉命徂征，适彼王郊。","王郊无毛，室家嗷嗷。","仆夫之劳，犹可敖也。","室家嗷嗷，不可敖也。","奉命徂征，适彼王遂。","王遂如燬，饥人如猬。","仆夫之瘁，犹可惠也。","饥人如猬，不可惠也。"]},{"t":"淇上三章","f":"古风","c":["淇水悠悠，竹竿翛翛。","静言思子，惜无轻舟。","淇水瀰瀰，竹竿离离。","愿言见子，惜无榜师。","既具我舟，亦伐我榜。","方之泳之，将子是访。","滔滔临淇，实劳我思。"]},{"t":"图诗三章八句","f":"古风","c":["图何以椿，穆然孝思。","图何以萱，乐此春禧。","维椿永思，维萱永禧。","谁其寿母，令德攸宜。","维石蕴玉，山则瑞矣。","维水孕珠，川则媚矣。","显允朱生，谁锡尔类矣。","曰其有母，俾尔昌炽矣。","子炽而昌矣，母寿而康矣。","芝函有烨，命服有章。","嘉纶孔彰，嶶音斯扬。","显允朱生，寿母无疆。"]},{"t":"寿颂三章","f":"古风","c":["碧草既菲，朱华载扬。","薰风扇箔，溽露沾裳。","郁郁灵萱，植于北堂。","茂兹永日，式举瑶觞。","瑶觞式举，琴瑟在御。","间以笙簧，杂以宝璐。","綵服有烂，和乐且孺。","锡厥孙子，亦洽宾序。","何以献之，九霞之醴。","曷其侈矣，冰桃玉李。","何以申之，婺星之纪。","曷其侈矣，于西王母。"]},{"t":"三礼诗三首 其一 皇太子册立诗","f":"古风","c":["于昭皇明，十叶惟圣。","引祚自天，敷祐厥命。","百辟是钦，四方是正。","咸建国本，以绥家庆。","帝衍其昌，缵服其光。","载辑人纲，载锡天常。","孝慈用章，福履无疆。","奠丕丕基，以定厥祥。","厥有圣嗣，惟皇元子。","睿聪夙成，令闻蔚起。","天之所置，孰俪懿美。","式灵震器，以享以祀。","如彼玉润，蕴德不瑕。","如彼朝阳，协于重华。","山川鬼神，罔不宠嘉。","凡厥内外，系心靡他。","维昔廷言，冀光大典。","帝命曰吁，天序丕显。","尚其弱龄，学于黾勉。","无庸骤尊，而骄不腆。","乃列坟史，乃翼师儒。","时敏厥修，日新与俱。","群公矢谟，元良在图。","帝命曰俞，万邦作孚。","乃诹礼司，庀是仪服。","乃虔时日，以先太卜。","象辂鸾旌，有贲执玉。","左右视听，百尔祇肃。","釐兹册宝，有穆其容。","践位储贰，俾朝于东。","并建诸王，蕃屏维宗。","覃惠自公，殊方攸同。","济济宫寮，保傅是弼。","既曜春华，亦乘秋实。","诏美导和，庶士维吉。","启以三善，崇以四术。","思皇帝胄，遹骏贻谋。","眷命悠悠，底于千秋。","敬承维夏，继述有周。","矢诗宣猷，以扬鸿休。"]},{"t":"三礼诗三首 其二 皇太子冠礼诗","f":"古风","c":["吉日惟良，命服惟元。","集礼铜龙，烂其盈门。","宫僚肃将，以承前轩。","衮冕有加，其道弥尊。","衮冕峨峨，既曼且硕。","采璂朱绂，瑶契金册。","宠兹成德，圣祖列辟。","式光宗祏，皇心孔怿。","皇醴东朝，训命告釐。","念厥毗倚，淑是令仪。","裕民惟志，寿国惟祺。","睿敏圣嗣，敬德不违。","圣嗣敬德，诞受多福。","霭其如春，式其如玉。","象贤攸属，令终有勖。","作颂孔穆，风言维祝。","厥颂伊何，于际于蟠。","厥讽伊何，慎防其端。","方圆以翊，中正以观。","保兹燕誉，奕世不刊。"]},{"t":"三礼诗三首 其三 皇太子婚礼诗","f":"古风","c":["两仪既定，阴阳斯位。","于皇储圣，惟德是媲。","自天之祐，罔不淳备。","乃启甲观，而登淑懿。","苑桃之华，有烨其光。","馥彼兰宫，达于椒房。","乃登文币，以定厥祥。","元祚其昌，嘉命之将。","德音孔惠，人神作缔。","在妫之汭，在姬之渭。","女史有纪，彤管有炜。","以其良娣，威仪棣棣。","威仪静幽，君子好逑。","佩瑜鸣球，羽葆文辀。","八鸾啾啾，曰闲以柔。","从车如流，归于龙楼。","帝道蕃茂，垂裕厥后。","庆成入奏，左右忭舞。","酌彼醇酬，以其玉斗。","群公稽首，天子万寿。"]},{"t":"寿域诗四章为庄得全编修尊人作","f":"古风","c":["煌煌寿域，光于南斗。","包孕群生，诞锡惟厚。","鸾凰是藩，麟鹿是囿。","碧草朱华，以繁以茂。","南斗之下，是为星沙。","环以绿水，夹以丹霞。","于焉逍遥，其乐孔嘉。","俾尔寿谷，德音不瑕。","南斗之傍，爰开玉堂。","皇降嘉赉，有烂其光。","玉树琼柯，有芬其芳。","俾尔昌炽，德音孔扬。","绵绵星沙，寿域所届。","济济玉堂，寿域所会。","及尔子孙，亦昌以大。","介兹景福，永寿无害。"]},{"t":"太和山铭","f":"古风","c":["穹窿太和，上参冥莫。","近接嵩华，远拔衡霍。","明后有作，是称灵岳。","上帝攸居，天柱是度。","赫赫成后，玄戈再援。","神之相之，用武以断。","穆穆肃皇，中兴江汉。","神之启之，守文以缵。","巍巍天柱，前俯璚台。","层城万仞，上应中台。","地轴盘结，云汉昭回。","灵踪久閟，真路乍开。","爰饰云构，造于中天。","冠峰被麓，舄奕墟躔。","丹碧霞焕，栋宇星悬。","势侔太一，巧极望仙。","神之所妥，钩陈营卫。","鞭风驾霆，出入云际。","神之所临，徵灵表异。","康国阜民，克显于世。","玄圃之峦，仁后所履。","丹丘之屺，仙灵所倚。","咸障大荒，曷窥元始。","追茂至道，孰踰斯美。","惟兹崇报，前掩禅封。","在帝左右，罔或不共。","四气顺序，万方景从。","昭佑我明，受福无穷。"]},{"t":"海棠果赞","f":"古风","c":["海棠色殊，纷披曜日。","不芬其葩，而香其实。","香或掩味，文乃逾质。","园陵之珍，佩充兰室。"]},{"t":"木瓜赞","f":"古风","c":["垂垂木瓜，诗人所咏。","酸本我心，香亦吾性。","人之好我，或忘其病。","无劳琼报，忝此嘉命。"]},{"t":"崇德诗七章","f":"古风","c":["翼翼旧京，作配丰芑。","济济庶士，爰来爰止。","孰茂厥程，硕人君子。","龙潜南国，凤览江汜。","惟此硕人，德音孔硕。","克廉以孝，百行允迪。","爰孚有众，升闻奕奕。","其廉可风，其孝惟则。","人之好名，是能让国。","苟非其人，箪豆见色。","硕人介特，靡诱靡惕。","千金之却，亦在报德。","今之孝者，是谓能养。","不敬何别，菽水非凉。","硕人爱敬，允格穹壤。","终身之慕，亦自少壮。","我闻天道，常与善人。","如种斯穫，靡屈弗伸。","既丰其德，或啬其身。","尔身弗享，爰及后昆。","硕人有子，邦之司直。","在帝左右，罔或不即。","汝明汝听，有孝有德。","用锡帝赉，衍兹世泽。","世泽克衍，先问孔扬。","既显于世，亦祀于乡。","肃肃判宫，笾豆有常。","是依是崇，儒道其光。"]},{"t":"送友人还山歌 其一","f":"楚辞体","c":["君处世兮清穆，忽捐佩兮何促。","风尘灏洞兮不可以久游，返予驾兮初服。","既不理兮多口，复无意兮横目。","思清流兮濯缨，惧迷阳兮伤足。","杨何心兮歧泣，阮何见兮途哭。","揽桂兮崇冈，搴兰兮幽谷。","慕鲁连兮辞侯，钦介推兮逃禄。","君不留兮奈何，拊黄鹄兮高歌。","欲从君兮未得，徒怅望兮岩阿。"]},{"t":"送友人还山歌 其二","f":"楚辞体","c":["羌独处兮无与，君惠顾兮为侣。","佩珊瑚兮脱赠，衣飘飘兮霞举。","君胡为兮空山，捐富贵兮早还。","日黯黯兮将愁，暮君之行兮渺难攀。","朝饮牛兮涧底，夕挂瓢兮松间。","悦白云兮高岭，弄明月兮澄湾。","蹇予步兮夷犹，隔千里兮沧洲。","望山中兮不见，思公子兮多怀忧。"]},{"t":"九望 其一 望瑶台","f":"楚辞体","c":["瑶台兮云浮，菌阁兮蕙楼。","溯赤水兮负玄洲，飞仙遨兮驾苍虬。","星辰朝兮绛阙，日月环兮丹丘。","孔盖兮龙斿，仙之人兮纷纷而来游。","瑶台高兮缥缈，中有人兮丹颜绿发而衣缟。","翳玉芝兮?琅玕，搴若华兮刈朱草。","珠入海而为树，桂逾岭而成林。","尘壒既不可久处兮，夫孰表予之遐心。","将托朱鸟以为媒，又要之以夙好。","朝诣车于雁门，夕弭节于璚岛。","虎骖乘而眈眈，龙服衡而矫矫。","憩落落之长松，涉涓涓之行潦。","聆仙乐于云门，抗飞旌于霞表。","招虞帝于苍梧兮，宾轩后于洞庭。","戛云璈兮瑶佩，披霞帐兮曲璚。","美嘉橘兮秋实，揽桂树兮冬荣。","岁逌逌其将迫，心摇摇如悬旌。"]},{"t":"九望 其二 望天池","f":"楚辞体","c":["天池波兮浩溟溟，日滉漭兮云无晶。","川谷兮东注，地轴兮南倾。","九州浮兮若芥，六合混兮一泓。","焦石沃兮何时竭，大壑纳兮何时盈。","中有神山，随波靡宁。","仙人愁若，诉于帝庭。","帝乃使神鳌兮戴之，若浮沤之暂停。","犹不免兮漂荡，越洪流而南行。","日月出入，星辰晦明。","乾坤沸灪而震荡，又何足喻乎变化之鲲鹏。","将命太一兮为舟，元气兮为楫。","控巨鳌兮驰贝阙，荐波茗兮拾海月。","昔神后既奠夫九土，曾莫顾夫家室。","何仲尼皇皇而乘桴，效渔父之榜枻。","是固吾之所愿，将褰裳兮从之。","惧将至而风引，忽欲往兮中疑。","鲛室兮嵚㕒，珠宫兮逶迤。","仙人下兮光陆离，驾水车兮载云旗。","夕息兮晹谷，朝嬉游兮扶枝。","路超远兮莫致，蹇惆怅兮生悲。"]},{"t":"九望 其三 曰望苍梧","f":"楚辞体","c":["白云游兮苍梧，山连卷兮路崎岖。","日黯黯兮昼多雾，岩㟹嶆兮鬼啸怒。","樛萝蓊郁兮塞往路，我欲从之修且阻。","鶗鴂兮空山，帝子去兮不还。","道远兮何极，不能随之兮泪沾臆。","涉湘皋兮绿潭，悲洞庭兮芳夕。","疏篁兮斑斑，山含怨兮水含忆。","步远冈兮不见，蹇夷犹兮难即。","望苍梧兮白云，隔千里兮思君。","抚瑶瑟兮寄幽怨，采杜蘅兮愁氛氲。"]},{"t":"九望 其四 望八桂","f":"楚辞体","c":["桂树生兮山南，沐玄云兮荫芳潭。","擢修茎兮幽霭，布芳叶兮夕岚。","发华滋兮秋风，翔群羽兮鹓鸿。","既拔萃兮高岭，复灌生兮玄冬。","扬芬兮素节，含贞兮嘉月。","有美人兮伤离，揽岩桂兮为期。","信怀芳兮自保，又久要兮申之。","去不来兮来不采，芳寂寂兮欲谁待。","嘉树茂兮岩间，桂父淹留兮往还。","登楼兮长咏，望八桂兮杳难攀。"]},{"t":"九望 其五 望韶石","f":"楚辞体","c":["予昔扬舲于桂浦兮，将以极夫遐征。","朝发丹水之浛洭兮，夕息重华之所经。","俄穷源于星宿兮，访昆丘之赤城。","天柱岧峣而飞空兮，地轴支撑而不倾。","纷合沓其异状兮，忽神怖而魄怔。","崩腾蹙踏来万乘兮，风雨阴晦而会百灵。","倏天清而地宁兮，聆箫韶之九成。","昔重华之盛德兮，信无远而弗歆。","绝潇湘而南下兮，嘉兹土而来临。","国不费而民不匮兮，兵卫简而不侵。","岂车辙与马迹兮，将釐俗于靺任。","遂乐兹而不返兮，溯南飙而长吟。","璇宫逶迤而下属兮，瑶台隐起而上寻。","驻清跸于磐石兮，招炎景于茂林。","参差九韶之管，疏越五弦之琴。","趋跄百兽之舞，来仪丹羽之音。","黼裳飏兮仙霞举，绛节去兮赤霄沉。","太音寥泬其希声兮，遗迹峥嵘而可睹。","信帝德之巍巍兮，有天下而不与。","留仙旆于九疑，怨瑶瑟于二女。","松谡谡而吟风，竹斑斑而含雨。","表灵兮珠丘，极望兮澧浦。","杳翠旗兮不见，荐芬馨兮何所。","钦明兮思君，闻乐兮愁予。","嗟南薰之久寂兮，民愠其谁与解之。","皇风靡而世遂季兮，俗化淫哇而嗤嗤。","久知太音之难谐兮，唐虞既远安适归。","将坐兹石而忘味兮，写予心之遥悲。"]},{"t":"九望 其六 望合浦","f":"楚辞体","c":["遥睇兮重渊，波光兮接天。","美珠官兮风俗，灿贝阙兮鳞联。","川炯炯兮圆流，星奕奕兮辉躔。","骊何抱而自喜，玑何胎而罕全。","愚何剖而忘身，圣何捐而称贤。","鲛人兮水中，渊客兮龙宫。","孰感恩兮涕泣，乃吐月兮朣胧。","?灵蛇兮剖玑鳖，间翠羽兮错珩璁。","君子杂之以为佩，佳人待之而修容。","夫何世俗之贵鱼目兮，弃夜光而不采。","岂忍夫怀宝而迷邦兮，握照乘而自晦。","终惧世之不察兮，訾径寸以微颣。","虽怀宝其何辜兮，独被褐之见罪。","潮生兮犀浦，月出兮贝屿。","弦望兮有时，藏珍兮自妩。","激天吴兮命海若，木兰舟兮沙棠橹。","访鲛室兮从之，蚌鳖纷纷兮媵予。","惧轻投兮按剑，将采之兮谁与。"]},{"t":"九望 其七 望石室","f":"楚辞体","c":["石室处兮炎方，越湘浦兮迈衡阳。","气巃嵷兮幽暧，洞熑焰兮扬光。","厓廞?兮?蜷，凝苍翠兮若英。","耸峻坂兮㠍嶪，错绮薄兮芬芳。","窅兮谷石碌䃚，岩桂灌生兮山之曲。","深兮穆盘径复，舞鸾皇兮嬉玄鹿，皋兰秀兮纷相馥。","琼为宫兮玉为梁，罗孔囿兮开龙堂。","蓂砌兮荪壁，木兰橹兮芝房。","石室兮巍峨，芳湖汇兮水曾波涨。","极浦兮丰芰荷，泛曲塘兮茂青莎。","绝霞岛兮绕岩阿，洄翠屏兮镜藤萝。","独处兮无侣，芳时兮谁与。","君奈何兮远游，望湖光兮渺何许。","采杜若兮芳洲，结锦缆兮金屿。","心欲往兮耽耽，托归风兮鸾骖。","待菌阁兮月华，沐天柱兮夕岚。","搴朱草兮瑶圃，漱金液兮霞举。","朝税驾兮东皋，夕次兮北渚。","乐岩壑兮憺忘归，蹇夷犹兮不能去。"]},{"t":"九望 其八 望崧台","f":"楚辞体","c":["有崇者冈，赫若台兮。","巑岏崚嶒，丰而皑兮。","上接云汉，章昭回兮。","下列盘洞，户重开兮。","怪石嵯峨，光的皪兮。","峰峦群峙，挺千尺兮。","青岫黛岑，渺难即兮。","鸟道纡回，不可陟兮。","员屋瑶台，辉金碧兮。","玉磴珠戺，芝兰藉兮。","璧英明珰，光相射兮。","厒隒急辚，暝烟积兮。","玉窦奁空，螭龙宅兮。","石栊嶙峋，多采择兮。","琼木纷敷，僷奕奕兮。","猿狖群嗥，谷鸟唶兮。","博敞孔阳，游羽客兮。","纫兰搴蕙，服侧柏兮。","孔盖翡帷，带凫舄兮。","森耸崭岩，得所适兮。","结桂延伫，中心怿兮。","崧台峨峨，乐而无极兮。","崇朝凝望，至日夕兮。"]},{"t":"九望 其九 望西樵","f":"楚辞体","c":["山崛起兮海湄，复回薄兮云际。","见千里兮平皋，挹四郊兮芳霭。","出厚地兮百盘，挂青天兮片黛。","溪谷兮多姿，朝昏兮殊态。","日出兮䆗窱，波泛兮容裔。","灵穴兮吟风，幽林兮积翠。","曾结庐兮几客，横荒涂兮千载。","披阴阜兮吐霞，升阳崖兮迎旭。","忽云中兮鸡犬，更天边兮乔木。","巅积水兮可艇，涧连村兮比屋。","交远皋兮茶烟，若有人兮卉服。","幸不游兮豺虎，差可方兮麋鹿。","媚林麓兮返照，喧阶除兮乱瀑。","飞瀑下兮湿云，径凝烟兮不分。","鸾鸿归兮山响，菌桂发兮林芬。","灌尧韭兮九节，挺仙使兮一群。","三山渺兮难即，十洲恍兮空闻。","岂若近兮几席，况乃接兮榆枌。","山中人兮来何迟，抚云松兮望所思。","岁复岁兮不可待，年复年兮滞还期。","秋风歇兮蕙若，春雨长兮蕨薇。","胡长违兮涧户，永阒寂兮岩扉。","命芝童兮翳芝盖，邀桂父兮扬桂旂。","誓永绝兮氛垢，从天路兮薄言归。"]},{"t":"东征诗 其一","f":"楚辞体","c":["皇赫怒兮定夷乱，壮士奋兮不遑宴。","横长戟兮箙劲箭，组甲耀兮星辰焕。","蹴溟渤兮波涛晏，倚长剑兮扶桑岸，四极奠兮鳌足断。"]},{"t":"东征诗 其二","f":"楚辞体","c":["皇灵震兮穷海外，征不庭兮静殊类。","甲旅悦兮从公迈，封鲸鲵兮戢鳞介。","加日出兮极地界，标穹碣兮际荒裔，异域来兮嘉王会。"]},{"t":"臬长李公之堂有雉忽来驯扰若家鸡数日后锦羽焕烂此治世文明之象异类驯服之符也一时缀文之士咸作诗侈其事予遂为歌歌曰","f":"楚辞体","c":["雉朝飞兮下公堂，时饮啄兮来山梁。","驯柏台兮扰车傍，性耿介兮体文章。","无重译兮致越裳，德泽加兮仁风翔。","嘉瑞荐兮贶穹苍，公辅政兮帝道昌。"]},{"t":"马上见宫燕回翔感赋一字起九字止","f":"古风","c":["燕，于飞。","入绣幕，出香帏。","御林拂拂，宫桃绯绯。","晓临金屋舞，夕傍玉楼依。","婀娜多情恋主，差池新恨沾衣。","云间尺素缄长别，芳草王孙怨未归。","年年见尔红襟如旧，岁岁逢人黑发渐稀。","故园花树已度今春晚，后院壶觞莫教他夕违。"]},{"t":"悯潦三章端民歌王兵宪宗鲁也余为广其辞焉 其一","f":"楚辞体","c":["洪潦汤汤兮毒吾州，地维圮兮乱常流。","霪雨助虐兮溢原野，飘室庐兮灌城社。","水不仁兮民为仇，潦不止兮君侯忧。"]},{"t":"悯潦三章端民歌王兵宪宗鲁也余为广其辞焉 其二","f":"楚辞体","c":["潦不止兮奈何，日惨晦兮雨滂沱。","燕雀东西兮失其故处，蛟龙矫矫兮水府失驭。","薪竹兮易竭，望尾闾兮难泄。","嗟洪流其何以，底定兮民将为鱼，非君侯兮吾安得平土而居。"]},{"t":"悯潦三章端民歌王兵宪宗鲁也余为广其辞焉 其三","f":"楚辞体","c":["往见侯兮，熊车戾止。","今见侯兮，短衣敝屣。","短衣敝屣兮为吾民，手足胼胝兮焉知其勤。","吊洪流兮汗漫，侯之治水兮心力殚。","芬芳兮椒浆奠，水府兮闷闷。","发禁旅兮登城陴，民之颠溺兮忍其弗持。","载糗饵兮食其饥，上帝怒兮叱水府。","杀湍流兮宅南土，江河晏兮来万祜。"]},{"t":"赋得文杏梁 其一","f":"古风","c":["文杏梁，卢妇郁金堂。","下临玉池水，双栖紫鸳鸯。","春风杨柳堤，堤前步步得相将。"]},{"t":"赋得文杏梁 其二","f":"古风","c":["文杏梁，赵女昭阳殿。","绮闼十二重，琼檐语双燕。","春风桃李花，花前岁岁还相见。"]},{"t":"莫愁湖曲 其一","f":"五言绝句","c":["湖上烟花暝，湖中丝管催。","木兰双桨在，何处莫愁来。"]},{"t":"莫愁湖曲 其二","f":"五言绝句","c":["荡漾芙蓉花，惊出鸳鸯鸟。","芳湖明月曲，吹送吴天晓。"]},{"t":"莫愁湖曲 其三","f":"五言绝句","c":["碧水似开镜，远山如画眉。","岸花凝笑脸，堤柳斗腰肢。"]},{"t":"莫愁湖曲 其四","f":"五言绝句","c":["借问卢家女，佳名是莫愁。","不知秋别恨，何处上心头。"]},{"t":"思归引","f":"五言绝句","c":["惜别奈远别，思归犹未归。","近来容鬓改，应为信音稀。"]},{"t":"秋闺曲","f":"五言绝句","c":["玉杵捣清霜，银筝冷洞房。","谁言关路远，频使梦渔阳。"]},{"t":"鸡鸣曲","f":"七言绝句","c":["洞房春梦潇湘沚，香雾濛濛湿江水。","几度相思不见君，鸡鸣杲杲生红云。"]},{"t":"上之回 其一","f":"五言律诗","c":["诏书下汉宫，天子向回中。","羽卫临边静，山川驻跸雄。","前军抵代北，后骑属河东。","归及长杨殿，誇胡更射熊。"]},{"t":"上之回 其二","f":"五言律诗","c":["三时方耀武，万乘以戎行。","雪花随玉辇，云叶捲龙旌。","大狩长榆塞，劳军细柳营。","莫拟瑶池宴，终留八骏名。"]},{"t":"关山月 其一","f":"五言律诗","c":["长风吹海月，来向玉关明。","及此登楼望，应多出塞情。","阵云含晕缺，战马傍轮鸣。","莫问刀头事，长榆更远征。"]},{"t":"关山月 其二","f":"五言律诗","c":["关山今夜月，寥落远征人。","塞上重圆缺，边头多苦辛。","愿随冰雪影，一照绮罗春。","中妇念离别，娥眉几度颦。"]},{"t":"青楼曲","f":"五言古诗","c":["新莺啭画堂，新燕集雕梁。","柳叶裁眉出，桃花学面妆。","珠帘映日捲，锦袖随风扬。","大道连平乐，高楼接建章。","容华艳阳月，夫婿侍中郎。","挟瑟调鹦鹉，将箫待凤凰。","朝回欲有问，轩骑满东方。"]},{"t":"和黄汝纶春情篇","f":"五言古诗","c":["帝京行乐好，霁景媚韶光。","南陌紫骝骑，东邻红粉妆。","夭桃间秾李，芳草映垂杨。","调雪成歌曲，排云出舞行。","花前宁辨色，衣后转闻香。","弦管故情在，关山春恨长。","若非京兆妇，定是邯郸娼。"]},{"t":"赋得巫山高","f":"五言律诗","c":["巫山上半空，遥接楚王宫。","岩影朝云上，猿啼暮雨中。","锦屏千丈瀑，芳树万年丛。","灵异信如此，高唐梦未通。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马骊。","二马虽共逐，臣马驱以驰。","走灭没，出权奇，谁当产者渥洼池。","踰昆崙，度月支，谁当相者孙阳师。","珊瑚宝勒黄金羁，桃花锦障光陆离，路傍照耀幽并儿。","君马吉行三十里，臣马前驱为君死。","千金台上未为恩，一顾尘中岂徒尔。","不辞四蹄践霜雪，西走咸阳东辽水。","战罢初归玉塞群，功成更服天闲驷。","却笑周家八骏蹄，徒向瑶池御天子。"]},{"t":"采莲曲 其一","f":"五言绝句","c":["锦袖清川曲，红妆绿水洲。","可是怜孤棹，时时出并头。"]},{"t":"采莲曲 其二","f":"五言绝句","c":["妆成翻自爱，临水照娥眉。","荷筒误攀折，撩乱不成丝。"]},{"t":"采莲曲 其三","f":"五言绝句","c":["荷花与人面，相对两相疑。","歌声人未觉，白鹭已先知。"]},{"t":"采莲曲 其四","f":"五言绝句","c":["别浦千花暝，回舟一水香。","停桡休更折，留著伴鸳鸯。"]},{"t":"古有所思","f":"楚辞体","c":["我所思兮大海南，何以致之紫云缄，青瑶为字金作函。","波涛万里不可涉，白日忽破扶桑岚。","我欲乘龙，龙不我骖。","我欲附青鸟，青鸟不我衔。","将泪滴海水，为我流入明珠潭。","我既无羽翼，君亦一去无消息。","从今勿复思，相思何终极。","堂前琼树枝，把君旧颜色。","携手高台复几时，君在天南我天北。"]},{"t":"相逢狭路间","f":"五言古诗","c":["美女耀阳春，使君朝紫宸。","相逢当狭路，相见在芳晨。","高髻图云出，纤眉写月新。","瑶光凝粉脸，丹彩发朱唇。","再顾倾城国，争看匝路人。","束腰垂柳陌，转袖落花津。","尊贵何劳问，行游别有因。","容颜诚绝代，礼法善周身。","障面移轻扇，回车度急轮。","珂声连玉佩，衣带接香尘。","采菉娇淇水，登桥艳洛滨。","何须云雨夕，始见阳台神。"]},{"t":"西湖春游曲 其一","f":"五言古诗","c":["青萍照绿芜，细柳漾新蒲。","翡翠金堤并，鸳鸯玉水俱。","时逢湘浦驾，来弄汉皋珠。"]},{"t":"西湖春游曲 其二","f":"五言古诗","c":["春和日载阳，春思复多伤。","野色含朝霭，流文荡晓光。","游心不自已，步步惜时芳。"]},{"t":"西湖春游曲 其三","f":"五言古诗","c":["人行丹嶂里，鸟度绿芜中。","烟雾藏春寺，湖山绕故宫。","兰叶搴犹短，花枝折未空。"]},{"t":"西湖春游曲 其四","f":"五言古诗","c":["湖镜何曾拭，山眉本自舒。","叶稠初隐鸟，花落乍惊鱼。","自有淩波步，回看掷果车。"]},{"t":"西湖春游曲 其五","f":"五言古诗","c":["上路填车马，中流沸管弦。","折花伤玉手，照水落金钿。","及此芳春日，俱宜妙丽年。"]},{"t":"西湖春游曲 其六","f":"五言古诗","c":["银鞍驰白马，玉轭驾黄牛。","来往红尘陌，嬉游绿水洲。","莺啼喧桂席，鱼戏动莲舟。"]},{"t":"西湖春游曲 其七","f":"五言古诗","c":["宝袖拭琼箫，金妆隐翠翘。","衫长风袅袅，钗重步摇摇。","鸣佩游三竺，回镳度六桥。"]},{"t":"西湖春游曲 其八","f":"五言古诗","c":["燕巢知岁别，莺语识年华。","独坐闲调瑟，明妆出浣纱。","春风日暮起，愁杀上湖花。"]},{"t":"西湖春游曲 其九","f":"五言古诗","c":["青阳既荡渭，绿水复盈淇。","有女怀春出，容颜不可思。","流光一抛掷，沉叹返空帷。"]},{"t":"与坐客咏席上所见效小庾体十一首 其一 咏砚","f":"五言律诗","c":["娲工呈练彩，孔石琢圆方。","以我紫云片，登君白玉堂。","凿池分月影，披露扬星光。","永持坚润质，游心文史场。"]},{"t":"与坐客咏席上所见效小庾体十一首 其二 咏酒卮","f":"五言律诗","c":["华堂宵宴启，金卮上寿行。","斟酒奉兰席，提携随玉瓶。","送意只愁浅，含情同一倾。","且愿开涓滴，为君解宿酲。"]},{"t":"与坐客咏席上所见效小庾体十一首 其三 咏骰盘","f":"五言律诗","c":["玲珑捧玉手，错落出雕盘。","含采分投易，连呼急转难。","良夜宴未毕，行乐美无端。","虽非百万掷，聊以奉君欢。"]},{"t":"与坐客咏席上所见效小庾体十一首 其四 咏香","f":"五言律诗","c":["珍木产南国，芬馨上北堂。","幸同微火用，常共好风扬。","百和凝花阁，双烟出洞房。","倘陪明德荐，随地可留芳。"]},{"t":"与坐客咏席上所见效小庾体十一首 其五 又咏","f":"五言律诗","c":["百花妆阁晓，一炷绣帘飞。","作佩充兰室，承薰入舞衣。","每从海尉至，常护汉郎归。","立近御炉侧，青烟接紫微。"]},{"t":"与坐客咏席上所见效小庾体十一首 其六 咏香炉","f":"五言律诗","c":["斑升翡翠点，杂用金银涂。","诡制侔周鼎，奇形出汉模。","翠翘案上拂，鸳被帐中需。","终宴含香侍，兰烟飘座隅。"]},{"t":"与坐客咏席上所见效小庾体十一首 其七 咏烛","f":"五言律诗","c":["西楼淹夜饮，东壁暧清光。","楚宴缨休绝，燕庭书作行。","龙衔疑却月，莲吐半凝香。","不是风欺焰，佳人舞袖长。"]},{"t":"与坐客咏席上所见效小庾体十一首 其八 又咏","f":"五言律诗","c":["洞房恋夜色，银箭起更筹。","影乱弹棋席，光多教舞楼。","花生应待喜，泪落不关愁。","未上西园月，偏能美夜游。"]},{"t":"与坐客咏席上所见效小庾体十一首 其九 咏烛台","f":"五言律诗","c":["铜荷叶下盖，金芝茎上盘。","枝发九龙燄，花高四座看。","明心投分易，承泪觉离难。","还持不自照，侍君罗帐欢。"]},{"t":"与坐客咏席上所见效小庾体十一首 其十 咏屏风","f":"五言律诗","c":["锦屏罗广座，曲曲似巫峰。","灯映琉璃净，堂开云母重。","看花围蛱蝶，学舞障芙蓉。","多是云将雨，朝暮会相逢。"]},{"t":"与坐客咏席上所见效小庾体十一首 其十一 咏琵琶","f":"五言律诗","c":["旧时马上声，今向席间鸣。","花月意恒满，关山恨暂平。","芳尘萦袖出，纤指逐弦清。","莫以别离曲，来承欢宴情。"]},{"t":"淮浦吟","f":"五言古诗","c":["幸免黄河险，复阻清淮流。","南风十日发，不见北来舟。","南船疾如马，北船不得下。","天道何时平，风便往来者。","淹泊清淮浦，怅望丹水涯。","狂风吹我舟，不得早还家。","晨起望佳人，日入未遑息。","白云苍梧间，是我心所忆。","虽有纨与绮，不如故时稀。","虽有新相知，不如故所思。","征夫念闺人，非为颜色好。","游子恋故乡，非关万里道。","黄鹄翔天风，千里不可乘。","安得东南翮，送我至广陵。","广陵非还家，行子暂栖泊。","稍缓旅人愁，非贪估客乐。","淮南多桂树，何似故山北。","广陵好风月，何似故乡陌。"]},{"t":"归?川作","f":"古风","c":["平畴秀嘉卉，高堰递细涓。","烟火桑柘外，渔钓竹林边。","萝径绝洒扫，风磴乍攀援。","云霞薄樵岭，花木明?川。","插槿护颓墉，激涧泻鸣弦。","夕圃摇佳蕙，遥林生晚烟。","田父四五辈，问讯丘中缘。","壶觞有深趣，兼无章绶牵。","抱瓮钦丈人，岩耕俪昔贤。","兹水洵乐矣，吾归将老焉。"]},{"t":"东鲁豪士行","f":"五言古诗","c":["门有万里客，不剑亦不琴。","手持漶灭刺，欲语泪先淫。","家本东鲁儒，豪举世难任。","游戏孟诸野，射猎峄山岑。","徒手殪猛虎，仰面接飞禽。","十五学孙吴，出身为羽林。","曾随汉车骑，逐虏塞垣阴。","勇略颇自许，意气人所钦。","一朝时事改，避难五溪深。","是时戈船将，十万靖南侵。","攘臂千夫长，捐躯百战临。","论功无分寸，谗害复相寻。","廿载事戎行，家远绝信音。","笑谈皆按剑，勋业遂泥沉。","丈夫赴国难，肯负平生心。","桑榆幸未晚，壮图希自今。","暂辍南征曲，为君东武吟。"]},{"t":"咏苏门","f":"五言律诗","c":["阮公天性逸，傲睨出风尘。","长啸入苏门，遇此异代人。","世事了不答，终古徒自陈。","意尽还山半，清音流涧滨。"]},{"t":"咏漆园","f":"五言律诗","c":["傲吏战国士，著书漆园里。","遭时厌有为，乘运观无始。","礼乐嘲鲁儒，垂钓谢楚使。","托迹方外民，希心柱下史。"]},{"t":"咏濠梁","f":"五言律诗","c":["庄生本旷达，惠施亦多方。","辨囿入芒渺，鱼乐且徜徉。","非鱼复非我，此中意何长。","斯人诚已矣，千载但空梁。"]},{"t":"咏琴台","f":"五言律诗","c":["汉代论才子，相如秀孤骞。","日暮高台上，临风挥朱弦。","疏梧照古月，密竹生秋烟。","去今已千载，流水尚依然。"]},{"t":"客至弹琴","f":"五言古诗","c":["有客把瑶琴，向我中林坐。","兀然发清音，萧瑟松泉和。","泠泠石上挥，流风激四座。","玄云千里至，皎月怀中堕。","妙曲感人心，幽听忘余卧。","朱弦幸未绝，花晨倘相过。"]},{"t":"大寒后写怀","f":"五言古诗","c":["靡靡西颓光，何时燠寒灰。","槁木无生意，宁知春事回。","龙蛇蛰已深，松柏日见摧。","冰霜满天地，欲往谁为偕。","飘飘南雁逝，声响一何哀。","我欲致此鸟，因之托中怀。","惜哉无羽翼，凝睇以徘徊。"]},{"t":"蠲愤","f":"五言古诗","c":["贫贱难久居，勋业惧晚成。","老骥志千里，达士感河清。","翩翩当衢客，青云耀冠缨。","如何穷愁子，终岁忧患婴。","拔剑欲出门，我剑悲且鸣。","长路脂吾车，路险车轴倾。","惊飙号垄树，穷猿多哀声。","寒江日夜逝，焉知游子情。","在贱常思贵，处约常愿盈。","人理苟如此，天运安得平。","沉晦非我致，俟命何所营。"]},{"t":"经越井冈寻黎惟敬秘书旧隐","f":"五言古诗","c":["华林蔽崇巘，金塘罢兰枻。","曲巷屡回车，纡径枉往辙。","重来几何时，暂至不复别。","燕雀虚堂归，松萝四邻阅。","图书两三卷，茅屋八九折。","抚化心已凄，衔知顿情竭。","伊昔与斯人，定交于晚节。","投分既忘年，对酒常累月。","觞酌方未已，世路忽羁绁。","临别深久要，揽涕即长诀。","芸阁访旧德，麟园钦前哲。","身退物不迕，调孤道逾洁。","凤览夫子志，虫雕馀儿悦。","人伦藉芳誉，物览清洞澈。","已矣故交欢，怀中字不灭。","衣冠王气孤，风雅微言缺。","玉树想平生，石泉效幽咽。","山阳既恸吕，雍门亦悼薜。","玉轸久不挥，冰弦痛欲绝。","三叹奉遗音，斯理谁与说。"]},{"t":"醉后东轩听琴","f":"五言古诗","c":["把酒东轩下，颓然醉前林。","美人倚脩竹，自发山水音。","锦袖流逸响，朱弦表贞心。","弹罢三叹息，日暮湘云深。","感君绿绮意，欲报惭南金。","顾惟白雪唱，可叶幽兰吟。"]},{"t":"陪欧桢伯集黎惟仁对江楼 其一","f":"五言古诗","c":["高楼瞰江澳，廛市分错居。","列岫深后户，宿莽积前除。","林野旷余望，隐几凌高虚。","参差见云木，远近散鹥凫。","是日天气柔，微风荡轻裾。","令德会良朋，绮言唱华腴。","无为钟鼎贵，茶瓜良有馀。","章绶岂不荣，哲人返其初。","青霞挹我袖，黄鹄为君舆。","列坐饮美酒，安能复拘拘。","投分欣有托，税驾从所如。"]},{"t":"陪欧桢伯集黎惟仁对江楼 其二","f":"五言古诗","c":["春晚气和燠，延眺凭高步。","层轩面芳洲，交窗临广路。","近浦百花飞，遥空一禽度。","云涯隐樯楫，沙岛淡烟雾。","波荡鸥群轻，潮落钓矶露。","千觞不停挥，孤琴欣所遇。","调谐金石契，气霭兰言吐。","既酬翰墨情，亦协江湖趣。","终虞饥渴驱，丘壑乖余慕。"]},{"t":"首夏濠上呈黎惟仁","f":"五言古诗","c":["蔼蔼青阳暮，赫赫朱夏初。","春荣既飙逝，炎景亦微嘘。","门巷罗灌木，左右带清渠。","叶密翳鸣蜩，萍开戏跳鱼。","此时蓬蒿人，揽卷惜居诸。","扫径期求羊，耦耕待溺沮。","小技呈蝌蚪，大器愧璠玙。","徒慕任公钓，独守班生庐。","闻君卧南郭，遂与世情疏。","蚤结云霞想，备得金庭书。","愿分白石髓，携手青龙车。"]},{"t":"答陈梦觉隐君","f":"五言古诗","c":["庄周钓濮上，陈平隐负郭。","汉业尚未兴，楚相反见薄。","我本岩居子，穷元探虚廓。","至理谅无遗，中情惧斯怍。","时有上代人，投我以金错。","挟术以屠龙，携经如相鹤。","长啸入青云，抽毫绚朱雘。","聊持冰雪姿，永肩泉石约。","卒岁以优游，斯言当领略。"]},{"t":"经锦石山作","f":"五言古诗","c":["西行至锦石，兹山何巑岏。","上有千花树，照耀紫云盘。","人传汉陆生，奉诏日南端。","片语下南越，千金入长安。","赵主降黄屋，粤俗为衣冠。","使还至此山，云锦绕层峦。","百万秦戍卒，三千汉材官。","铜标绝炎塞，横海泛波澜。","时来片语易，事去六师难。","功成在龙奋，名立附云翰。","志士不偶时，终古为悲酸。","仍闻桂江水，上接乌蛮滩。"]},{"t":"赠七弟 其一","f":"五言古诗","c":["哲士怀远略，乘时册天府。","朝从布衣游，薄暮饰簪组。","遭逢岂不奇，契稷良自许。","蹇余实蒙昧，于世寡俦侣。","中岁偕令弟，比肩事明主。","大册承天颜，崇班簉鹓羽。","溯彼原鸰篇，匪曰但禦侮。","馥馥泽中兰，众草岂其伍。","懿兹王者香，贻来美人所。","昔也产幽谷，今焉发瑶圃。","所愿我同心，勋名茂鼎吕。"]},{"t":"赠七弟 其二","f":"五言古诗","c":["烨烨三株树，托根在层城。","上巢朱凤侣，下荫玉池清。","醴泉灌其侧，彩云曜其英。","岂无桃李花，懿此同根生。","昔我游上国，子亦复北征。","何期知己遇，乃协孔怀情。","骅骝方驾疾，鹓鷟共枝鸣。","穷达会有时，所宝在荣名。","携手天路遥，期子扬徽声。"]},{"t":"赠四兄 其一","f":"五言古诗","c":["桓山有四鸟，栖息同一枝。","飞鸣自相应，饮啄亦相随。","伯也忽先殂，仲氏念将离。","羽翼各自远，声影一何悲。","揽衣三叹息，觞至不能挥。","愿逐南云翔，送子返故栖。"]},{"t":"赠四兄 其二","f":"五言古诗","c":["昆山有良璧，连城剖见珍。","投君君不宝，委置同沙尘。","和氏既泣楚，蔺生复辞秦。","光辉常夜发，声价动强邻。","圣代饰瑚琏，胡弃清庙宾。","徒令被褐客，掩抑情不申。","愿言勿轻掷，识者需其人。"]},{"t":"同七弟送四兄于彰义门 其一","f":"五言古诗","c":["二弟送兄返，停车彰义门。","车傍有鹡鸰，摇摇复在原。","岂为急难故，当由恋孤鶱。","羁人滞远道，游子念故园。","纤纤城畔草，聊用藉芳樽。","柳条时自短，何以系南辕。","鸿鹄绝四海，不顾丘与樊。","大鹏徙南溟，斥鴳有遗言。","兄乎振六翮，天池共奋翻。"]},{"t":"同七弟送四兄于彰义门 其二","f":"五言古诗","c":["杖策去乡国，结轸游皇畿。","王事有兄弟，驷马驱以驰。","忆昨三珠树，五云曜奇姿。","如何同林羽，中路相背飞。","弟在天北隅，兄还日南陲。","燕越万馀里，山川阻修岐。","昔游共被至，安得同车归。","翩翩朱凤侣，巢在南园枝。","永言扬好音，慰我长渴饥。"]},{"t":"董玄宰太史席上送朱君采舍人","f":"五言古诗","c":["西颢澄夕爽，朋簪聚华宴。","置酒宫树侧，别我凤池彦。","秋阴递城阙，寒吹横郊甸。","河柳半萧疏，汀葭已淩乱。","飒飒鸣风条，离离度云雁。","燕云驰蓟丘，楚江望吴岘。","忆我二三友，召对蓬莱殿。","抗言云汉表，意气人所羡。","骑出紫骅骝，挥鞭若流电。","及此秋风期，落叶倏焉散。","虽阻芸阁欢，乃惬萱闱恋。","同袍美昼游，之子去乘传。","勋业当茂龄，荣华岂绅弁。","寄言买臣者，无忽昔贫贱。"]},{"t":"送刘比部玄子往江北 其一","f":"五言古诗","c":["严装候晨发，仆御戒修途。","我友远行迈，驾言适旧都。","旧都勿久滞，祇役在诞敷。","馀封带灊霍，高澨出淮徐。","左顾洪河流，右瞻陵庙纡。","旷望极原野，白露殒平芜。","山川邈悠哉，荏苒岁华徂。","岂不念离析，王事有驰驱。","登车遵大路，执手城南隅。","愧彼双黄鹄，奋翅淩高衢。","誓当复早旋，要盟恐常虚。","风霜厉南陆，慎尔千金躯。"]},{"t":"送刘比部玄子往江北 其二","f":"五言古诗","c":["弱龄诵书史，即慕黄与羲。","谓由画象理，便可契希夷。","如何三叔世，法令日繁滋。","皇风久云歇，贞度亦已隳。","昔与子同舍，始识金科词。","虽则太平术，无乃德义亏。","勿喜轸余念，钦哉慎尔规。","衔章缉往宪，执狱噬前疑。","愿子崇明德，苍乳有遗讥。"]},{"t":"代陶渊明九日闲居","f":"五言古诗","c":["昨者远游归，田园守旧耕。","冉冉老将至，于世复何营。","时来嘉令节，悦我迟暮龄。","众卉承露萎，孤松冒霜荣。","木落远峰峻，潦止寒流清。","岁寒知物变，壮图令心惊。","萸为辟恶佩，菊有遗世情。","既感川上叹，亦肥嘉遁贞。","事往勿复道，觞至可尽倾。","俯仰衡门士，聊以毕吾生。"]},{"t":"白雪吟","f":"五言古诗","c":["凝华转寒姿，芳菲已盈瞩。","朝蔼承明望，夕送宜春目。","双阙递瑶光，连山隐平陆。","因风高下起，入牖联翩续。","琴奏俪幽兰，歌声杳黄竹。","迷陇饥兔奔，点树宫鸦宿。","已便高士卧，颇映幽人读。","阳春如有情，徘徊恋终曲。"]},{"t":"新春自述","f":"五言古诗","c":["芳郊绿未满，御河泉已新。","乔木变初鸟，轻澌戏早鳞。","游冶逐芳辰，车马驰要津。","通城罗第宅，夹道列华裀。","我本穷乡士，远游谢亲宾。","谬随金闺彦，三见燕草春。","所惭尺寸朽，雨露负皇仁。","丹铅理薄技，青云思致身。","耻学繁华子，争妍桃李尘。"]},{"t":"君子有所思行","f":"五言古诗","c":["晨出蓟北门，顾望黄金台。","高台亘层云，照耀五城开。","骏骨没已久，昭王安在哉。","驱马往从之，中涓难为偕。","台下谁家子，骎骎逝龙媒。","金鞭摇白日，玉蹄起红埃。","踯躅霸图尽，驱驰王运回。","怀思不能去，日夕悲风来。"]},{"t":"和刘玄子白发篇","f":"五言古诗","c":["白日忽西匿，寒飙号北林。","闻君白发叹，使我涕横襟。","昨日鬒如云，飞蓬今始临。","自匪乔松质，晚暮谁能禁。","红颜弃我去，素鬓来相寻。","岂缘积损至，无乃多愁侵。","拔去还复延，染之不得黔。","居常羞览镜，入朝愧华簪。","老马怀长路，烈士悲壮心。","毋以桃李姿，薄彼桑榆阴。"]},{"t":"感昔篇答友人","f":"五言古诗","c":["昔年十四五，意气无与比。","富贵不关心，功名何物是。","经过紫陌场，被服纨与绮。","清阳既婉如，侠烈性复尔。","阳春二三月，游戏出都市。","臂鹰草泽中，调马垂杨里。","黄金结壮士，白璧投媚子。","行乐苦不足，明岁复如是。","二十始学书，三冬足文史。","来观上国光，幸免下流耻。","被酒干人事，赋诗良自喜。","未觉世途艰，安见流光驶。","蹉跎及兹辰，弱龄逼强仕。","心长发奈短，素丝渐垂耳。","览镜非旧容，逢人羞问齿。","芳时不再至，壮心讵能已。","明当携少年，射猎西山址。"]},{"t":"新秋瀛洲亭上论学","f":"五言古诗","c":["金飙肇凉气，玉水涵秋霁。","华叶未随风，绮苔尚盈砌。","环流太液波，侧泻御沟汭。","危槛瞰澄瀛，周垣属云陛。","仰视孤鸢翔，俯察纤鳞逝。","蔼蔼玉堂宾，济济衣冠会。","瑶函抽妙义，银钥发清閟。","意入道源深，境寂玄关邃。","清泠涤我襟，夕爽飘吾袂。","逝川无息流，羲御不停辔。","请事颜公言，永怀隰朋愧。"]},{"t":"赠焦弱侯修撰使大梁","f":"五言古诗","c":["袅袅青梧枝，结根缘高冈。","兰生丛薄中，馨香随风扬。","惟昔与吾子，嬉游翰墨场。","早朝趋建礼，晚沐出长杨。","饮我以醇酒，示我以周行。","佳言比弦韦，佩之充明珰。","今晨念远别，揽衣起徬皇。","车徒将入洛，文赋已游梁。","征马思长路，栖凫怨孤颃。","念当从子逝，翮短不能翔。","南陆鹜修轸，良会安可常。","改途陟嵩少，为我吸玉浆。","倘逢三花树，采采莫相忘。"]},{"t":"赠庄得全太史使西越","f":"五言古诗","c":["别离良不易，兹别何煌煌。","车徒盛意气，衢路生辉光。","执手一相送，送子玉河阳。","玉河清且涟，中有双鸳鸯。","嬉游萍藻间，将举更回翔。","将举欲何之，云涉江与湘。","风云开赤社，玉节淩朱方。","朝游苍梧侧，暮宿丹水傍。","但言皇泽远，宁恤道里长。","弦歌未终宴，仆御已严装。","宵人竞荣宠，君子慎周防。","归途倘见忆，为采秋兰芳。"]},{"t":"赠黄汝纶","f":"五言古诗","c":["汝纶淡荡人，白首困章句。","为文拟送穷，作赋悲不遇。","昨来客长安，稍枉故人步。","时贵无所谒，囊空亦已屡。","未蒙布衣召，且罄壶觞趣。","今晨别我去，掉臂不肯住。","千金谁鬻伎，五石君浮瓠。","岂无国士心，终鲜尘埃顾。","缔交二十载，俯仰见情愫。","三叹白驹篇，气竭不能诉。"]},{"t":"中秋夕寄怀黎惟仁","f":"五言古诗","c":["秋序会平分，夕霁天宇澄。","迢遥彩云没，宛转月华生。","凉飔捲珠箔，银壶坐自倾。","楼上弦歌曲，叹息有深情。","鸿雁隔浦翔，促织近床鸣。","佳人渺天末，终息思屏营。","谁云千里隔，共此一宵晴。"]},{"t":"赠张太仆质卿","f":"五言古诗","c":["真妄本无端，是非多所误。","方回北里辙，遽首南浮路。","蚁泛难为欢，蛾巧易成妒。","荏苒衣上尘，孰辨缁与素。","落羽虞虚弦，春行畏多露。","离颜已非昔，谁能待来故。"]},{"t":"赠羽客还罗浮","f":"五言古诗","c":["云中有一士，冲默契希夷。","五龙传睡法，双峰对茅茨。","忆昨宿瑶台，龙虎守坎离。","二月酿松花，乘鸾吹参差。","囊中数丸药，不渴亦不饥。","随分度世人，有缘即遇之。","暂为京国客，恐滞还山期。","一鹤唳秋云，三秀明春芝。","愿从童子去，再拜称天师。"]},{"t":"赠别黄平倩编修 其一","f":"五言古诗","c":["层城丽白日，卿烟复绕缭。","玉节下云中，湛露承天表。","清清玉河水，上有特栖鸟。","延颈顾其匹，善鸣何窈窕。","俦匹岂不佳，欢会则云少。","去去展周亲，行行隆汉道。"]},{"t":"赠别黄平倩编修 其二","f":"五言古诗","c":["汉道一何广，周原亦膴膴。","碣石既东表，雁岭复西阻。","驱车五原上，北眺长城下。","列侯半城守，两阶尽干羽。","回首望咸阳，兴言陟其岵。","谁为北山诗，之子行将父。"]},{"t":"赠别黄平倩编修 其三","f":"五言古诗","c":["将父情既遑，与子谊非薄。","暂辞紫阁欢，归恋庭闱乐。","景风自南来，动我杯中酌。","相送入关门，悠然满函谷。","函谷连蜀城，恃险岂长略。","子有经世言，铭之在剑阁。"]},{"t":"赠别黄平倩编修 其四","f":"五言古诗","c":["剑阁阻且深，铜梁不可越。","锦城花似绮，巴江带如发。","人行筇笮云，马踏峨眉月。","道路信云险，之子尚驰突。","情夷境自安，神畅力不屈。","西望垄坂长，伊余阻愁绝。"]},{"t":"赠别黄平倩编修 其五","f":"五言古诗","c":["愁绝非为离，相对何萧瑟。","谬登著作场，忝随文墨职。","言宴及良辰，雠校无虚日。","匪玉枉受攻，虽蓬乃自直。","走兽尚索群，归鸿必求匹。","临风结长想，愿托西飞翼。"]},{"t":"游侠篇赠汪公干","f":"古风","c":["虽为京洛客，不过金张门。","生平负气志，行乐无朝昏。","冯驩惭市义，剧孟接高论。","礼乐攒眉去，诗书抑首敦。","玉台携妙妓，珠弹挟王孙。","白丸来蓟苑，匕首去咸原。","■////璖镂剑箾，翠羽插车辕。","相期在千里，结交止一言。","登坛无狗马，到处有琴樽。","晚年执硁节，穷巷多车轩。","片言或失意，杯酒起诟喧。","苟明匹夫德，不顾万乘尊。","有时易水上，独吊田光魂。","耻学侯嬴辈，惟殉左席恩。"]},{"t":"答黎文学惟仁","f":"五言古诗","c":["昔在衡门下，园庐或互游。","有时风日美，樽酒话林丘。","欢然共携手，卒岁事西畴。","何意饥寒逼，中年为贫忧。","杖策入帝京，五上敝貂裘。","幸遇休明际，泥涂终见收。","渔钓皆被猎，牧豕亦封侯。","生平多卤莽，此际惧愆尤。","古人戒末信，今兹慎家修。","夫子秉高尚，晚节更清幽。","割席方自此，代庖非所谋。","高风不可泯，重谊莫能酬。","常恐平生负，终贻岩壑羞。","安能茂稷契，抗迹揖巢由。"]},{"t":"秋夜怀友","f":"五言律诗","c":["凉风吹小苑，白露下将夕。","虫吟四壁静，雁叫重云隔。","宫月疏梧桐，山衣剪萝薜。","佳期不在兹，谁能久行役。"]},{"t":"咏瓶菊","f":"五言律诗","c":["陶令采来菊，插之青铜瓶。","问君何为尔，珍爱等瑶琼。","懿此美人惠，复贻寒岁馨。","犹怜东篱下，日暮重含情。"]},{"t":"赠别包汝钝给事","f":"五言古诗","c":["高台积雪多，大陆北风厉。","行路寂无人，之子驾言逝。","逝矣返故乡，眷言执离袂。","与君四海人，六载为兄弟。","既谐金石交，亦动风云契。","良遇安可常，再陨临岐涕。","有酒难自斟，无舟可共济。","衔哀子傍皇，怨别我留滞。","揽衣讯长途，执手期后会。","久要贵不忘，愿子书衣带。"]},{"t":"赠别乔世昌都谏","f":"五言古诗","c":["潞河三尺冰，夷门千里道。","岂不念离居，岁晏无芳草。","芳草何足贵，所贵永为好。","郁郁山上松，磊落而寿考。","岂无霜雪侵，坚贞常自保。","鸱鸮鸣高林，骐骥伏下皂。","达哉塞上翁，所见一何早。","冲风不起羽，强弩不穿缟。","令终古所难，末路谁能巧。","明哲昔有训，全真以为宝。"]},{"t":"独酌梅花下走笔索陈山人画梅","f":"五言古诗","c":["我醉梅花下，思君画梅枝。","瑶华看不足，画里或传奇。","绮月乍图影，香风时冷肌。","早来盻庭霰，羞涩不成姿。","昨宵感我梦，彼美好容仪。","既梦忽复觉，芳魂谅在兹。","安知非画里，恍惚使人疑。","烦君写此意，远寄瑶台妃。"]},{"t":"咨伯步访我洞梅不待小酌而去","f":"五言古诗","c":["君为看梅来，不饮梅下酒。","却令梅下仙，徘徊吟洞口。","昨夜罗浮月，宛宛窥窗牖。","顾见瑶台人，嫣然举玉手。","微风动芬馥，徐步锵琼玖。","相对不为欢，后梦亦何有。"]},{"t":"题甘露园","f":"五言律诗","c":["入林何必深，宛与世尘隔。","高树似金茎，淩风承玉液。","于陵灌方勤，汉阴机已息。","借问园居子，何如藐姑射。"]},{"t":"送人还山","f":"五言律诗","c":["君从山中来，复向山中去。","长啸谢人群，浊世不可住。","夜雨长瑶草，晨风送鸾驭。","以我一片心，挂向瑶台树。"]},{"t":"赋得采芳","f":"五言古诗","c":["江南有思妇，江北望佳人。","搴芳立洲渚，盈手掩罗巾。","兰心既有托，蕙意难具陈。","弄珠汉皋曲，拾翠洛川滨。","日夕渺愁望，烟波讵能亲。","草色匝幽馆，花枝摇暮津。","寄言宦游子，须惜故园春。","勿令芳岁别，千里隔音尘。"]},{"t":"初秋夕寄友人","f":"五言律诗","c":["东走与西笑，相隔红尘里。","何事日闭关，注易从兹始。","桂花发初月，莲子落秋水。","歌钟正高会，默默守玄理。"]},{"t":"送何平甫同年宰嘉兴 其一","f":"五言古诗","c":["东南信多美，此地霸王州。","云凫去渺渺，江路溯悠悠。","宿昔嘉禾郭，今兹烟雨楼。","水绕吴洲曲，山连秦望浮。","河阳种花去，单父鸣琴游。"]},{"t":"送何平甫同年宰嘉兴 其二","f":"五言古诗","c":["燕树雪成霙，黄河冰可步。","近郭送骖騑，遥山起烟雾。","别筵方恨促，怀歌已言暮。","蘋洲千里思，桂楫三江路。","去羡淩风舄，送子西陵渡。"]},{"t":"于五凤楼前赠弟","f":"五言古诗","c":["有鸟朝阳鸣，飞向瑶台集。","楚楚吾家弟，爰来自畿邑。","畿邑五载閒，百度亦维辑。","皇风久已颓，尔其庶有立。","芸阁我倦栖，柏台子新入。","子优绳纠司，我愧青缃业。","归邸各异宿，入朝或交揖。","簉羽班始联，鸣佩声相及。","矢志将无同，共歌天保什。"]},{"t":"奉使淮藩留别同馆诸君 其一","f":"五言古诗","c":["层城何高高，上列珠树林。","林间有好鸟，相对扬徽音。","飘风日夕至，吹我异川岑。","川岑虽云异，幸不隔同心。","故人怜远别，惠我结衷襟。","申诺等崇丘，佩谊重兼金。","徘徊首归路，对酒成慨吟。"]},{"t":"奉使淮藩留别同馆诸君 其二","f":"五言古诗","c":["黄鹄东南飞，五里一回顾。","莫言飞不前，但为念君故。","士由美名毁，女由美容妒。","不见秋至草，零落在朝露。","今我同怀侣，白首期终誉。","交亲谊在敦，临别申情愫。"]},{"t":"奉使淮藩留别同馆诸君 其三","f":"五言古诗","c":["忆我游天阊，结交青云人。","私心窃自许，积念在致身。","作者十馀辈，文雅皆等伦。","良时美嘉会，散步出城闉。","高言矫当世，逸气横秋旻。","聚散苦无端，为乐不及辰。","而我复远役，怀哉隔音尘。","永言保坚白，卒岁无淄磷。"]},{"t":"奉使淮藩留别同馆诸君 其四","f":"五言古诗","c":["国典申旧章，同列美斯游。","斯游信云美，揆德实非俦。","才惭下国使，礼展同姓侯。","侯邦指南服，襟带冠炎陬。","陶陶首夏月，湛湛露斯浮。","朱华耀玉节，芳树引华辀。","南涉清淮岸，北顾大河流。","嘉会日以远，皇恩难可酬。","黾勉事行役，所虑为罍羞。"]},{"t":"采芳曲","f":"五言律诗","c":["美人摇桂楫，容与清川湄。","搴芳欲谁待，将以遗佳期。","芳情讵消歇，芳华恐易衰。","望而不可见，零落空自知。"]},{"t":"既登济上楼还饮舟中对酒作","f":"五言古诗","c":["鲁酒白玉壶，齐讴紫罗襦。","持觞劝鲁叟，问尔何拘拘。","昔有独醒人，千载笑其愚。","屈原非吾党，公荣非我徒。","所以日对酒，弹弦间笙竽。","安得偕贺李，金鱼贸清酤。","斯人不可作，兹事宛如昨。","当时君不饮，今日谁为乐。","我来访古游，还登济上楼。","天光摇积水，城影落芳洲。"]},{"t":"济上","f":"五言古诗","c":["昔览山海图，所志在远游。","直由穷其源，匪为恣冥搜。","兹水何显伏，神理难与谋。","始犹穿王屋，末乃见陶丘。","贯河殊泱泱，合汶仍浏浏。","涸济昔有闻，入海道何由。","曰余忝嘉惠，访古增烦忧。","所忧非为济，淮泗未安流。","寄言行河使，禹功良可求。"]},{"t":"渡河","f":"五言古诗","c":["朝发钜野泽，夕济洪河流。","九流信渺渺，九曲良悠悠。","瓴注捣淮泗，箭溜齧徐州。","昆崙去几许，孟门犹未休。","汩日有馀浊，滔天无厌浮。","我行季夏月，北风何飕飕。","昔渡限无梁，今汎有方舟。","鸣橹顺洪涛，扬帆逐轻沤。","岸上谁家叟，伫立河之洲。","望而不得语，披发且行讴。","薪竹少暇日，堤防无良谋。","为我谢河伯，无为吾民忧。","川灌何足喜，云旗成漫游。","请从挟羿矢，宁假事屈游。"]},{"t":"黄河篇","f":"古风","c":["滔滔万古水，云与天汉接。","披图疑昔闻，按迹證今睫。","昆崙泉始蒙，星宿井初渫。","杯觞犹未滥，褰裳乃云涉。","如何万里流，势用百川挟。","浊浪昏云日，崩涛溃原隰。","神运岂无徵，王气兹有协。","流清圣可俟，图出极乃立。","入塞表朝宗，荣光启大业。","自从凿龙门，转徙非一劫。","汉使谬穷源，禹功秘往牒。","璧马事既往，金堤障犹叠。","卒岁用堤防，何时已林?。","讵言一苇航，终假商岩楫。"]},{"t":"将至淮阴泊清河县","f":"五言古诗","c":["问俗至淮阴，忾然伤怀抱。","白鸟去冥冥，黄流日浩浩。","岸西清河县，半已没洪潦。","门巷类浮家，人烟淡洲岛。","新水昨夜至，孤城势如捣。","雨飒颓墙花，风吹野田草。","粳稻岁不登，妻孥何由饱。","不如水上凫，犹得唼萍藻。","嗟尔河县民，何以待终老。","老父跪致辞，使君勿复道。","丘民何足贵，仁亲乃为宝。","东吊淮泗流，陵树被淹槁。","自从禹功微，明德畴能考。"]},{"t":"使过广陵銮江李季宣挐小舟载斗酒逆予于瓜步遂游金焦诸胜","f":"五言古诗","c":["别君才两月，思君已三秋。","我寻京口渡，君逆广陵舟。","隔岸吴山色，未到愿已酬。","况有故人酒，因之成胜游。","金焦两拳石，东控帝王州。","长风吹不去，惊浪没还浮。","城回碧嶂转，日照沧波流。","遂恐乘流去，去去访蓬丘。","北固时已暮，南徐不可度。","倒影入西池，东挂秣陵树。","玉岛暂栖止，松房尽临水。","涛声清客枕，梵响洗尘耳。","夜半坐矶头，江月映江楼。","天低若堕水，水碧涵天秋。","晚寻焦君迹，云霞似相识。","浥露采瑶芝，看松坐白石。","水底瘗鹤铭，求之不能得。","欲探骊龙宫，更烦象罔力。","招隐与甘露，相去不盈步。","褰裳往从之，飙车入云雾。","其馀皆小琐，不足烦回顾。","归潮信天风，三山近若空。","回望金银阙，恍在碧烟中。","此时与君别，分手类飘蓬。","天明挂帆去，云海意何穷。"]},{"t":"咏史","f":"五言古诗","c":["伐木久不歌，谷风竟谁陈。","文叔为天子，严陵乃故人。","贵贱既殊绝，物色何殷勤。","三召始能至，再顾不得臣。","迹远交始全，道诎身乃伸。","清风激颓俗，馀辉映千春。","至人在师世，大贤贵亨屯。","所以风云遇，渭水投竿纶。","而我濩落士，偶然挂簪绅。","功成拂衣去，垂钓沧浪滨。"]},{"t":"入毗陵","f":"五言古诗","c":["才及荆南界，已听吴趋吟。","云阳去方始，闾浦遂前临。","包橘洞庭岸，宿莽具区浔。","节物随行变，风潮无厌侵。","问我胡闻见，不惮历高深。","自多往古慕，匪直远游心。","此邦有季子，是我夙所钦。","其人没已久，英风流至今。","如何末世士，声利竟相寻。","昔贤轻脱踪，末路重分金。","鸱鸢嚇腐鼠，鸾凤翔丹林。","誓将返吾驾，没齿首阳岑。"]},{"t":"虎丘山作","f":"五言古诗","c":["涉江数百里，历览苦未厌。","饮水过南零，采茶入阳羡。","兹山隐平陆，彩翠扬芳甸。","周峙转绿畴，环流伏昏堑。","近瞩俯长洲，远眺纡吴岘。","灵閟迹多幻，精韬形屡变。","虎踞丘藏金，龙去泉沉剑。","崖坼涧无底，海涌流常溅。","触耳易骇闻，寓目非常见。","且娱耳目玩，孰资有无辨。","改步换丘壑，四时等游宴。","荒台麋鹿上，广石笙歌占。","解佩尽佳人，褰兰多秀彦。","别有幽深处，是为松竹院。","喧寂非一趣，静躁亦殊眷。","战胜貌自肥，道充物固贱。","寄言来游客，兹理可深念。"]},{"t":"七里滩作","f":"五言古诗","c":["结发事远游，所愿栖名岳。","遇有会心处，便欲终焉托。","挂帆严子濑，鸣舷富春郭。","夙怀高尚踪，始果还山诺。","潭影湛虚明，林光递回薄。","落蕊送归潮，惊湍赴遥壑。","道在想冥鸿，志修岂屈蠖。","濯缨暮流清，巢云归鸟乐。","考槃在南涧，还耕趁东作。","灭迹期天民，遗荣谢人爵。"]},{"t":"登钓台作","f":"五言古诗","c":["黄鹄游太清，燕雀守丘樊。","伟哉严子陵，不屈万乘尊。","为士固有志，何心恋华轩。","还钓坐磐石，返耕入松门。","洗耳颍川水，抗迹首阳原。","身隐名愈高，人去台空存。","茂林息归鸟，峭壁奔断猿。","石激水流响，山晚林木芬。","垂竿千丈碧，使我清心魂。"]},{"t":"子陵祠下再赋一首","f":"五言古诗","c":["吾观严子陵，岂缺经世务。","玄纁三往反，始识洛阳路。","亲劳万乘问，不肯回头顾。","偃仰帝座上，卧起道情愫。","耕钓还越山，永绝弋人慕。","客星耿乾坤，钓台出烟雾。","溪碧澄人心，磴险难予步。","触物赏既多，怀人情亦屡。","寄言台下客，此非问津渡。"]},{"t":"泊馀干口","f":"五言古诗","c":["问水识江介，濒湖见兹县。","适越道里尽，入楚众流乱。","汀唱闻渔榜，山烟起樵爨。","浦暗菱荇稀，赭岸霞光绚。","鹤侣冲人起，鱼群惊棹散。","节物客里换，客愁酒中断。","王程未及瓜，乡路已过半。","行役其如何，临流暂觞玩。","江海寄劳人，安土庶无闷。"]},{"t":"使至饶州","f":"五言古诗","c":["山川奠南服，藩屏壮江圻。","肃徒三千里，咫尺将天威。","晨起理柔桨，容裔江之湄。","遥遥至国都，符瑞生光辉。","青岑瞰华屋，白水映朱扉。","游梁文赋是，入洛宦旅非。","嗟我远行役，车怠马亦饥。","首夏辞京邑，已见秋叶飞。","虽微驷牡用，薄言歌采薇。","谁念简书重，客子未遑归。"]},{"t":"再献淮世子","f":"五言古诗","c":["名藩展大礼，吉日厥惟良。","不睹皇枝盛，安知帝道昌。","明明高后烈，赫赫淮甸张。","朝恩将日永，国祚与天长。","圭册敦往典，冕服亦孔臧。","帝命嘉且隆，祇承在谦光。","忆我远来斯，寝食独靡遑。","幸徼大国惠，使命得所将。","公子秉峻谊，饱德充厥肠。","终宴连曲池，游遨周华房。","自顾微臣分，醴酒亦过尝。","愿我贤主人，为乐靡及康。","安望左席贵，陨越干国章。"]},{"t":"初归故园 其一","f":"五言古诗","c":["祇役在淮都，事已返旧疆。","旧疆八千里，乡路杳何长。","清晨至里门，车徒不敢张。","邻里闻我至，老稚走相望。","亲族闻我至，斗酒各自将。","劳慰未云毕，仓卒叙炎凉。","问我何官爵，谬登著作郎。","问我何职业，石渠典秘藏。","问我何所就，低首不能昂。","去家事明主，遭世本虞唐。","出入金闺里，昕夕铜龙傍。","优游文墨职，咫尺独靡遑。","兹辰承嘉命，持节还故乡。","故乡多密亲，谁存复谁亡。","存者咸会斯，亡已归山冈。","寄言宦游子，故乡安可忘。"]},{"t":"初归故园 其二","f":"五言古诗","c":["八载去乡国，今晨始得归。","捷步入外闾，慷慨登中闺。","既旷家园聚，转念骨肉稀。","忆我骨肉亲，泪下如绠縻。","宗族少前辈，邻里半成非。","一出已如此，再出安可期。","驱车问丘垄，松柏十数围。","兔走思旧穴，鸟还栖故枝。","他乡勿久滞，书此报京畿。"]},{"t":"初归故园 其三","f":"五言古诗","c":["游客久念还，道长苦难越。","解缆当麦秋，到家已菊月。","玉露凝寒条，金风飘素节。","兴言行役久，坐叹时芳歇。","四兄感今归，子侄追昔别。","置酒高堂上，丝竹清音发。","仕宦未极意，符瑞辉闾阀。","开轩望场稼，次第桑麻说。","击鲜绿沼中，时菊承露掇。","自我去八载，积念隔凉热。","欣兹返衡茅，节物复可悦。","暂息朝市喧，终养丘园拙。"]},{"t":"使归羊城柬亲友 其一","f":"五言古诗","c":["移家二十载，亲友半羊城。","小子复朴鄙，相逢意多倾。","忆昨去京国，寤寐隔衷诚。","寄书万里远，一岁案常盈。","英英群秀士，皤皤诸老成。","处迩不忘遐，久要若平生。","感兹携手好，契我同归情。","烟霞恋旧赏，泉石追前盟。","谁能久离索，而不怀合并。"]},{"t":"使归羊城柬亲友 其二","f":"五言古诗","c":["昔我远行役，相送江之湄。","今我远来归，相迎郊之圻。","念此经时别，感彼旧颜移。","言笑方未已，涕泪忽沾衣。","短短百年内，安得常乖离。","今会已非昔，后会复殊兹。","愿言共携手，永践寒岁期。"]},{"t":"使归羊城柬亲友 其三","f":"五言古诗","c":["弭策归海上，兴言问亲故。","昔别今几存，旧恨当谁诉。","扰扰百年间，四十已虚度。","佳期在早岁，多为名所误。","鲁客之楚游，及归迷津路。","越人学邯郸，还遂失其步。","鼷量傥已盈，蚊力将何负。","未若还故吾，且履贫贱素。"]},{"t":"行自西关经黎司勋林太史邓廷评故居晚登北山","f":"五言古诗","c":["肃驾阅林坰，回镳历江岛。","归马不待策，悠悠遵故道。","故道多遗庐，即事念同好。","哀哉二三子，捐世一何早。","忽忽十年间，斯人骨并槁。","秋风折璚柯，斗光埋剑宝。","既兴酒垆感，复切山阳悼。","登高望所思，逝川何浩浩。","往者不可追，一樽聊自倒。","孰是天地终，而能长寿考。"]},{"t":"咏阶前鹤","f":"五言律诗","c":["昂昂腾汉姿，皦皦负霜质。","暂娱耳目玩，岂是轩墀物。","鸾啸恒为侣，鸡群讵堪匹。","会当乘风云，万里坐超忽。"]},{"t":"咏松","f":"五言律诗","c":["森森千丈松，落落丈夫概。","耸干高岭侧，穹标碧云外。","当春发华滋，迎寒转苍翠。","节以霜雪坚，用以栋梁大。"]},{"t":"秦女曲","f":"五言律诗","c":["嬴女与萧史，嬉游玉台端。","盛年等欢爱，各保如花颜。","乘鸾向明月，凤吹遗云间。","自无餐霞质，逸驾畴能攀。"]},{"t":"山中赠丁元父给谏","f":"五言古诗","c":["谪官嵩山阳，山深意不俗。","岩扉时自开，云构何常卜。","隐几见少室，三花媚林麓。","簿书展长松，印绶挂深竹。","山僧似定猿，吏人偶驯鹿。","搴霞上高岭，采秀入幽谷。","览古将军树，息盖帝休木。","石泉夜雨声，数寸阶苔绿。","自关道气清，岂受尘网束。","正直神不欺，幽闲理自足。","时有箕颍人，相过论心曲。"]},{"t":"登箕山","f":"五言古诗","c":["杖策访名山，夙慕良有以。","素琴石上横，清风松下起。","昔日让王人，含芬遗垢耻。","饮泉想弃瓢，临流思洗耳。","太古多逸民，中世寡奇士。","回策下岩翠，放歌入烟紫。","白云何时来，荒涂谁与理。","终愿毕吾志，抗手谢坌滓。"]},{"t":"行经路傍古墓","f":"五言古诗","c":["路傍何代墓，欲问了无因。","当日铭碑者，斯焉骨亦陈。","陵谷有回换，况乃绮罗身。","重泉一以闭，千载不复晨。","蒙密荆杞乱，纵横石兽奔。","珠襦为人取，玉体蝼蚁亲。","田狸升树啼，牧竖歌伐薪。","幽幽垄上日，靡靡草间燐。","雍门不足涕，蒿里不足呻。","恨无一杯酒，酹此泉下人。","安见千年后，谁非狐兔尘。"]},{"t":"冬季朔日从友人斋食","f":"五言古诗","c":["朔日为月始，季冬属岁藏。","天工此时毕，人事何匆忙。","斋心朝太一，密虑卫元阳。","晓灌醍醐顶，静吸华池浆。","披衣寻净侣，芳洁自罗将。","酒用醴泉水，食取瑶草芒。","五内涤尘根，丹室澄虚光。","坌垕永无染，刀圭从此尝。","真人有要言，清净道之纲。","淡泊宁吾志，甘滋烂人肠。","去矣餐元气，吾将嬉紫房。"]},{"t":"庭梅二月半后放花","f":"五言古诗","c":["春还忽已半，桃李方参差。","梅蕊何迟发，开花临玉墀。","捲帘蜂乍入，披幌月仍窥。","韶节谅难定，素心人讵知。","孤芳幸未晚，及此赠佳期。"]},{"t":"送王行父","f":"五言律诗","c":["落日洞庭春，行云楚江色。","千里送佳人，黄鸟思何极。","郊原赏已隔，洲渚望犹积。","时蕊未堪飞，况乃纷离席。"]},{"t":"三月三日拟兰亭体","f":"五言律诗","c":["连皋驻游幰，枉渚撷时芳。","及此当春服，流盻清川阳。","和风扇广陌，微波激轻觞。","忘形寄沉湎，适意在徜徉。"]},{"t":"公宴诗 其一","f":"五言古诗","c":["遭世本清穆，与子共翱翔。","肃肃群龙会，式宴开此堂。","各怀仁义言，被服文绣裳。","清论吐兰气，矩步接周行。","白日耀华簪，春风流羽觞。","长袖多奇舞，皓齿发新倡。","四座咸既醉，感激思徬徨。","一朝遗顾盻，千载有芬芳。","日入车马散，馀辉映雕梁。","勖哉众君子，无已歌太康。"]},{"t":"公宴诗 其二","f":"五言古诗","c":["清晨高宴会，薄暮未言疲。","铿填罗剑舄，纵横卧樽罍。","谬参俎豆光，得奉君子仪。","饮醇不知醉，饱德实充饥。","华林荫广厦，飞鸟鸣相随。","清风穆四筵，久阴上丹墀。","卜昼虽自昔，夜饮匪今斯。","燕歌有馀烈，赵瑟声正悲。","满堂盛言笑，感叹中自私。","竹帛无我名，安用生明时。","倘惠方驾顾，为君总前绥。"]},{"t":"三月五日游郭氏园池","f":"五言古诗","c":["结轸临芳郊，回镳憩园枝。","园前绿水池，园后古城基。","池馆发幽思，花木含春滋。","乔柯布新叶，嫩卉舒柔荑。","佳鸟向我鸣，好风穆然吹。","出门见耕凿，悠然念东菑。","共就池边酌，还登城上陴。","古人长已矣，古城馀若斯。","不知千载后，此乐更为谁。","所愿樽恒满，但恐日西驰。"]},{"t":"三月十五游城南韦氏园","f":"五言古诗","c":["暄风荡嘉卉，膏露沐时芳。","休假出南园，众友与我行。","方塘溜清渠，珍木秀通庄。","谷禽择树鸣，水族近人翔。","素柰呈雪姿，绮棠绚霞妆。","俯仰茂对育，羁累为之忘。","嘉彼中园有，坐叹此流光。","取快直时物，欢乐宁讵央。","寤言幽涧侧，彼子独褰裳。"]},{"t":"初秋","f":"五言古诗","c":["凉飙乘夕起，落叶纷已晚。","行云天外还，栖鹊月中返。","草间萤乍稀，枝上露犹泫。","秋风未及深，客怀已不浅。","揽衣步前楹，独叹离居远。"]},{"t":"月夜花下小酌和友人","f":"五言古诗","c":["碧空散微云，孤月照远客。","以君衣上光，鉴我花间席。","倾壶逐夜凉，隔林望归翮。","槭槭叶堕阶，凄凄风入隙。","清光正娱人，徘徊恋终夕。"]},{"t":"秋夜","f":"五言古诗","c":["历历云间星，练练波上月。","窈窕出帘栊，参差见城阙。","白露皓前林，商飙中夜发。","闺人怨机杼，君子远于役。","蟋蟀感宵征，蜘蛛寻夜织。","慷慨平生怀，迢迢限燕越。","谁令旷佳期，惆怅至明发。"]},{"t":"奉答四家兄见赠九日上官之作兼酬谢孝兼彦云汪处士公干","f":"五言古诗","c":["峨峨承华居，所任必端良。","我后眷储幄，资贤辅少阳。","入则以道谕，出则以义匡。","自省乏秀望，安能俪圭璋。","秋实信靡效，春华恐不扬。","嘉会符九日，式宴序东堂。","肃肃天宇旷，邕邕群雁翔。","饮酒过三爵，登歌应重光。","吾兄嘉令节，众宾庆道昌。","褒词逾华衮，竣谊明秋霜。","箴往述召吕，勖今称韦张。","陈力而就列，庶几视周行。"]},{"t":"雪夜谢彦云载酒见过与四家兄汪公干小集","f":"五言古诗","c":["玄云积重阴，素景澄虚朗。","生白盈轩墀，流光入帏幌。","初炯玉窗明，渐映瑶台上。","洒菊丽寒姿，间梅发清赏。","寂静神已闲，幽独理宜奖。","昔闻袁安卧，今见王猷访。","门外辙迹深，竹间人语响。","小酌不知寒，抽琴抒妙想。"]},{"t":"寒夜董玄宰太史过谈","f":"五言古诗","c":["落日见归鸟，卷帙聊暂辍。","居人掩轩坐，有客报来辙。","苔砌卷落槐，竹根暧馀雪。","灯下两人语，花傍一壶挈。","语默虽万端，妙契同一澈。","伯牙遇钟期，王倪逢列缺。","筌啼久已忘，风雅道未绝。","请画商岩芝，岁晚可同撷。"]},{"t":"兵车何煌煌行","f":"五言古诗","c":["兵车何煌煌，煌煌去何乡。","天子今命我，讨彼蛮彝方。","侧闻日本寇，远涉朝鲜疆。","招以义不服，敢于逆颜行。","王赫斯震怒，授钺开明堂。","带甲十万馀，一一尽豪强。","盔刃既犀利，械器咸精良。","战胜庙算多，杀伐天威张。","两翼夹中坚，精锐不可当。","期门占气候，太一动星芒。","连营鸭绿左，结阵鸡林傍。","指顾反侵地，挂弓于扶桑。","平生怀忠义，意欲吞八荒。","行行振长策，永令波不扬。"]},{"t":"东征从军行 其一","f":"五言古诗","c":["我本忠义士，授策靖东夷。","军书昨夜下，启行有程期。","入与家人别，去去从此辞。","朝登蓟门道，夕济滦河湄。","我行孟冬月，北风鸣且悲。","溪谷多霜雪，道路常崄巇。","后嘶万马群，前建十丈旗。","悠悠越国都，遂至彼封圻。","仗剑清海氛，时雨迎王师。","反彼旧旄倪，睹我汉官仪。","齐公问包茅，秦伯赋无衣。","况我奉王命，定乱而持危。","古来竹帛烈，岂属纨裤儿。"]},{"t":"东征从军行 其二","f":"五言古诗","c":["朔风吹征裘，边马鸣不止。","烈士怀古心，拔剑四顾起。","东方羽檄急，海气昏千里。","幽并多健儿，吴越多君子。","共是报恩人，各言雪国耻。","万骑出渔阳，三军度辽水。","搴旗山雪高，吹角海波瀰。","朝鲜救兵至，日本夷王死。","功名何足论，要自酬知己。"]},{"t":"东征从军行 其三","f":"五言古诗","c":["申胥哭秦庭，其志在存楚。","庾信哀江南，亡臣困羁旅。","吴子时卧薪，报仇不遑处。","越人未返国，妻妾为囚虏。","此邦久宴安，那能免侵侮。","宗庙见焚燬，臣主窜草莽。","今我整义旗，遥遥涉疆土。","岂不惮远役，王事怀靡盬。","晨征犯风雾，夜宿无室宇。","三军久暴露，饥寒亦已屡。","问罪宁尔邦，除残报明主。","嗟尔远道人，安知我勤苦。"]},{"t":"东征从军行 其四","f":"五言古诗","c":["属国久向化，述职比东藩。","海烽一朝起，鱼鳖何喧喧。","匪伊敢犯顺，乃我欲固存。","连樯伏万弩，平野列千屯。","会见封鲸鲵，崇丘对国门。"]},{"t":"东征从军行 其五","f":"五言古诗","c":["自我徂殊域，悠悠滞东鄙。","本为辑鳞介，由来徵楛矢。","久知皇极尊，宁复问箕子。","夷国日丧乱，王师费经纪。","何时咏栗薪，荣我东归士。"]},{"t":"咏茄","f":"五言律诗","c":["紫茄时被陇，舒叶自亏蔽。","登君玉盘内，得耦嘉蔬味。","结花讵能芳，垂实迥连带。","虽微蹲鸱用，颇胜匏瓜系。"]},{"t":"城颍","f":"五言古诗","c":["停车指城颍，芳躅何缤纷。","巢许既高蹈，千载离垢坌。","如何遗羹子，纯孝至今闻。","揖让君臣全，愤争骨肉分。","积憾天性蚀，微言大义存。","至情在感发，口舌徒云云。","荒隧沦故道，薄采奠孤坟。","寄言茅焦者，颍谷有馀芬。"]},{"t":"和四家兄元日看梅","f":"五言古诗","c":["正朝览物华，庭梅色已弄。","送腊稍辞寒，迎岁尚含冻。","年光蕊上转，春意枝间动。","初妍映柏觞，早芳入椒颂。","人对新岁花，鸟回新花哢。"]},{"t":"和四家兄新岁梅","f":"五言古诗","c":["才听新岁鸟，已看新岁梅。","况逢新岁客，同倾新岁杯。","素艳宜冰署，年华上玉台。","迎风未片落，照雪且丛开。","幸及连枝赏，全胜寄陇来。"]},{"t":"临春台","f":"五言古诗","c":["载酒临春台，徘徊不能已。","东风如有情，飘荡樽前起。","为将看花意，吹渡春江水。"]},{"t":"送混成子谪尉上海","f":"五言古诗","c":["南方有一士，结庐倚岩桂。","胸藏霸王略，腹贮烟霞气。","学道三十年，未忘当世虑。","舌摧仪秦锋，智屈孙吴技。","短绠常汲深，高才沦下位。","谪宦类贾傅，抗章似梅尉。","位卑而言高，处贱而议贵。","举世或笑之，谓拙于用大。","予独不之笑，于道有真契。","暂随燕雀群，未酬鸿鹄志。","□知岂在多，希知良足贵。"]},{"t":"赠吴孝父归黄山","f":"五言古诗","c":["黄山连碧虚，上有轩辕居。","丹台久芜没，何客此结庐。","结庐独长往，早发金庭想。","高揖曹阮辈，炼药恣偃仰。","紫房闭绿苔，清涧袅云来。","丹井昔常洁，瑶宫今始开。","自为黄山客，醉拂黄山石。","兀然发孤啸，千峰敛暮色。","何时启石关，投足遍人寰。","意欲穷九有，归卧云松间。","君去亦多时，君来何太迟。","容成与浮丘，招手白云期。","昔落风尘里，名姓在人耳。","今返烟霞际，悠然与终始。","三十二莲峰，荡漾金芙蓉。","归来当见忆，云鹤许相从。"]},{"t":"赠别林宫赞咨伯 其一","f":"五言古诗","c":["平昔寡俦侣，与子分弥敦。","班联通禁掖，居止隔墙垣。","壮怀夙有契，微尚颇亦存。","亭皋一回首，落日眺川原。","川原何迢迢，我思郁以烦。","良友远行迈，何用展心魂。","终同沧海去，未报紫宫恩。","独有临期泪，要之平生言。"]},{"t":"赠别林宫赞咨伯 其二","f":"五言古诗","c":["秋山何苍苍，四顾尽萧索。","临水送将归，离心对摇落。","摇落难为欢，芳游宛如昨。","时菊掇紫茎，霜筠飘素箨。","去雁影离离，轻烟生漠漠。","归骖陌上转，别词酒间作。","未酬匡世志，共想还山乐。","我怀良不虚，君情岂有托。","何以赠前期，功名在麟阁。"]},{"t":"正朝作","f":"五言古诗","c":["正旦洽百礼，圣人登万寿。","金石备宫悬，衣冠饰岁首。","东朝礼乐新，南国簪绅旧。","未能陪柏梁，且复颂椒酒。","雪霁汉宫槐，烟轻蓟门柳。","东伐靖远夷，西征荡小丑。","宝玉充庭旅，闾阎犹疾首。","顾问调元人，阳和肯回否。"]},{"t":"寄何孔参逸人于端溪","f":"五言古诗","c":["家住清溪侧，溪清照古颜。","言是沉冥客，栖遁此溪山。","君平方坐肆，季主亦开关。","一探元命秘，观世出人寰。","天人本微妙，神理况清閒。","宁同名利士，滞迹风尘间。"]},{"t":"馆中移植桃花和四兄兼答诸客","f":"五言古诗","c":["海上求仙客，河阳宰邑人。","曰予从宦侣，偶与二事均。","卜筑宫城侧，地接仙源邻。","休沐情既暇，丘壑念弥伸。","此花何灼灼，其叶亦蓁蓁。","移为瑶水树，种作绥山春。","光风泛紫艳，轻霞簇红鳞。","拂绶凝锦绮，当杯晕朱唇。","未留西母核，先献华林珍。","门庭无杂莳，蹊径绝纤尘。","愿以千岁实，来荐帝园新。","君问种桃者，宁知非避秦。"]},{"t":"小馆新种桃花黄平倩庄得全两学士过看黄既断酒庄亦有宿酲皆不待酌而去贻以此诗","f":"五言古诗","c":["昔予游海上，灵山屡淹泊。","海峤气长春，玉窗桃未落。","仙者四五辈，流霞劝春爵。","归来入汉宫，谒帝蓬莱阁。","韶光暮春月，京华逐行乐。","结侣过前蹊，游仙慕丹壑。","丹壑何迢遥，前蹊发红萼。","移处乍绯绯，看时即灼灼。","接叶隐啼莺，交枝舞青雀。","愿栽东海桃，不种西山药。","黄子辞世氛，夙有绥山约。","庄生早结绶，半醉称臣朔。","予非避世人，君岂问津客。","再至宁当迷，来朝恣欢酌。"]},{"t":"杂诗","f":"五言古诗","c":["白日丽高隅，流光照我堂。","临堂理妙曲，哀怨断人肠。","妙曲何所怨，怨此天一方。","同心与我言，蔼若春兰芳。","如何久离居，使我重感伤。","王睢不匹处，玄燕必双翔。","朝出国门望，至夕犹徬徨。","往往飞花处，为君停玉觞。","红颜难久恃，春华不再扬。","愿君重明信，无使两情忘。"]},{"t":"庚子三月三日再效兰亭体","f":"五言律诗","c":["春服娱嘉节，命赏怡清川。","鱼游祓浪侧，莺语流杯前。","濯缨听新曲，舞雩咏归篇。","齐物非外物，取乐任自然。"]},{"t":"高正甫出守袁州九月九日予偕家兄暨诸亲友能文者十九人饯之毗卢阁赋诗为别 其一","f":"五言古诗","c":["季秋氛气敛，天宇旷澄明。","樽酒送远客，税驾出林坰。","层轩四望起，万里秋阴生。","南眺浔阳渚，北望蓟丘城。","代马骋高足，燕鸿起遐征。","极目多远思，赏心叹合并。","太守耀朱轮，千骑抗飞旌。","嘉会即宠饯，良时析群英。","商飙厉丝竹，娈童歌且清。","为持芳菊酒，写我当歌情。","清朝重理人，时哉策令名。","谁能东篱下，日暮守衡荆。"]},{"t":"高正甫出守袁州九月九日予偕家兄暨诸亲友能文者十九人饯之毗卢阁赋诗为别 其二","f":"五言古诗","c":["高台本宜春，君行亦宜秋。","宜秋正南望，苍苍烟雾浮。","秋色理征传，轩骑从诸侯。","凉飙起北陆，爽气入南州。","亲朋恋离索，赠言美行游。","醒时多缱绻，醉后复绸缪。","宦达众所羡，时危在分忧。","重关困商旅，三户弊诛求。","惟我金石友，夙昔慕清修。","愿子驰声光，慰我饥渴愁。"]},{"t":"途次遇雨","f":"五言律诗","c":["昨夜月离毕，今朝鹳鸣垤。","征夫阻途旅，妇子叹家室。","改辙严烦顿，停车问愁疾。","东作其如何，西成庶平秩。"]},{"t":"中山问酒家","f":"五言古诗","c":["客从中山来，即问中山酒。","村店倚绿桑，旗亭对官柳。","果熟垂虚檐，花飞拂暗牖。","君子耻空罍，小人思击缶。","季鹰快生前，苏秦矜肘后。","蚁汎正乘欢，蝇营我何有。","酒家旧名胡，临邛新娶妇。","愿因陶旅情，无钱肯沽否。"]},{"t":"过殷墟作","f":"五言古诗","c":["北上朝歌里，南涉淇水隅。","前有钜桥仓，后有鹿台䧢。","宫阙久芜没，坟陵亦丘墟。","借问此何郭，云是殷故都。","才辩足拒谏，智力称绝殊。","飞廉为助虐，崇伯更献谀。","积粟逾太行，聚财倾昆吾。","民离尚征敛，运去犹欢娱。","剖心莫与悟，佯狂遂为奴。","一朝孟津会，牧野誓师徒。","粟为周人发，财为周人输。","敌国行仁义，己身遭钺鈇。","身死为世笑，笑此一独夫。","感叹殷王子，多藏诚累愚。"]},{"t":"过演易台","f":"五言古诗","c":["大易兆未然，圣人炳先几。","吾观商周际，易道实中微。","贤哲被奴戮，奸佞何猖披。","西伯执臣节，羑里见囚羁。","忠信不见明，正直胎祸机。","及乎履患害，始发忧危辞。","倚伏信难豫，运会密相推。","柔顺而文明，所以处明夷。","道穷言始立，身困教乃垂。","文王我师也，斯言岂吾欺。","感愤登兹台，含悲竟此辞。"]},{"t":"自卫辉赴苏门途中书怀寄何太守兼柬辉县吕明府","f":"五言古诗","c":["旦发卫水阳，极意恣所往。","名山谐夙慕，绝境发奇想。","含情眷明牧，赍具资胜赏。","方辞颍川守，遽识朝歌长。","登车云尚晦，振辔天渐朗。","目极桑枣林，耳属鸾凤响。","撇见蓬池烟，已映苏门上。","高台待啸歌，长林遂偃仰。","岩峦吐气清，石竹閟幽幌。","志意由自适，神理非外奖。","卜筑蹑前踪，怀贤契今访。","终期谢天刑，于焉税尘鞅。"]},{"t":"宿苏门山中","f":"五言古诗","c":["涉世乏远略，夙尚多奇秉。","会息车马喧，即践烟霞境。","习坎穷真源，兼山止绝顶。","日入众壑掩，鸟归空林静。","石壁暧残照，山冈有馀映。","闭关绝尘想，万虑一时屏。","风泉扬妙音，月林洒清影。","阒寂寡欢悰，幽独證内省。","寂幽神弥王，岩穴道愈炳。","平生少云为，更觉兹夜永。","因书静悟侣，云术共遨骋。"]},{"t":"游嵩山四首 其一","f":"五言古诗","c":["名岳宅中土，生贤藉奇巘。","图为风雨会，地以揖让显。","崖崿虽峻极，冈阜亦平衍。","循麓果纡回，登崇更凌践。","夙多遗世踪，到此尘虑遣。","箕颍信高蹈，阳城道未贬。","揆迹有绌伸，忘怀任舒卷。","素风谅不遐，幽意得所展。","欲去还复留，低徊不能返。"]},{"t":"游嵩山四首 其二","f":"五言古诗","c":["寻真紫芝馆，访古白云衢。","年代一何杳，辇道尚盘纡。","秦槐馀一树，汉柏有三株。","金丹既沦没，玉检亦荒芜。","神仙术久閟，多欲为累愚。","千秋与万岁，无乃太矫诬。"]},{"t":"游嵩山四首 其三","f":"五言古诗","c":["薄游吹笙岭，回憩捣衣石。","玉女不可遇，青童似相识。","遗我一箱药，金膏和玉液。","服之容色改，自然生羽翼。","体轻若黄鹄，一举淩八极。","顾视让王人，累累冢上石。","天地可齐年，浮名竟何得。"]},{"t":"游嵩山四首 其四","f":"五言古诗","c":["二室丽天中，三花落云外。","远势浮河洛，穹标掩华岱。","珍木自成阴，瑶草何曾溉。","神膏沆瀣霏，金沙碧潭碎。","风从箕山来，思与逸驾会。","天路渺难即，霞术久芜秽。","独见周王子，吹笙游鹤背。","青宫生尘埃，紫房绝情爱。","逍遥白云间，欲归迷所在。"]},{"t":"登少室绝顶","f":"五言古诗","c":["二室俱造天，少室难与侔。","将淩岝崿险，遂涉清浅浏。","阴磴烟尚霏，阳崖雨乍收。","曳曳云触石，涓涓溪乱流。","攀岩藓苔滑，逾岭径术修。","下窥元气合，上列象纬周。","霞彩席间发，岚气衣上浮。","弹琴众山响，吹笛群壑幽。","方兹展奇眺，聊用豁远眸。","顾瞻尽河洛，表里见神州。","海客谈员峤，羽士慕丹丘。","茫昧理岂设，想像步难留。","平生徒欣仰，即事恣冥搜。","寄言赏心客，去此复何求。"]},{"t":"颍阳山中赠登封燕明府","f":"五言古诗","c":["王乔玉舄飞，方朔金门待。","久闻有仙吏，思愿与之会。","君宦松山阳，而与箕颍对。","案牍积烟霞，讼庭落苍翠。","人吏青岩中，簪绅白云外。","有时驱马出，独晤饮牛辈。","虽复稍逢迎，顾少风尘态。","乍到赏心惬，久游神理会。","卧理时自闲，抚字亦劳瘁。","洗耳未必贤，折腰岂为累。","我寻五岳期，君报三年最。","何日丹砂成，乘鸾谒华盖。"]},{"t":"过襄城登首山","f":"五言古诗","c":["名山蕴灵躅，神宝丛仙班。","地以旷绝超，路缘险涩艰。","辇道绿萝合，神室白云闲。","昔契神既王，今陟力未悭。","高步升幽岨，侧耳聆潺暖。","孤赏莫与晤，幽寻谁共扳。","昔闻有熊帝，炼药于此间。","广成窈而冥，玉童清且娴。","鼎成龙忽去，一往不复还。","深宫闭紫苔，曲房凋朱颜。","得道轻黄屋，遗世守玄关。","极望鼎湖上，龙髯不可攀。"]},{"t":"大堤","f":"五言律诗","c":["大堤临汉水，四时好行乐。","纷纷驰宝勒，处处上珠箔。","酒旗拂柁楼，岸花映江阁。","日暮管弦声，风吹满城郭。"]},{"t":"出衡山县行数十里古松道中至山下作","f":"古风","c":["未登衡岳寺，先看衡岳松。","清阴夹道植，翠色百里封。","左右分偃盖，前后引扶筇。","天清下鸾鹤，风至舞虬龙。","俯瞰千寻壑，直上万仞峰。","穹标倚霞岭，逸韵答石淙。","凉荫苍苔石，香袭丹桂丛。","我来值穷秋，凄凄霜露浓。","既钦淩寒节，复惬幽赏悰。","时见松下人，采芝?紫茸。","思愿从之游，耸身青云中。","何时鍊金液，于此驾轻鸿。"]},{"t":"游南岳 其一","f":"五言古诗","c":["南州盛火德，衡岳应朱爵。","拔地势嵯峨，摩天气回薄。","五岭耸近峙，九江沦巨壑。","秩祀崇百王，典礼光述作。","在昔有虞世，巡狩穷蛮落。","夏后体明德，玉字亦参错。","不知何代王，柴望阻灊霍。","南风岂不竞，皇德讵能博。","辇路鞠榛莽，云衢成寂寞。","缅惟赤帝居，降神谅有托。","宁止宅仙灵，岂但富鸾鹤。","往哲夙所钦，胜游追前诺。","幽探岣嵝碑，广张洞庭乐。","去矣逝鸿冥，讵云屈龙蠖。"]},{"t":"游南岳 其二","f":"五言古诗","c":["千峰上云气，云气日驰骛。","漠漠生岩林，霏霏网窗户。","忽飘如散绵，倏聚若团絮。","聚散少定踪，昏晓有常度。","须臾变岩壑，俄顷殊苍素。","四时但积阴，终日兴霪雾。","霪雾少开霁，积阴多寒冱。","清明实阳德，离照岂恒虑。","侧闻夏秋交，旱熯伤农扈。","泰岱虽肤寸，终朝成甘澍。","愿一见祝融，陈言问其故。"]},{"t":"游南岳 其三","f":"五言古诗","c":["祝融何迢遥，迢遥抗华岱。","盘薄尽南荒，孤高出云外。","远眺极日出，近属穷江介。","窟宅多仙灵，简函发幽昧。","往者四五人，开云艺松桧。","久欲往从之，共释樊笼累。","斯人不我顾，此意谁与会。","买山事非达，专壑情则泰。","会当命轻鸿，乘云巢紫盖。"]},{"t":"游南岳 其四","f":"五言古诗","c":["弱龄访名山，久怀南岳游。","于心有夙好，宁惮道阻修。","嘉惠在行役，兼得历深幽。","远从荆郢国，来涉潇湘流。","阳台雨初霁，祝融云亦收。","丹宫丽白日，碧树悬清秋。","登高览大荒，四顾尽九州。","回首叫虞帝，浩荡苍梧愁。","箫韶久不作，凤鸟鸣相求。","我欲跨此鸟，东访蓬莱丘。","惜哉时未遇，敛策独夷犹。"]},{"t":"游南岳 其五","f":"五言古诗","c":["南岳有凤皇，托身青云端。","音声中律吕，文彩照天门。","我行与之遇，徘徊且高骞。","问凤何所适，将举向西昆。","问凤何所欲，饥食帝东园。","自惟耿介性，安能顾丘樊。","伟哉凤皇志，待时而奋翻。"]},{"t":"雨后登祝融峰","f":"五言古诗","c":["衡岳冠南斗，祝融薄青天。","白云蒙其上，往往限飞仙。","属兹新霁候，澄景吐鲜妍。","既欣历览便，复忘登陟艰。","向下见群岫，凝云如积绵。","苍茫一气中，安辨陌与阡。","大壑趋洞庭，馀霞映湘川。","昔闻有灵閟，积霭常弥年。","岂伊神理感，而能破重玄。","将发紫庭秘，即此晤真诠。"]},{"t":"九日同何梁二公登雁峰寺","f":"五言古诗","c":["羁旅苦无悰，良辰忽以至。","临水叹将归，登高询故事。","共有龙山兴，载酒雁峰寺。","地暖气初肃，风紧叶欲脆。","久知瘴疠清，未觉风土异。","燕去诚知节，雁回有何意。","欲穷万里目，几席屡迁次。","烟霞荡远空，丝竹激悲吹。","菊蕊未堪餐，橘香薰欲醉。","汉臣荣佩萸，楚客思葺芰。","枫岸君滞宦，衡门我栖志。","忽聆岐路言，临觞发悲慨。"]},{"t":"报使至横石驿病不能前疏乞宽假作","f":"五言古诗","c":["叹滞曾周南，悬情亦魏阙。","轻生命不延，矜荣义所劣。","昔予骋皇路，青宫点朝列。","未尝遑家恤，誓执匪躬节。","徇时昧止足，忝役愧明哲。","逮此缠痼疾，饮水诫内热。","将命阻瓜期，怀归畏简札。","陋彼蒲柳姿，伤此桃李月。","长云送归鸟，空山响啼鴂。","引领天北隅，企望心力绝。","灵药庶可采，疏麻岂堪折。"]},{"t":"于清远峡山待命作","f":"五言古诗","c":["奉役旋京邑，抱痾滞江津。","方同漳浦卧，讵乞茂陵身。","清川带霞岫，矗矗际高旻。","眷此中和月，陶我性情春。","夕霭被兰坂，香风散渚蘋。","灵鸟集灌木，碧浪吹游鳞。","言念孤游客，感物易伤神。","赏心莫与晤，长路杳无垠。","抚景叹行役，离居忧采薪。","岂伊玩物情，而忘王事勤。","但恐衰贱躯，不克拖朝绅。","傥遂乞还请，长此愿垂纶。"]},{"t":"入西樵 其一","f":"五言古诗","c":["西樵与东樵，云表互参次。","借问四百峰，何如七十二。","山中千馀家，往往足幽事。","迢迢白云间，鸡犬自鸣吠。","闾里绝诤讼，园畦多树艺。","以此淳朴风，上代复何异。","荒凉福地图，寥落洞天记。","胜绝昔有闻，兴剧今始莅。","石扇启霞霏，金函发山笥。","独往念始申，还丹术犹閟。","将寻芝谷翁，共访桃源世。"]},{"t":"入西樵 其二","f":"五言古诗","c":["采蒲入深谷，谷深蒲叶长。","下垂九节茎，上荫千仞冈。","玉虹摇涧彩，瑶草发金光。","临流洗且曝，随风清且香。","仙人骑白鹿，乃在嵩山阳。","我昔行见之，授以服食方。","且尽延年术，乘化以翱翔。"]},{"t":"入西樵 其三","f":"五言古诗","c":["松间四五翁，劝我居锦岩。","岩前下飞瀑，后可结茅庵。","隔林望村落，一一入烟岚。","水石既潆带，藤筱复相参。","桃花发天上，桂树生山南。","爱此风土美，况聆丘壑谈。","晨朝警鹤辔，景夕驻鸾骖。","拂雾采灵药，开云艺松杉。","隆情匪虚饰，夙志庶无惭。"]},{"t":"入西樵 其四","f":"五言古诗","c":["涉海时泛滥，登岳信阻修。","未若兹山胜，逶迤起平畴。","烟霞接敝庐，林壑即近陬。","旦发淩东坂，倒景穷西陲。","畦疃高下起，瀑布纵横流。","人家住重岚，水木涵清秋。","啸歌白云动，衣袂青霞浮。","金砂事未著，玉版谁见留。","葛洪慕丹井，安期访蓬丘。","此山多胜事，缓步得冥搜。","一枝聊偃息，八极可神游。"]},{"t":"再去田园 其一","f":"五言古诗","c":["两载还故庐，幽意颇渐适。","方与海滨老，农谈忘日夕。","朝看驱牛出，暮见栖鸟息。","时复北窗下，对客娱篇籍。","揆予从薄宦，谦下祖老易。","秩匪三千钟，愿过六百石。","剪蓬蒋诩园，载酒扬雄宅。","息影辞嚣烦，秉心庶静默。","奈何舍此去，慨焉悲物役。","多谢南山云，岁晚迟来客。"]},{"t":"再去田园 其二","f":"五言古诗","c":["出门望四野，忧心恒忡忡。","问子何所忧，百感填予胸。","谁云天泽远，举目尽疲癃。","谁云周道平，荆棘高蔽空。","树木莽萧条，于何息吾躬。","久知世路艰，悔不守固穷。","君子重谋始，古人戒薄终。","卒卒营世务，羡尔高飞鸿。"]},{"t":"亲友梁黎辈念予北行日载酒过访 其一","f":"五言律诗","c":["生平多宦旅，垂老未遑息。","亲友念将离，载酒劳行役。","良宴不待期，累日继以夕。","未别已绸缪，别去情何极。"]},{"t":"亲友梁黎辈念予北行日载酒过访 其二","f":"五言律诗","c":["自我还三径，稍枉裘羊踪。","颇谓淩冬桂，得侣岁寒松。","时来驱我去，始愿念莫从。","悠悠思远道，戚戚寡欢悰。"]},{"t":"亲友梁黎辈念予北行日载酒过访 其三","f":"五言律诗","c":["世情贱归田，乡里贵出门。","自匪旷远士，鲜不异寒温。","隆谊期止足，敦交在丘园。","结念早旋归，窃恐负此言。"]},{"t":"亲友梁黎辈念予北行日载酒过访 其四","f":"五言律诗","c":["落日携佳人，清尊共愁绪。","仰观群雁翔，肃肃云中羽。","天路多贵游，行子慕俦侣。","欲发晨风兴，思君屡延伫。"]},{"t":"答龚秀才岸文 其一","f":"五言律诗","c":["南翥息未安，北辕修且骛。","问君何仓皇，惟以王事故。","良会能几时，缛节忽已暮。","执手眷前期，踟蹰在中路。"]},{"t":"答龚秀才岸文 其二","f":"五言古诗","c":["平居意不浅，与子分仍深。","不能裨国事，久欲归山林。","良朋敦惠好，枉赠瑶华音。","补衮惭山甫，陈力愧周任。","申章多明规，祇觉赧予心。"]},{"t":"答龚秀才岸文 其三","f":"五言古诗","c":["楚人得荆璆，弃之同瓦砾。","一朝遭卞生，至宝始生色。","举世趋荣途，谁顾蓬门客。","中庸皆列鼎，之子尚藿食。","高才终见知，君其各努力。"]},{"t":"于三水口别侍御七弟 其一","f":"五言古诗","c":["鞅掌缠世务，老至不遑居。","承惠还乡井，含辛去田庐。","辍棹三江口，分手万里途。","万里予怅望，三江子踟蹰。","再出缘义役，屡别使情疏。","一身难自料，万事剧纷挐。","登途虞折轴，临川戒衣袽。","既乖一木任，敢望五鼎需。","群策皆摈处，独力将焉如。","方谋毕吾役，及尔遂悬舆。"]},{"t":"于三水口别侍御七弟 其二","f":"五言古诗","c":["迢迢远行迈，行迈暂维舟。","维舟白日晚，原野风飕飕。","风飕一长望，四顾起沉忧。","沉忧非一端，杞国符我谋。","仪象迭舛错，人事多愆尤。","骀驽服上驷，骅骝弃道周。","鸺鹠鸣高树，鸾鷟远丹丘。","衢路豺虎啼，城社狐鼠游。","嗟哉远行客，举足将安投。","不如返故栖，与子共林陬。","况乃骨肉分，各念道里悠。","子居有令望，我出无良筹。","离悲增物感，泪下不可收。"]},{"t":"三水与亲友别","f":"五言古诗","c":["悠悠万里道，送送三江口。","惜与所知别，行行重携手。","两载返衡门，连旬接杯酒。","既能谅迂愚，幸不弃衰朽。","云壑方倦栖，世路复缠纠。","挥袂谢乡闾，劝驾劳亲友。","停舟日将夕，晤语不能久。","惟有南山松，可喻固穷守。","临别枉情赠，欲报惭琼玖。"]},{"t":"南华寺谒能禅师像效唐体 其一","f":"五言古诗","c":["能公昔开化，千载扬宗风。","惜生绝学后，沦被夷教中。","衣为曲阜履，钵即鼎湖弓。","在法不在物，奈何惑愚蒙。","独有幽寂意，弥令孤赏同。"]},{"t":"南华寺谒能禅师像效唐体 其二","f":"五言古诗","c":["丈夫人天师，夙生大智慧。","了悟开顿宗，修持入不二。","自得黄梅传，广开众生昧。","至今青莲宇，宗门各精诣。","云生法座上，月照空潭际。","潺潺曹溪声，客思不遑寐。"]},{"t":"登郁孤台奉柬开府李公台","f":"五言古诗","c":["躧步陟崇冈，冬序正萧索。","孤台郁然峻，国顾尽寥廓。","千峰带郭起，二水绕城落。","霜华薄彩旃，朔气吹晓角。","胜览即要区，于宣在猷略。","武旅久偃息，儒风宁寂寞。","明公时秉钺，大府雄蛮落。","地以今镇重，道继前贤作。","恬寂实素衷，荣途厌蜷踔。","昔遇方下车，兹游值卧阁。","揆予闇知足，山隐未能确。","泉石有前期，风尘违夙诺。","登高骋遐瞩，驰思入玄漠。","岁晏滞芳游，心赏何由托。","愿因元公言，归寻孔颜乐。"]},{"t":"丁大参刘参戎邀游虔州光孝寺看二井","f":"五言古诗","c":["良游荷胜招，忽与人境别。","木落山更苍，地暖气初冽。","稍寻奇俶观，遂竟灵异说。","境缘二井胜，事匪茫昧设。","灵气通山泽，寒潮应海月。","甘液岂泉蒙，春流因雷发。","妙理信中感，神机岂外泄。","汲同神瀵滋，饮异醴源竭。","山根潜地肺，水道走石穴。","久闻有此言，每令心赏绝。","游思六合外，归补水经缺。"]},{"t":"淮上赠李道甫中丞 其一","f":"五言律诗","c":["春风渡长淮，河水深且广。","砥柱复安在，洪流方震荡。","中路逢佳友，偕我济川舫。","岂忘同舟言，共此风涛壮。"]},{"t":"淮上赠李道甫中丞 其二","f":"五言律诗","c":["群贤翌天造，济济拖朝绅。","汉廷多公卿，黯也社稷臣。","双阙高巍巍，连章动星辰。","而我乏远谟，匡时谬许身。"]},{"t":"淮上赠李道甫中丞 其三","f":"五言律诗","c":["幽兰无改芳，贞松不渝节。","感君缟带赠，被服如霜雪。","悠悠历山陂，行行杳燕越。","晤言接容辉，终岁常揽结。"]},{"t":"淮上赠李道甫中丞 其四","f":"五言律诗","c":["芳草有奇姿，直木无曲干。","结交为兄弟，黾勉涉世难。","临分理妙曲，闻者窃惊叹。","知音谅不违，衷情自此见。"]},{"t":"忝珠篇赠张孟奇寿母","f":"五言古诗","c":["罗浮女真宅，忝珠岩壑重。","下临云母溪，上接玉鹅峰。","昔日㛹娟子，于此炼玉容。","玉鹅腾云驾，云母倚月舂。","风凄琼液冷，日暖金膏溶。","霓裳月下飏，瑶草霜前茸。","袅袅绿云间，锵锵环佩逢。","自馀众女仙，霞袂纷相从。","洞中命鸾鹤，天外摘芙蓉。","君家住其下，卜筑蹑前踪。","归来奉篮舆，时往策仙筇。","玉女鲍何辈，颜色桃李秾。","遗尔紫霞酌，缄之白云封。","懿此北堂护，茂彼南涧松。"]},{"t":"释志诗 其一","f":"五言古诗","c":["夙昔寡欢宴，况乃涉疑患。","滞思废寝兴，沉忧昧昏旦。","筮仕乏良媒，所历非华贯。","牵丝将二纪，述职在文翰。","退即失寻丈，进不能以寸。","岂其席上珍，而比沟中断。","狂者类东走，劳人正南窜。","未解子云嘲，且答方朔难。","闻誉匪为喜，止谤曰无辨。","揆情有爱憎，审己何尤怨。","无以布褐贱，荣彼绅与弁。","无以藜藿贫，甘彼五鼎豢。","巾柴可游遨，奚取朱轮焕。","孰是终徇物，而忘性所玩。","对丝发遥悲，临歧兴浩叹。","归欤且吾乐，所乐非外赞。"]},{"t":"释志诗 其二","f":"五言古诗","c":["泾浊渭则清，举世昧其光。","昆丘烈燄起，玉石咸见殃。","骐骥避骀驽，鸱鸮逐凤皇。","萋菲一为吟，千载同嗟伤。","嗤嗤便佞子，多言巧如簧。","众庶皆有心，彼独何无良。","凡百我在位，谋虑用不臧。","诲淫者冶容，致盗由慢藏。","神龙宅九渊，玄豹处重冈。","蜂虿而窃乘，壮夫失其强。","大雅贵明哲，君子慎周防。"]},{"t":"盘松篇夏日陪诸公饮报国寺盘松下共赋","f":"五言古诗","c":["炎氛扬火宅，万物赫以暵。","偶践清凉境，获此嘉树玩。","种植自何代，蓊蔚若崇巘。","冉冉烟黛浮，团团盖阴转。","昔闻耸仙岭，今见盘佛殿。","托根水晶域，布叶雨花院。","婆娑覆广除，森沉隐遥汉。","风霜讵摧折，虬螭互奔窜。","夏云垂迥荫，秋涛起层澜。","既异恶木阴，幸免不材叹。","暂乖栋梁用，永离斤斧患。","无用形不累，有节凋宁先。","屈蟠岂其性，偃蹇庶自善。","君娱匝地枝，宁惜参天干。","青黄文牺樽，曲直传马栈。","终全社栎年，共保灵椿算。"]},{"t":"夏夜遣怀","f":"五言古诗","c":["向夕氛气敛，天宇一何森。","皎月正临牖，微风时动林。","夏虫岂知冰，迎凉自悲吟。","端居感物变，旷然坐自深。","沉叹终往古，幽思缠鸣琴。","黄虞世已远，悠悠空我心。"]},{"t":"杪夏集徐园","f":"五言古诗","c":["命侣出皇坰，税驾水之浒。","高下见林莽，飞潜散鳞羽。","维时夏秋交，凉风变徂暑。","棱棱霜台俊，幽期协心许。","选胜匪自今，兹游亦已屡。","追念向来辈，无一今晤语。","花木识故蹊，池亭非旧主。","芳塘未改流，颓城尚遗堵。","转盼即陈迹，况复论终古。","我闻达士说，天地为逆旅。","何者是长物，而能久留处。","浮白且尽觞，谈玄但挥麈。","一醉兀自然，此外非吾取。"]},{"t":"从武选郎徐君社长问禄命","f":"五言古诗","c":["太极运两仪，变化万形随。","譬彼大垆冶，镕铸一何私。","如何巧智士，谓力能胜之。","得时者称贤，势在山可移。","岂知元命中，茫昧不可欺。","达人睹其然，不惑复奚疑。","荣华众所艳，弃之轻如丝。","寂寞众所去，处之甘如饴。","失马宁非福，亡羊信多岐。","渴饮清泠泉，饥食西山薇。","逍遥放情志，身与元化嬉。","闻君得秘要，细用此道推。"]},{"t":"奉和六月十四夜起对月","f":"五言古诗","c":["羁人易为感，久客难为悦。","闻君中夜起，爱此林上月。","素影流轩墀，清光对城阙。","井上梧阴多，檐际露华结。","在物忌太盈，处圆先虑缺。","及此未圆时，冰壶坐自澈。","珍簟已迎凉，纨扇将辞热。","轮满即亏候，暑退成寒节。","并起千恨端，弥伤万里别。","还寐复何如，佳期杳燕越。"]},{"t":"翔凤篇答汪公干时四家兄亦和此篇","f":"五言古诗","c":["紫凤飞南海，徘徊恋天池。","岂无三珠树，归守椅梧枝。","逢君问出处，所需在明时。","本期千仞翔，览德而下之。","文采非惊世，宁为燕雀欺。","尝闻帝王代，衔图及鸣岐。","时哉不我与，蒙议于德衰。","稻粱不肯啄，终岁常苦饥。","东园琅玕实，倘许共来仪。"]},{"t":"崧山纪异赞","f":"五言古诗","c":["我闻西方尊，接引为慈仁。","从其所修受，而别善恶因。","峨峨南崧山，胜地久荆榛。","梵宇日倾圯，金像空嶙峋。","大夫买山隐，转念像教湮。","舍宅重布地，移佛动金轮。","接引何为者，人力不能伸。","大夫祷以意，倏然举行频。","捷如鼓答桴，轻如筏渡津。","灵蛇口中出，经藏腹内陈。","中有梁皇谶，姓名犹未泯。","乃悟前身是，始觉受记真。","秋官尔应知，指穷于为薪。","薪尽火复传，咸在当生身。","修持若不倦，世界即天人。"]},{"t":"移寓圣安寺僧舍作","f":"五言古诗","c":["希世无高步，久游廛市间。","夙昔东山意，归期亦屡愆。","履道尚云错，行险岂得安。","投足来净宇，精心窥妙门。","高论支许接，逸驾禽尚攀。","心静水晶域，耳聆甘露言。","隘此方内游，驰彼域外观。","归鳞纵壑逝，宿鸟投林还。","岂惟耽寂灭，于焉寄游盘。","终同无名子，灭迹去人寰。"]},{"t":"中秋夜对月叙怀","f":"五言古诗","c":["零露靡百草，素节渐为霜。","宛宛月中桂，孤高徒自芳。","上枝荫琼宇，下枝神鹊翔。","吴刚小儿辈，持斧莫轻戕。","玉兔捣灵药，千载秘其方。","嫦娥顾而笑，天风落霓裳。","我欲按此曲，因之寄异乡。","异乡不可致，凝思结中肠。","徘徊览明月，河汉永相望。"]},{"t":"汪公干从燕台送余至济上叙别兼寄别和叔 其一","f":"五言古诗","c":["古来重交谊，岂不在命驾。","君从燕山阳，送我任城下。","所历千里馀，四顾尽平野。","览古究天人，观代陈王霸。","久堙稷下谈，孰重燕台价。","怆恻乐生去，慷慨聊城射。","苍茫齐鲁墟，贤圣何凋谢。","抚迹劳我思，感时伤物化。","乐饮慰穷愁，悲啸激长夜。","我行适旧都，子还依旅舍。","去帆天际遥，归鞍日边卸。","片语难久留，馀辉恋桑柘。","磊落平生怀，晤言用自写。"]},{"t":"汪公干从燕台送余至济上叙别兼寄别和叔 其二","f":"五言古诗","c":["吾昔游上都，邂逅得二汪。","谬蒙倾盖知，所知遂不忘。","既我晚际遇，翰墨颇见长。","二汪适不偶，空谷有芬芳。","栖迟恋衡门，隐迹寄卖浆。","相与讨文义，昕夕共徜徉。","笙竽间琴瑟，歌吹六艺场。","今予遭薄谴，于世尽炎凉。","惟子不忍弃，时来访行藏。","古人叹罗雀，今乃见糟糠。","予适有远行，相送千里疆。","长路思屏营，执手以傍徨。","翩翩凫与雁，将翱复将翔。","朝嬉仍共浦，夕宿各一方。","谷风箴义缺，白驹咏食场。","素交终不替，是道足以臧。","谊敦古所难，申咏于斯章。"]},{"t":"题黎惟仁对江楼","f":"楚辞体","c":["江上春云散春渚，为楼恰对云生处。","有时欹枕听涛声，长日褰帘望江树。","楼居仙子何所有，万卷经书一壶酒。","胡床箕踞少人事，满目烟霞但搔首。","江水东流绕越台，珠溟穗洞差参开。","闲呼江鸟过朱槛，坐引江花泛绿醅。","楼有江兮江有汜，思佳人兮不能已。","江月明兮谁共登，江风起兮君独倚。","清响云中读楚骚，琼窗偃卧江天高。","楼前岁岁桂花发，愧尔篇诗江上豪。"]},{"t":"赠宪府王公治水歌","f":"古风","c":["黔漓奔腾灌牂牁，西倾万里扬洪波。","寻常桂浦经过少，荡潏金沙似浊河。","今年燕京四月风霾连朔漠，狐裘蒙茸雪花薄。","诏书日恐时令乖，厥占大水飘城郭。","经秋霪霖天欲漏，河伯望洋更东走。","两涯不辨牛马群，万峰倒蹴蛟龙吼。","双峡束流截奔马，崩涛怒号不得下。","瀰漫但见苍梧云，溟泛那知洞庭野。","洪荒之事谁能辨，眼底俄惊桑田变。","市上渐见游釜鱼，幕中岂有归巢燕。","激石穿堤未云已，冲波直捣孤城里。","险极难论薪竹功，事急宁得芦灰止。","是时城中万室命如丝，蚁穴恐溃千金陂。","宪府行营苍水使，群僚亦秉玄夷麾。","挥戈欲斩蛮云愁，投鞭东断沧波流。","胼手胝足不言瘁，烈风淫雨有时休。","转见越裳称海晏，知君才是济川舟。"]},{"t":"仙羊石","f":"七言古诗","c":["山中牧羊人不识，累累松间成白石。","秋风琪树乱呼群，夜月清苔照行迹。","仙人叱羊羊尽起，自言身是瑶台子。","早晚赤松游不稀，数逢王质采樵归。","传书更报初平道，骑向何峰拾瑶草。"]},{"t":"三家兄平明发舟归?川别后寄此","f":"古风","c":["扁舟石门里，双棹荡孤烟。","日夕望江树，彷佛见?川。","原上鹡鸰沙中雁，一水相连不道远。","稚子早攀岩桂待，行人独忆云松返。","惜是东西南北人，十年漂泊尚迷津。","平明送兄返田舍，薄暮思家泪满巾。"]},{"t":"题王学士忠铭先生山中四景 其一 文笔晴烟","f":"七言古诗","c":["云表岧峣玉毫吐，点画鸿蒙扫烟雨。","丰狐老兔愁锋芒，象齿文犀安足数。","长虹一道界奎躔，明霞万里飞琼笺。","泚墨欲乾溟海水，笔势撑住东南天。","早晚风云殊变态，山灵握管有何意。","紫阁归来翌圣明，玄草长留照天地。"]},{"t":"题王学士忠铭先生山中四景 其二 金鸡春晓","f":"七言古诗","c":["玉衡之精化为石，朱霞作冠金作翼。","潮头阳乌射琼岛，岛日曈曈送春晓。","此山恰与桃都连，云里长鸣声向天。","海峤疑开不夜城，飞仙往往候鸡鸣。","宫梧今傍凤凰栖，天上还先众鸟啼。","莫学汝南人舞剑，须听王褒颂碧鸡。"]},{"t":"题王学士忠铭先生山中四景 其三 石垄马鞍","f":"七言古诗","c":["房星落地仙灵驭，渡海潜行不知处。","有时风雨尚闻嘶，石垄高鞍待谁据。","回身似就琼波饮，落日千山散云锦。","羲和总辔势莫动，孙阳挟策翻神耸。","南望天池似渥洼，至今山下多龙种。","龙种谁骑出九真，汉家铜马在枫宸。","不信人间金騕袅，听呼天上石麒麟。"]},{"t":"题王学士忠铭先生山中四景 其四 桥头碧水","f":"七言古诗","c":["建溪泠泠漱花坞，紫鳞白石纤可数。","练影晴披琼馆云，镜光直泻明珠浦。","碧玉环流学士家，桥南桥北问桃花。","当年意气看题柱，此日秋乘上汉槎。","桥头一别几经春，溪鸟啼花莫待人。","瀛洲亭上玻璃色，藜杖寻溪安可得。"]},{"t":"金镜篇","f":"七言古诗","c":["金轮铸就阴翳没，玉台捧出清辉发。","纵使妍媸任爱憎，已能冰雪侵毛发。","宝匣何曾暂晻暧，尘埃岂得沉光彩。","玉兔长生明月楼，菱花不隔秋潭水。","扬子江心百炼铜，文盘五位飞天龙。","共道写形归汉苑，何论照胆出秦宫。","本图鉴古亦鉴今，讵云照面不照心。","一尺寒光近不得，三秋云雾虚愁阴。","旧侍仙人乐紫霞，曾将精白献皇家。","不向宫中妆粉黛，特来殿上烛忠邪。","美人拂拭意良厚，绣阁鸾沉待君久。","此日衣冠际太平，君王内殿庆长生。","愿输金镜瑶台下，常比光华寿圣明。"]},{"t":"和韩昌黎石鼓歌","f":"七言古诗","c":["岐阳石鼓传周宣，神武尚纪中兴年。","抠衣曾肃文庙拜，访古更读昌黎篇。","车攻马同事已往，俯仰遗迹心茫然。","大小二雅不收载，纵横数石遗刻镌。","忆昔宣王按剑起，整顿周纲恢八埏。","南伐淮徐西猃狁，出车命将声喧阗。","天子明堂登玉帛，诸侯冠佩趋游畋。","于时岐阳纵大猎，前驱六马势腾骞。","戈甲照耀军容盛，从臣一一皆材贤。","不独清风能作颂，亦有羽猎如甘泉。","武功万代宜宣示，伐石作鼓夷层巅。","龙画撑持结构古，螺书诘曲镵戈鋋。","日炙霜侵不知岁，鸾漂凤泊沉荒烟。","祇疑鬼物为呵护，封埋古刻苍苔鲜。","文义颇类小雅作，字体翻从史籀迁。","六百七十有二字，纷挐螭虎握玑璿。","年深缺划固不免，奥义高文止半全。","章樵考正力颇苦，薛郑音训心仍虔。","曩时韩公称好古，低徊石侧涕沦涟。","摩挲铜狄叹岁月，剜苔剔藓细品诠。","发为歌词极赏识，今文古文相并悬。","陋儒褊迫不解事，虚令世代差讹传。","隋珠几同鱼目混，和璧翻成燕石捐。","五帝存亡皇有无，峄山梁父几封禅。","神禹丰碑閟岣嵝，轩黄宝鼎沦伊瀍。","犹幸此鼓在人世，晨星累累映奎躔。","岐山较猎或代有，左氏编年岂误沿。","吁嗟此石何从得，自岐徙洛复入燕。","置之辟雍戟门里，衣冠讲解得究研。","予生际此不恨晚，至宝及睹周秦前。","方今宇内幸无事，嘘吸皇风万里旋。","诸生盛讲中兴事，朝士争歌雅颂编。","镌功勒成告下土，愿比成周致太平。"]},{"t":"阅管中书紫宸宣对卷有感赋赠","f":"七言古诗","c":["丈夫遇合会有时，怜君工画复工诗。","数谒公卿无所就，频游京国少人知。","一朝召试金銮殿，公等何来晚相见。","画毕中官催进御，诗成内诏传清宴。","昨年天子好经术，词臣进讲无虚日。","出从台谏论安危，入与宰臣计得失。","犹有馀力及风雅，翠幄云楼两潇洒。","笔札小儒皆见亲，布衣贱艺还优假。","管生后来在众中，解衣盘礴对王公。","惊人诗句及绘事，往往落笔称才雄。","九重燕赉赐官爵，一旦姓名动台阁。","但知今日等荣华，谁识当年暂流落。","是时区生困羁旅，闻之自笑仍自许。","本持薄技亦蒙恩，况以奇策干明主。","兹来侍从文华直，见君凤沼开心臆。","幸逢虞帝正垂裳，更值殷王好恭默。","虎豹沉沉隔九关，无事经帷尽日闲。","卿相寻常稀召见，微臣安得窥龙颜。","吁嗟管生遇亦奇，主父买臣曾有之。","假令君才在今日，纵欲承恩何所为。"]},{"t":"功德寺看牡丹歌","f":"七言古诗","c":["去年看花花未发，今年看花花已阑。","何事与花常不值，花期误却为微官。","解道天香与国色，只馀绿叶护僧栏。","沁水园中车马寂，洛阳城里管弦残。","香色从来不耐久，春光到底为谁有。","若使花开常不落，安得红颜成白首。","红颜白首暗相催，把酒逢花能几回。","僧徒劝我勿惆怅，明岁花时可重来。"]},{"t":"方生行","f":"七言古诗","c":["方生手持白虎文，过我顾啸生风云。","饮酒何辞一石醉，下笔欲扫千人军。","昨朝奏牍来燕市，争道骅骝日千里。","雄篇往往惊前辈，高论纷纷屈馀子。","为德从来自有邻，在世岂应无知己。","只言献赋动明君，谁料当年未策勋。","不遇荆人徒抱玉，待逢伯乐始空群。","高才郁郁今如此，薄俗悠悠安足云。","君家严君亦奇磊，海内才名三十载。","当年意气满乾坤，至今迁谪流江海。","贤豪尽下汉公卿，落拓三为州刺史。","五马朝辞北地霜，片帆春送西江水。","豫章参天白日动，丰城气薄风雷徙。","方生方生岂但尔，好去共称名父子，万里之行自此始。"]},{"t":"琴剑篇","f":"古风","c":["匣中有剑囊有琴，美人昔赠双南金。","琴是峄阳之古桐，凝烟拂雾高冈岑。","百鸟过之徊翔而不敢下，丹穴之禽经此留遗音。","剑是昆吾切玉之劲铁，秋星为铓雪作镡。","才动金环神鬼泣，未离宝匣蛟龙吟。","一从轩辕战涿野，崩云挥日光华夏。","一从有虞奏南薰，卿云白雪流雰雰。","感君赠我意，我行双佩之。","风烟万里不自保，行藏千古宁须疑。","一片清霜吐莲锷，七弦流水含金徽。","剑以待风胡，琴以待钟期。","世间听曲皆里耳，谁能为我辨雄雌。","近闻塞上风尘起，胡骑纷纷渡辽水。","又闻帝室赓明良，正风合雅从古始。","吾将拭我青萍，拂我缘绮。","三战为君渫胡血，再鼓为君洗俗耳。","行令四海无妖氛，还坐清风竹林里。"]},{"t":"内阁栽莲","f":"七言古诗","c":["濯濯新荷出波小，紫阁栽培值春晓。","移种疑从玉井来，托根偏向瑶池好。","预拟开花映玉堂，绝胜照水溢金塘。","风归渐拂亭亭盖，雨过初闻细细香。","阁内主人爱莲者，每道群芳出其下。","已添新水净淤泥，更着疏阑助潇洒。","旧种吾家绿玉池，淡烟微雨蒂双垂。","即此一茎栖瑞露，犹堪千叶上灵龟。"]},{"t":"酒肆行","f":"古风","c":["燕京酒楼临紫陌，綵帜璇题高百尺。","时时车马会填门，夜夜笙歌解留客。","近出铜驼路，远连平乐苑。","青骢白晰谁家郎，飞盖挥鞭不辞远。","垂柳垂杨二月天，好风好日百花筵。","蒙茸紫貂过肆外，婀娜红粉倚垆边。","古来豪侠不顾利，一斗十千宁惮费。","几人能向酒家眠，几人能辨酒中味。","高阳之徒识者稀，相逢拚饮日西移。","鹔鹴典尽君沽否，世上尘埃谁得知。"]},{"t":"梅花歌","f":"七言古诗","c":["家住罗浮山下村，千株万株对柴门。","一一峰头种梅树，家家宅畔有梅园。","忽惊海上春光早，转觉山中花事繁。","开时雪障炎天白，飘处香浮海月昏。","石湖处士空留品，官阁诗人且细论。","满目瑶华难辨蕊，千丛琼片不分根。","素禽栖处翻疑影，粉蝶飞来暗断魂。","拄杖穿林皆踏雪，荆扉照水半迎暄。","初经峍屼深溪口，复过横斜浅水源。","何处临风无玉树，谁人吹笛坐琼轩。","别有娇娆新约素，霓裳鹤驭来缤翻。","汉水游妃朝解佩，瑶台仙子笑无言。","冰帘半捲银环出，珠户斜开玉手掀。","此际游人初入梦，此时芳霭绕啼痕。","参横月落愁翠羽，霜白天清吟断猿。","自从离却梅花国，万树斜阳今几存。","北风十日地欲裂，冷尽孤根只数盆。","深洞移来春欲到，纱窗闭处火微温。","金马朝回看点额，玉人妆罢共开樽。","东风传语庾关信，独把南枝向塞垣。"]},{"t":"大雪林维烈南发以诗留之","f":"古风","c":["燕京春来十日雪，封瓦填池三尺深。","街北小台压欲倒，城南古道没难寻。","芦沟冻合桑乾水，碣石寒凝黍谷底。","宅里惟便高士卧，街前空笑先生履。","南客此时正望家，四顾茫然生怨嗟。","当门驴子缩如猬，未行先倒路复赊。","怜君怀归思转剧，道阻雪深归不得。","安得赤脚踏层冰，恨不随风生两翼。","苑西书楼连汉上，披帷对此多心赏。","苑东酒楼高刺天，当垆小妇鸣管弦。","劝君不如且留读书饮酒过寒节，犹胜蹇驴出踏雪。","直待春江花鸟繁，看花听鸟还故园。"]},{"t":"双节篇","f":"七言古诗","c":["严霜一夕殒庭梧，洞房风凄兰蕙枯。","含啼两两谁家姝，中夜起坐泣故夫。","昔事君子结发娱，百年生死同衾襦。","奈何辞君岁月徂，荆花零落委路衢。","不惮从君下黄垆，一身俯仰多艰虞。","上堂吞声奉老姑，下堂呱呱抚诸孤。","大妇善哭崩城隅，小妇香泪纷鲛珠。","中庭灯影伴将雏，后园啼杀羁栖乌。","吁嗟二妇烈士徒，青春誓志白首俱。","金石可毁节难渝，冰日皎洁双璠玙。","朱颜岂受粉黛污，绣闼实使纲常扶。","史家列传增烦纡，吁嗟二妇良女模。"]},{"t":"黄河鲙鲤歌和四兄","f":"七言古诗","c":["大河流水何汤汤，中有鲤鱼三尺长。","独茧之丝不能钓，贯以杨枝谁致将。","兄谓食鱼必河鲤，出水鲜鳞宁有此。","盘餐称意不论钱，鲙事吾乡最为美。","呼童霜刃三四挥，香醪浮动雪花霏。","大醉不知身是客，酣歌只觉兴如飞。","江乡六月足风涛，荔枝压酒冰盘高。","扬舲醉卧乘流去，且欲从君鲙巨鳌。"]},{"t":"圯上行","f":"七言古诗","c":["子房当日横意气，志在报韩功不济。","留城未即归汉王，博浪先因击秦帝。","避难潜行过下邳，复仇无计虑穷追。","道逢老人呼拾履，心固不欲强然为。","老人家在谷城下，往来圯桥无识者。","高步矫矫如惊鸿，堕履翩翩若飘瓦。","子房跪进一何恭，老人坐受甚从容。","顾谓孺子为可教，授以素书成帝功。","更期后日访黄石，或约他年游赤松。","此事相传亦奇诡，风云感会良有以。","不见祠前东流水，古来上德皆如此。"]},{"t":"昨游姑蔑徐氏园见林开先题壁兹过上饶费氏馆见朱贞吉留题凄然有作","f":"七言古诗","c":["登山临水几心伤，问柳寻花亦断肠。","已觉姓名成故物，岂知风景在他乡。","昔年与子共行乐，金谷名园恣欢谑。","只疑英誉早飞扬，忍见高才遂沦落。","开先洒翰本清真，贞吉题诗合有神。","自从知音无二子，可怜肝胆向何人。","忆昨徐园观林字，醉笔淋漓有生气。","今朝费馆见朱诗，往往烟霞极奇思。","故人笔迹一何多，岁月精灵未耗磨。","处处风光留客在，思君不见奈愁何。"]},{"t":"山园春日歌","f":"七言律诗","c":["山园景物系人思，好是风光二月时。","歌爱鸟声喧别院，舞将鱼乐过前池。","檐桃初结花间子，阶笋才抽雨后枝。","自可王孙留碧草，尽堪游子驻金羁。"]},{"t":"浮丘仙洞歌","f":"古风","c":["珊瑚井底流金沙，菖蒲涧畔飞琼霞。","林里时藏蓬岛路，城头半出羽人家。","羽人家住朱明日，却辟此丘为户牖。","邀客常教白鹤迎，烧丹却倩青龙守。","丹池别后依然在，琪树种来皆已大。","海阔全凭一鸟度，天空不遣片云碍。","此丘往时在海中，三山烟雾晴濛濛。","今日丘林带城郭，惟馀海月一片挂长松。","眼见碧水又飞尘，令人却忆扶桑东。","扶桑枯海水竭，仙人缘鬓翻成雪。","赵客梦中啼翠羽，葛公坟上飞黄蝶。","物外之谈诚恍惚，世间何事无消歇。","层城瑶池不足游，我欲乘龙何处求。","纵使千年归一度，不如日饮美酒扬清讴。"]},{"t":"?川花树歌","f":"古风","c":["正月二月春风微，?东?西花乱飞。","着水才冲青雀舫，因风复上白鸥矶。","此日一杯人易老，他时千树春能好。","总令游子步常迟，更虑行人归不早。","飞花往往别前轻，白发年年离处生。","芳草但知萦去骑，绿杨何用送流莺。"]},{"t":"阮溪行","f":"七言古诗","c":["云溪一道绕村流，密树疏篁夹岸幽。","傍分沟洫膏农亩，曲引江潮鉴画楼。","溪上衣冠数百家，家家园圃种桃花。","因风忽散千丛锦，映水时窥一片霞。","别筑溪亭临水住，粉壁朱窗小桥渡。","钓艇谩劳渔父寻，花堤似入仙源路。","日出烟皋农务繁，风清竹下桔槔喧。","耕凿但知尧日月，居人能说汉乾坤。","本藉桑麻为世业，更传经史与儿孙。","处处书声连薜荔，年年生事满田园。","鱼跃芹池新浪活，燕巢水槛旧坭乾。","灌芝浇桂随宜汲，泛月流云自有源。","别溪多年今又去，溪水留君君不驻。","嬥嬥干旄村里出，填填车马溪前度。","老稚牵衣劝莫行，溪田数亩好春耕。","回看社外桑榆景，转念溪边花鸟情。","行人不语步迟迟，富贵逼人诚有之。","殷勤为扫溪头石，待我功成理钓丝。"]},{"t":"颍阳三月雨雪歌赠丁元父","f":"七言古诗","c":["颍阳山中三月雪，拂石点苔映春月。","行人三日嵩峰游，欲行不行心断绝。","古称洛邑天地中，三月胡为尚朔风。","岩前看竹微微翠，涧底寻花悄悄红。","登封主人有异政，去国忧谗时卧病。","无乃此事干天和，不然何以乖时令。","世途反覆那可知，把酒且唱游仙词。","雪晴驱马朝天去，尔对三花采寄谁。"]},{"t":"邺都行","f":"七言古诗","c":["汉家末运罹崩分，群雄割据乘风云。","曹氏提戈窃汉鼎，邺城草创淩天阍。","京邑横跨西山趾，楼台半出漳河水。","呼吸风云百万师，指顾山河五千里。","战罢归来校文士，草檄徵词各称美。","列坐既多能赋人，西园亦有佳公子。","邺都歌舞日纷纷，建安词赋气淩云。","北堂艳妓输乔女，南国佳人让洛神。","只谓千秋终宴乐，谁知转眼成灰尘。","人间幸有三分业，地下曾无九锡文。","兴亡今古一飞鸿，豪杰经营总是空。","铜爵台基沦蔓草，芙蓉园馆委秋风。","若道繁华无寂寞，试问当年安汉公。"]},{"t":"铜台引","f":"古风","c":["君不见魏帝当年号神武，气吞吴蜀势如虎。","已开广殿会文英，更筑高台贮歌舞。","翠钿杂沓罗甲帐，词赋缤纷列簪组。","一朝运去霸业空，千载流传妇儿语。","没后惟馀粉黛恩，生前误作山河主。","台上君王去不回，帐下美人歌自苦。","昔时富贵等浮烟，今日蒿莱满环堵。","铜台西望不堪思，漳水东流无尽时。","春鸟如歌又如恨，至今犹是望陵悲。"]},{"t":"邯郸道","f":"古风","c":["突骑如流星，飞过邯郸城。","千人皆辟易，不敢问姓名。","报仇轻赴敌，使气重横行。","相逢鲁勾践，识是燕荆卿。","使气从来不相让，博肆喧喧竞争长。","心知欲语口难言，作意叱君君未谅。","荆卿归去西入秦，其事不成空殒身。","惜乎不讲刺剑术，看作悠悠饮博人。"]},{"t":"陌上桑","f":"七言古诗","c":["邯郸大道好经过，邯郸少妇采桑多。","琼窗日出褰珠箔，绮陌春还驻翠娥。","只道蚕饥思摘叶，谁怜腕瘦复攀柯。","芳尘艳艳飘轻縠，香风习习曳纤罗。","春花千种比颜色，春鸟百啭杂笑歌。","初从枝上悬青桂，转过城南踏绿莎。","红袖此时调宝柱，白面谁家鸣玉珂。","使君执谊谅不薄，贱妾持心亦靡它。","秦家自有东方骑，五马踟蹰奈若何。"]},{"t":"丛台行","f":"古风","c":["武灵王，何雄哉，胡服骑射屈群材。","略地云中西入秦，秦人惊起函关开。","雄心日暮犹未已，百尺高台更丛起。","才人尽解邯郸步，鼎士俄成袨服市。","鸳鸯宫瓦碧琉璃，玳瑁朝簪灿陆离。","十里管弦声不断，春风吹入照眉池。","自从内变起床第，千秋霸业随流水。","玉辇金舆不复行，层台渐圮曲池平。","坑卒仍闻四十万，偿璧虚当十五城。","君不见邯郸夜拔丛台宴，酒酣昼卧温明殿。","莫将天下属他人，英雄为谋自有见。","歌舞能令壮志消，古来祸败由荒宴。","君不见邯郸道上逢吕翁，千古豪华如梦中。"]},{"t":"过真定李巡抚出访谈岭海旧事","f":"古风","c":["南逾梅鋗关，北涉滹沱水。","井陉桑柘挂斜阳，云是尉佗旧时里。","尉佗当日窥南服，黄屋乘舆连左纛。","老夫帝号窃自娱，汉世玺书勤讲睦。","陆生片语何雄哉，北首同登朝汉台。","全胜楼船南下日，好过终军系颈来。","中丞熊轼抚全赵，越王旧里几临眺。","忆昔提戈静海烽，此日登楼共长啸。","草莽遗踪何用伤，铜标旧事转荒凉。","天书倘借前矛去，更上高台吊越王。"]},{"t":"顾正谊画山水歌","f":"七言古诗","c":["顾君自神其画品，往往不在宋元下。","丹青妙手世罕传，当代沈文此其亚。","兴来一幅生绡帐，恍惚峦涧开茅堂。","炎天赤日不到地，四座飒飒枫杉凉。","烟云咫尺藏变态，丹台石室知何代。","隔岸人家花映溪，小桥却在溪烟外。","前山合沓势峥嵘，绿水不动波无声。","万壑千岩忽满眼，对之使我心魂清。","忆昨归山采瑶草，结屋诛茅苦不早。","眼底平看沧海流，杖头忘却苍梧道。","闻君早晚向吴淞，鲈鲙莼羹秋兴浓。","便好高图钓鲈石，添作吴江江上峰。"]},{"t":"季冬朔夜饮酒歌","f":"古风","c":["玄夜沉沉钟漏咽，高馆燃炉丝竹折。","冻云肃穆凝清汉，薄雪参差露微月。","主人有酒千斛馀，岂合善价求沽诸。","太常斋后偏宜饮，相国园中薄剪蔬。","人生志愿何时足，取快目前适所欲。","昆虫鱼鳖皆有命，何忍驱来实吾腹。","香厨素馔本芬芳，况有紫笋白盐胜膏粱。","得遇醉饱且为乐，安用八珍五鼎腐肠之食充圆方。"]},{"t":"闺中闻子规","f":"七言古诗","c":["玉楼绮窗朝日晖，百花声中闻子规。","憔悴林莺浑不语，差池梁燕未堪飞。","绕遍南枝又北枝，可怜千春伤别离。","直从桂岭花开日，啼到巴川花落时。","巴川桂岭春难驻，越南燕北路多歧。","几处听来皆下泪，谁家闻去不低眉。","佳人玉箸垂红颊，朱颜坐叹芳菲歇。","览镜慵图两鬓鸦，停针懒绣双飞蝶。","长安大道皆言直，梦里相寻转相失。","徒闻泪血染成花，岂料贞心化为石。","含愁含恨诉香闺，想料枝头只独栖。","但令贱妆惊鸳梦，不劝行人驻马啼。"]},{"t":"正月十六日双寿歌","f":"古风","c":["青鸟海上来，衔书置君堂。","书中何所道，仙字八九行。","灿灿赤玉文，叠叠紫泥香。","上言圣世得贤良，下言翁姥偕寿康。","翁姥授书起，两两长跪迎天祉。","顾为青鸟言，惟我二人，佩仁行义。","若纤尘在泰山，涓潦在海水。","何能一旦感动天，皇天锡佑无穷纪。","绥山桃实成并蒂，东海扶枝作连理。","又有玉皇香案吏，绣衣白简称吾子。","韶华二八早春朝，火树千层接绛霄。","翁姥降生同此日，绣衣衔命新下朝。","天书乍听皇华咏，南国先传骢马谣。","骢马承恩向南极，登车正上扶桑日。","命服何须玳瑁簪，甘滫讵假琅玕实。","此中洞天福庭，有碧草朱华金砂玉屑，服之寿与天地毕。","观风若上瑶台望，取致高堂胜怀橘。"]},{"t":"谭母寿歌","f":"七言古诗","c":["大儿行年七十馀，矫如海鹤淩烟墟。","为官岂必登卿相，得俸已足供亲娱。","小儿行年六十四，壮志翩翩若奔骥。","昨辞亲舍叩帝阍，今拜儒官过乡里。","近闻小儿赴文僚，犹记大儿曾入朝。","三釜从知屈捧檄，五斗何曾轻折腰。","借问高堂今何岁，两儿垂白堂前戏。","承颜徇禄各有人，长已归田少者仕。","谩说麻源是女身，须知南岳降夫人。","回看桂海鸾长度，却望绥山桃自春。"]},{"t":"闻西征中路官军消息 其一","f":"七言古诗","c":["东方血光明组练，中路官军殊死战。","马兵先溃步兵乱，四五十里横尸遍。","将领几人虽幸免，尔纵生还有何面。","吾闻定远昔策勋，三十六人横塞云。","岂有十万貔貅士，不能一剪鲸鲵群。","成功必更需名将，失道宜先斩败军。"]},{"t":"闻西征中路官军消息 其二","f":"七言古诗","c":["自从西征劳士马，六七年间谁主者。","溪谷量人乌厌肉，举声向天天泪下。","朝廷任用在得人，枉令赤子膏原野。","飞刍挽粟不得停，民穷彻骨复横征。","人言东海深无底，填尽物力何时平。","不如表请暂回军，休养士卒求内宁。","明王有道四夷服，安用越国寻兵争。"]},{"t":"石门行","f":"七言古诗","c":["石门啾啾鬼夜哭，北将诈诱南兵缚。","可怜枉死三千人，更有平人被屠戮。","忆昔平壤破倭奴，此辈赴难曾捐躯。","有功谁分不蒙赏，无罪因何反见诛。","本为勤王诬以反，阳言赏给屠俱尽。","皇天闷闷旌旆愁，白日瞆瞆风沙愤。","从来杀降受恶名，况以私憾杀我兵。","无人肯向朝廷说，至今道路犹吞声。","谁其为谋石与李，尔曹安得逃天刑。"]},{"t":"纪朝鲜","f":"七言古诗","c":["自有东师六七载，庙堂岁岁议封贡。","近者群公幸主战，折将隳军竟何用。","海阔刍粮不易渡，五钟一石劳传送。","横征颇虑空杼轴，转输未免妨耕种。","去年小挫由忌功，今年大衄缘轻纵。","执事颜行屡见逆，天王威命何曾共。","封既无成战失利，公私之积咸哀痛。","更无一人能画策，徒有诸僚成聚讼。","夷狄交侵古来有，更于中国何轻重。","当时止合问曲直，按兵境上不为动。","朝廷制驭自有道，岂在劳民与动众。","奈何误听小人计，日以和好自愚弄。","从此兵端寻岁月，岂知海内为虚空。","财倾左藏不足惜，民伤万命能无恸。","近闻有议留屯戍，老成亿度或屡中。","充国金城上方略，李牧雁门费边供。","年来丧败咎北军，弓马虽闲备骑从。","吴越少年习水战，樯楫轻利过飞鞚。","倘能训练三万人，坐见狡夷受羁控。","腐儒何敢与肉食，聊以短章代微讽。","绕朝勿谓秦无策，中兴尚看甫作颂。"]},{"t":"人日怀故园","f":"七言古诗","c":["人日登楼望岁华，可怜久客独思家。","南中尽道花如锦，北地才看锦作花。","非关帝里春光少，但惜故园春事早。","借问花开桃李蹊，何如雪满关山道。","此日登高且放杯，谁家吹笛上春台。","未报楼前折新柳，已闻江上落残梅。"]},{"t":"赋得吴门市赠庞尉","f":"古风","c":["君不见梅尉昔游吴门市，本是南昌隐君子。","暂埋名姓市廛中，曾抗封章汉廷里。","吴门一鹤唳华亭，君其乘之朝太清。","不嫌三黜官仍小，更作千秋吏隐名。"]},{"t":"送张孟奇还山","f":"七言古诗","c":["四十得官已不早，到官便说还家好。","未曾半载享荣华，何事终朝太烦恼。","金马从来有客栖，松门岂合无人扫。","男儿致身羡青云，君到青云即乞身。","受恩未报胡言去，有才不试空藏珍。","古来樵隐俱在野，看君岂是悠悠者。","满腹经书宜世用，平生意气羞人下。","驷马高车有祸机，君今此去未为非。","但恐圣世搜岩穴，我辈安忍负明时。","南归若访罗浮隐，为言贱子言若斯。"]},{"t":"梅花歌与崔子玉诸公饮花下作","f":"七言古诗","c":["江南气候足妍和，燕地风沙本自多。","惟有梅花解人意，乡关客舍共芬华。","当年花里故人别，今日花前为谁折。","玉椀银缸赏已新，毡毹锦帐香未歇。","醉把瑶华揽子裾，莫教羌笛怨离居。","上苑花枝犹若此，故园春色定何如。"]},{"t":"叶县歌","f":"楚辞体","c":["洪潦纵横兮泥途深，车不得轨行兮马力不任。","日将暮兮天愁阴，望佳人兮伤予心，安得双凫兮驾汝翩翩而来临。"]},{"t":"暮归山中","f":"五言律诗","c":["田家落日闲，茅屋对秋山。","片霭将林暮，孤云共鸟还。","人烟流水外，村杵夕檐间。","萝月时相待，翛然返故关。"]},{"t":"春日阮溪","f":"五言律诗","c":["溪边多胜事，倚杖惜芳晨。","幽径迟来客，孤亭独坐人。","莺将花作友，云与水俱春。","多谢求仙者，何如此问津。"]},{"t":"石门舟中","f":"五言律诗","c":["壁势临江断，涛声入海遥。","众流趋郡国，万舸逐风潮。","越峤王封壮，秦军伯气销。","图南安所适，行矣见扶摇。"]},{"t":"东行纪兴","f":"五言律诗","c":["落日泛舟返，沧波通远天。","未逢三岛使，还访五羊仙。","珠树秋云泾，瑶台夕霭悬。","兴来随所适，沿月棹江烟。"]},{"t":"安期岩 其一","f":"五言律诗","c":["昔闻采药去，过海访蓬壶。","尚忆如瓜枣，难寻九节蒲。","鹤鸣犹绕树，云起类披图。","借问阜乡舄，何如叶县凫。"]},{"t":"安期岩 其二","f":"五言律诗","c":["长谣白雪曲，一扣紫岩扉。","陟磴岚随杖，搴萝翠滴衣。","瑶华纷可掇，仙峤望中微。","海上三清鸟，传书几岁归。"]},{"t":"戏拟少年行","f":"五言律诗","c":["少年何倜傥，结束似金张。","惯贳文君酒，新薰荀令香。","卖珠过主第，掷果向河阳。","秦氏称殊婿，王家早拜郎。"]},{"t":"友人读书诃林","f":"五言律诗","c":["闻道栖禅客，观空不废书。","萝轩僧梵寂，木榻世情疏。","贝叶藏山鸟，昙花隐壁鱼。","由来方丈室，即是草玄居。"]},{"t":"春夜闻雁","f":"五言律诗","c":["汀洲春水生，旅雁动乡情。","复此联翩起，犹含关塞声。","云低时乱叫，雾阻或单鸣。","独坐悬灯夕，因风寄远征。"]},{"t":"寒居","f":"五言律诗","c":["茅斋云木里，寒日转萧森。","幽独生春事，清虚长道心。","闭关惟纵酒，拥褐且长吟。","一枉朋知过，门前车迹深。"]},{"t":"元旦日食 其一","f":"五言律诗","c":["未献椒花颂，先逢日食书。","蓂生春暗发，麟斗事非虚。","不尽如钩挂，新回似月初。","卿云方启旦，光烂奉晖馀。"]},{"t":"元旦日食 其二","f":"五言律诗","c":["献岁冠裳集，朝正祲霭多。","圣朝无阙失，天意竟如何。","匣镜朝晖没，开轩夕照过。","定知天有日，无待鲁阳戈。"]},{"t":"春晴","f":"五言律诗","c":["香阁惜春归。","妆楼宜曙晖。","池纹含细簟，花气透重帏。","林鸟千回啭，园桃一半飞。","韶光处处好，结伴采芳菲。"]},{"t":"春思","f":"五言律诗","c":["春光无远近，都讶艳阳时。","蝶稚初涂粉，蚕眠欲咡丝。","陇云归雁早，海日到窗迟。","惆怅芳菲里，佳期那得知。"]},{"t":"戏作临镜","f":"五言律诗","c":["纱窗催曙鸟，绣阁捲香帏。","开匣自生妒，看妆谁谓非。","怜时嫌著粉，愁处懒更衣。","回视雕梁燕，双双犹未飞。"]},{"t":"烽烟完节诗 其一","f":"五言律诗","c":["虐焰昏炎徼，惊烽煽绿林。","岂缘宋姬笑，遂断木兰吟。","抱柱岂为信，登台良独任。","惟应芦火玉，堪自表贞心。"]},{"t":"烽烟完节诗 其二","f":"五言律诗","c":["忍说干戈日，仍钦妇子贤。","膏薰何用比，烽火故相煎。","烈性金同炼，芳心桂共燃。","当为镆铘剑，长誓斩蛮烟。"]},{"t":"过韶石 其一","f":"五言律诗","c":["玉辇南巡日，从天降九韶。","仍闻舞百兽，真想格三苗。","风雨仙灵集，云霞绛节朝。","有时磐石上，天籁暮萧萧。"]},{"t":"过韶石 其二","f":"五言律诗","c":["轩帝钧天后，重华复此乡。","皇风开楚越，大乐睹虞黄。","石上停仙跸，云端识衮裳。","珠丘不可望，流恨满潇湘。"]},{"t":"岭上望中原 其一","f":"五言律诗","c":["岭树郁苍苍，千峰划大荒。","路盘秦栈没，天入楚云长。","地旷留铜柱，春深贡越裳。","古来思猛士，无乃固金汤。"]},{"t":"岭上望中原 其二","f":"五言律诗","c":["行行踰叠嶂，立马倚崔嵬。","关路元通汉，将军是姓梅。","山川百越尽，云雾五陵开。","倘上筹边疏，安危敢论才。"]},{"t":"度滁关望凤阳","f":"五言律诗","c":["环滁山不断，西尽白云封。","遥辨金陵气，知从泗水龙。","河冰妨渡马，涧雪倒枯松。","侧想涂山会，来王万国宗。"]},{"t":"徐州道中","f":"五言律诗","c":["彭城徐子国，访古气弥增。","饥雀啄残雪，春泉汲断冰。","台临青垒迥，山隐白云层。","客路随征雁，翩翩向五陵。"]},{"t":"晓渡临淮河","f":"五言律诗","c":["县城临渡口，晓涉是春冰。","日月开淮甸，山川入汉陵。","临渊徒有羡，履薄得无兢。","立望龙兴地，风云时自腾。"]},{"t":"春日边思","f":"五言律诗","c":["劳歌倦行迈，长路改年华。","野冻冰胶岸，风鸣马喷沙。","夕烽标汉垒，宵月惨胡笳。","谁念穷边戍，春来不见家。"]},{"t":"南还潞河玩月 其一","f":"五言律诗","c":["潞河堤上月，清景忆皇州。","心逐孤轮转，光看万里流。","花阴辞北渚，帆影溯南洲。","独有江楼望，应同今夜愁。"]},{"t":"南还潞河玩月 其二","f":"五言律诗","c":["轮生云不碍，弦上桂还侵。","披雾光逾皎，临河影讵沉。","望回霄汉迥，看去海门深。","别有南飞鹊，徘徊绕上林。"]},{"t":"戏咏扇上画兰","f":"五言律诗","c":["新制齐纨扇，画作楚皋兰。","叶叶幽闺性，花花彼美看。","动摇晨露湿，怀袖香风寒。","芳意宜连理，嘉名应合欢。"]},{"t":"又咏扇上画兰","f":"五言律诗","c":["美人怀藻思，碧草寄幽情。","露叶迎香发，风枝任兴生。","相怜春畹暮，相倚月轮清。","若持掩歌脸，吐气必俱馨。"]},{"t":"泛舟","f":"五言律诗","c":["汀洲暑气微，烟艇泛晴晖。","鱼拨菱花动，鸥冲桂桨飞。","下溪逢浣女，面水缉荷衣。","相见时相问，郎今何处归。"]},{"t":"江上吊屈庙 其一","f":"五言律诗","c":["楚臣昔见放，遗庙楚江阴。","憔悴当年色，凄凉千载吟。","碧云湘浦远，春草洞湖深。","魂去招何处，遥遥枫树林。"]},{"t":"江上吊屈庙 其二","f":"五言律诗","c":["去国情如昨，怀归复几时。","皇天难具问，公子敢言思。","风雨湘灵泣，鱼龙梦泽悲。","九歌君不见，空自撷江蓠。"]},{"t":"将至故园志喜","f":"五言律诗","c":["自予出京国，迢递望山阿。","客路厌风水，丘园寄薜萝。","枫林青岸合，桂浦白云多。","试问长堤草，年年奈别何。"]},{"t":"溪上独往命酒自随","f":"五言律诗","c":["清溪行不极，徐步即幽深。","草识归人兴，禽疑久客心。","鱼梁明落照，鸡犬隔空林。","不藉芳醪色，谁能慰独吟。"]},{"t":"本空上人禅定西村寄怀","f":"五言律诗","c":["西郊开净域，一水向珠林。","鸟下斋前几，灯传定后心。","钟声流木杪，松子落岩阴。","借问修持苦，应怜绮障深。"]},{"t":"对雪和四兄","f":"五言律诗","c":["早雨晚仍雪，风花湿更乾。","糁枝成玉树，铺径作瑶坛。","赋里窥春易，尊前和曲难。","莫将柳絮句，轻拟撒盐看。"]},{"t":"过亡友陈伯衡故居","f":"五言律诗","c":["云房披素幔，雪涕访遗尘。","竹石对今雨，图书非故人。","鸟啼深巷静，花映古苔春。","何处风前笛，悲来过四邻。"]},{"t":"又咏黎秘书汲古亭","f":"五言律诗","c":["石井何年凿，林亭向水源。","梧疏翻月影，栏古浸苔痕。","抱瓮忘机事，开畦远市喧。","桔槔宁用此，聊灌汉阴园。"]},{"t":"戏马台 其一","f":"五言律诗","c":["乾坤龙战日，西楚气雄哉。","叱咤千人废，腾骧独马来。","云深钜鹿野，日落彭城台。","霸业何销歇，伤心但草莱。"]},{"t":"戏马台 其二","f":"五言律诗","c":["芒砀吞大泽，台上起悲风。","汉世人心属，君王马步工。","孤城苍树断，野戍暮烟空。","独有彭门会，高秋怀宋公。"]},{"t":"咏燕市","f":"五言律诗","c":["五方殊物产，百货丽皇居。","高足千金外，双环万镒馀。","三川谢声利，陆海让车书。","但和酒人筑，休停卿士舆。"]},{"t":"别汪和叔之塞上","f":"五言律诗","c":["花前各尽觞，游子赋河梁。","我望南枝返，君同北雁翔。","笳声咽陇底，海色愁渔阳。","未共酬恩去，相思塞草长。"]},{"t":"出京汪公干追送至潞河别往上谷再赠","f":"五言律诗","c":["临河驱去马，送远各依依。","穷路难为别，游人俱未归。","雪残边草出，沙涨碛花飞。","莫更听燕筑，徒沾壮士衣。"]},{"t":"出上东门","f":"五言律诗","c":["上东东首路，车马无时闲。","日日见行客，朝朝思故山。","地枢连九陌，天阙表重关。","借问频来往，何人剩壮颜。"]},{"t":"咏车","f":"五言律诗","c":["鸣銮遵广陌，缓辔动轻埃。","上路流如水，长桥殷似雷。","朱轮随日转，翠幰拂云来。","不见渭川载，徒思托乘才。"]},{"t":"赋得泥融飞燕子","f":"五言律诗","c":["泥融碧草芳，紫燕远相将。","衔来微带湿，巢处定闻香。","对舞玉池水，双栖文杏梁。","袖中书未寄，夫婿隔湖湘。"]},{"t":"赋得沙暖睡鸳鸯","f":"五言律诗","c":["沙上眠鸳鸟，雌雄不异林。","东风吹欲醉，渌水照同心。","上客赠文绮，佳人思锦衾。","昨宵春梦去，惟恨玉关深。"]},{"t":"发清源开先载酒道傍一醉而别 其一","f":"五言律诗","c":["遑遑问归路，与子暂盘桓。","岁月分襟易，风尘把袂难。","离觞促日短，旅服过春寒。","意气今何在，惟将宝剑看。"]},{"t":"发清源开先载酒道傍一醉而别 其二","f":"五言律诗","c":["下马饮君酒，酒酣愁奈何。","离颜正萧索，客计且蹉跎。","荆玉售何晚，鲛珠泪渐多。","平生惟有恨，中路一悲歌。"]},{"t":"过吕梁","f":"五言律诗","c":["临河发棹唱，聊得洗尘机。","夕鸟度山翠，空梁沉暮霏。","孔观人已远，庄记事多违。","从此茫茫去，中流击枻归。"]},{"t":"夏日同诸客泛舟青溪作 其一","f":"五言律诗","c":["东城杨柳陌，西堰木兰船。","锦缆清川曲，朱楼大道边。","花阴随去棹，鸟韵杂鸣弦。","别有淩波态，回看洛浦仙。"]},{"t":"夏日同诸客泛舟青溪作 其二","f":"五言律诗","c":["解佩临青岸，鸣环步绿浔。","川如濯锦艳，溪比浣纱深。","倚楫吴姬唱，褰芳越客吟。","江南佳丽地，最此称游心。"]},{"t":"夏日同诸客泛舟青溪作 其三","f":"五言律诗","c":["锦席人须醉，仙舟客共登。","年华各自惜，意气转相矜。","瓶水沉朱李，溪花覆紫菱。","莫誇姑射雪，吾有玉壶冰。"]},{"t":"夏日同诸客泛舟青溪作 其四","f":"五言律诗","c":["捲幔千花暝，回舟一水遥。","芳情瑶瑟怨，别曲凤笙调。","桂苑通仙阁，兰房接画桥。","倚歌待明月，长笛不须邀。"]},{"t":"金陵城南宴","f":"五言律诗","c":["逸客东山至，佳人南国多。","袖翻金谷舞，梁绕石城歌。","妆阁宜春入，花蹊爱晚过。","留欢方待月，无遽动鸣珂。"]},{"t":"泊峨眉亭玩月 其一","f":"五言律诗","c":["昔贤临泛后，重系木兰舟。","山月此亭古，风烟何代愁。","鹊飞犹绕树，杯渡欲随流。","多少婵娟恨，何须访醉游。"]},{"t":"泊峨眉亭玩月 其二","f":"五言律诗","c":["由来对酒处，高咏渺难闻。","万古青天月，清辉殊为君。","凄凉同逐客，怅望独离群。","盈手犹堪赠，长歌寄碧云。"]},{"t":"题贞吉王孙幻景庵","f":"五言律诗","c":["汉室诸王子，沙门大士家。","桂开仙院叶，莲发曲池花。","讲席窥山鸟，禅衣落涧霞。","中林亦何事，长日演三车。"]},{"t":"晚发豫章江上","f":"五言律诗","c":["迩来山水趣，独在豫章船。","正有登临兴，其如旅病牵。","抱琴传此意，栖岳计何年。","暮倚中流楫，闻歌徒自怜。"]},{"t":"赣州阻水","f":"五言律诗","c":["两涯新涨满，系缆动乡愁。","万岭盘溪落，双桥带郡流。","行人迷旧渡，宿鹭没前洲。","失路今如此，谁能赋远游。"]},{"t":"自南野驿赴横浦","f":"五言律诗","c":["溪路多纡折，一程数十滩。","崖欹度缆险，石浅溯舟难。","樵径迷深竹，鸥矶坐急湍。","任君归思切，信宿且加餐。"]},{"t":"中秘黎公挽词 其一","f":"五言律诗","c":["一代词宗丧，三朝侍史荣。","芸香馀旧草，风雅变新声。","宦路终蓬阁，归魂必玉京。","茂陵求见及，犹想禅书成。"]},{"t":"中秘黎公挽词 其二","f":"五言律诗","c":["晚节慕丹丘，长生事可求。","谁言已年梦，竟作岱宗游。","海暗千珠色，山空八桂秋。","平生知己泪，零落向西州。"]},{"t":"中秘黎公挽词 其三","f":"五言律诗","c":["山中朝沐罢，地下忽修文。","日黯炎洲树，江寒桂水云。","风松吟旧馆，露草泣孤坟。","欲拟招魂些，泉台恐不闻。"]},{"t":"中秘黎公挽词 其四","f":"五言律诗","c":["此别成千载，浮生感七哀。","吟诗推我过，把剑觅君来。","溟海鹏初息，罗浮凤不回。","岁寒问耆旧，松柏是新栽。"]},{"t":"始赴东山口杨柳村庄作 其一","f":"五言律诗","c":["山中朝暮雨，溪上两三家。","古岸堆榕叶，闲门扫橘花。","茅茨散鸡犬，林沼涨云沙。","何恨伤春事，无心恋物华。"]},{"t":"始赴东山口杨柳村庄作 其二","f":"五言律诗","c":["经始东山下，萧条素业存。","源桃犹避世，沙柳自成村。","远树峰腰驿，孤烟谷口屯。","山林情岂忝，丘壑道能尊。"]},{"t":"始赴东山口杨柳村庄作 其三","f":"五言律诗","c":["废垄千畦韭，清川几树桃。","入林披壤石，薄采荐溪毛。","旧俗忧多难，新氓计转劳。","未堪营一饱，身世有渔舠。"]},{"t":"始赴东山口杨柳村庄作 其四","f":"五言律诗","c":["十亩阴连水，茅檐春雾浓。","烟霞馀几片，岩壑有千重。","寇贼虽新息，军储亦旧供。","异时负薪子，应乞寝丘封。"]},{"t":"始赴东山口杨柳村庄作 其五","f":"五言律诗","c":["瓜地怜兹卜，菟裘无别营。","刈麻防久雨，祈谷望新晴。","田父休询姓，山禽不辨名。","庞公遗后计，独有鹿门耕。"]},{"t":"始赴东山口杨柳村庄作 其六","f":"五言律诗","c":["沙田春悯潦，云壑昼伤阴。","牛羊村径浅，耕凿战场深。","麛狎眠幽竹，鸥喧坐碧浔。","遗书犹可读，谁贵满籯金。"]},{"t":"始赴东山口杨柳村庄作 其七","f":"五言律诗","c":["地僻时留径，江深晚泊船。","岂无陴上宅，实少汶阳田。","俭穫频供税，丰年或具饘。","莫将桑梓敬，花树拟平泉。"]},{"t":"始赴东山口杨柳村庄作 其八","f":"五言律诗","c":["荆扉颓岸引，蔬圃乱流通。","包橘无千树，芳兰自一丛。","暮云丹水北，古峡苍梧东。","柳外春沙没，哀哀何处鸿。"]},{"t":"舟次洚水口 其一","f":"五言律诗","c":["满目兵戈后，西来岂胜游。","箐林皆置堡，洚水始通舟。","预恐官租逼，常怀歉岁忧。","请从渤海治，致盗独无由。"]},{"t":"舟次洚水口 其二","f":"五言律诗","c":["篱落新烟少，江村古塞遥。","长林收夏榷，残烧长春苗。","颓屋燕双入，微风花乱飘。","那堪正水宿，城柝复萧萧。"]},{"t":"入罗滂水","f":"五言律诗","c":["井邑新安集，闾阎杂汉徭。","火耕春伐木，山猎夜归樵。","潮响蛮溪合，林光瘴峒消。","直须勤抚字，慎勿困徵徭。"]},{"t":"出灵羊峡望香炉诸峡山","f":"五言律诗","c":["香炉复灵峡，信美且吾州。","伊昔投荒路，今看拥上游。","猿啼千嶂雨，枫落片帆秋。","作赋何年客，偏怜风景幽。"]},{"t":"陈少珍移居与周少恂相邻寄怀","f":"五言律诗","c":["二友衡门接，城隅水竹多。","闲携青玉杖，高和紫芝歌。","篱落同鸡犬，衣裳杂薜萝。","端居寡俦侣，寂寞向羊何。"]},{"t":"初秋夜 其一","f":"五言律诗","c":["摇落才兹夕，萧条已不禁。","下阶闻坠叶，悬树见栖禽。","未有干时策，长怀出世心。","谁言骑省客，独受二毛侵。"]},{"t":"初秋夜 其二","f":"五言律诗","c":["昔贤虽宦达，犹或念蹉跎。","况复飘蓬久，其如落叶何。","冥冥高鸟翮，滚滚逝川波。","欲拟清商曲，难赓白石歌。"]},{"t":"初秋夜 其三","f":"五言律诗","c":["河低天欲曙，孤坐意何长。","不惜枫林晚，空怜蕙草芳。","暗投增按剑，夕济限无梁。","耿耿不能寐，踟蹰中自伤。"]},{"t":"晚投洲寺","f":"五言律诗","c":["暝色投沙界，幽香入梵林。","夕流含砌转，寒叶下阶深。","借榻邻山狖，张灯散渚禽。","不须谈出世，虚寂长禅心。"]},{"t":"洲寺晚望","f":"五言律诗","c":["寺僻流双绕，山晴绿四围。","一僧迎客出，群鹭掠波飞。","潦尽泉声聒，庭空帆影归。","息心终傍此，非是暂忘机。"]},{"t":"答苏母舅以九日诗见寄","f":"五言律诗","c":["忽示登高作，悲怀独有君。","家贫违故里，书远寄秋云。","地僻山寒早，江空猿啸闻。","往时落帽兴，愁绝孟参军。"]},{"t":"宿端溪口","f":"五言律诗","c":["烟霏生暝色，信宿伴渔樵。","地静林无瘴，溪喧水是潮。","落霞连雁足，残烧隔山腰。","虽听江城笛，何言乡路遥。"]},{"t":"晚过光孝寺禅室","f":"五言律诗","c":["真谛何时了，微踪暂托缘。","鸟啼千岁树，霜冷六时莲。","风叶随吟客，天花对病禅。","无论空与寂，水月共思玄。"]},{"t":"得苏母舅东山书问","f":"五言律诗","c":["牢落悲吾舅，东山合就耕。","暮题颜远句，遥寄渭阳情。","草屋营寒事，沙田足晚成。","贫居闻亦乐，诗酒过平生。"]},{"t":"游三洲岩 其一","f":"五言律诗","c":["闻说岩林胜，西浮锦水春。","云归瑶径失，雨洗石苗新。","折桂期山客，攀萝蹑羽人。","居然成独往，何用记来津。"]},{"t":"游三洲岩 其二","f":"五言律诗","c":["洞启烟扉湿，林悬雾磴斜。","藏书空有穴，封灶久无砂。","扣石闻天乐，褰衣动涧霞。","一从灵景秘，春事长瑶华。"]},{"t":"张子以五齐录事传见示因赠","f":"五言律诗","c":["饮客高阳后，随身双玉瓶。","百年须酿醉，一月几回醒。","白眼看人事，清酣识性灵。","君今颂酒德，吾意亦沉冥。"]},{"t":"秋荷同坐客分赋","f":"五言律诗","c":["过夏红蕖发，亭亭小院幽。","迎霜花似浣，听雨叶堪留。","色静金塘晚，香分玉井秋。","更宜擎月露，持奉液池游。"]},{"t":"端州集梁约中园池 其一","f":"五言律诗","c":["懒挟朱门瑟，归寻绿水园。","主人解簪组，留客开萝轩。","树密云迷径，池清竹映村。","知君乐情志，不负仲长言。"]},{"t":"端州集梁约中园池 其二","f":"五言律诗","c":["名园多胜事，延赏足烟霞。","片石开云细，回塘避径斜。","菊含霜后蕊，桃发春前花。","未觉年芳暮，留欢醉物华。"]},{"t":"曲江值雪同家兄舍弟","f":"五言律诗","c":["急雪孤城下，同云万里长。","客情犹故国，春色渐他乡。","冷气开炎峤，流光艳早阳。","纷纷何所拟，诸谢有歌章。"]},{"t":"晚次始兴江口","f":"五言律诗","c":["客程行渐北，乡思转悠悠。","斗下看雄剑，风前揽敝裘。","渚花飘映月，霜叶洒随舟。","今夕南征雁，先飞故国楼。"]},{"t":"岭上见梅花","f":"五言律诗","c":["梅岭候偏宜，梅花岭上窥。","报瑶人去远，踏雪马行迟。","驿使春前发，乡心笛里知。","已从关路北，犹觅向南枝。"]},{"t":"题大庾岭北驿兼示入计诸使者","f":"五言律诗","c":["我行竟何事，访古昭王台。","沧海搏鹏羽，黄金识骏才。","游燕歌渐起，系越使初回。","望气何人在，当关报客来。"]},{"t":"虔州西津桥作","f":"五言律诗","c":["生平重游侠，中岁颇艰虞。","宝剑南来越，雕弓北射胡。","风云开上国，雨雪壮长途。","候吏何须问，关门昨弃繻。"]},{"t":"游大隆福寺","f":"五言律诗","c":["驰道开香界，仙宫近紫微。","泉清龙旧跃，松暝鹤知归。","画壁荒苔杂，雕阑蔓草围。","双幡门外直，犹想翠旗飞。"]},{"t":"摩诃庵寻僧不值","f":"五言律诗","c":["杖锡是何适，云霞少定踪。","咒龙馀钵水，留鹤伴阶松。","野立看遥嶂，孤吟待暝钟。","仍闻弟子说，早晚下西峰。"]},{"t":"林开先惠练绢袜","f":"五言律诗","c":["岂料无衣客，尘中步亦仙。","迷阳思裹足，举趾意缠绵。","旅食从貂敝，商歌任履穿。","王生今老贱，谁引汉廷贤。"]},{"t":"开先吉士饷酒云自齐东游日所藏发封大釂不觉尽醉","f":"五言律诗","c":["贻来千日酒，不饮奈愁何。","穷路惟堪醉，华年渐欲过。","开樽恋花月，觅侣坐松萝。","愿以如渑颂，兼之击唾歌。"]},{"t":"五日同邓希父蒋兆卿宴黄公绍旅寓园亭时微雨初过得鲜字","f":"五言律诗","c":["撷艾属芳筵，林亭景气鲜。","蒲觞开石径，桂楫想江天。","细葛凉风袭，高槐片雨悬。","殷勤看彩缕，一倍惜流年。"]},{"t":"客中九日","f":"五言律诗","c":["细雨黄花节，秋风竹叶杯。","异乡谁送酒，何处更登台。","木落江云暮，天寒塞雁来。","惟怜三径在，归去剪蒿莱。"]},{"t":"梅庵僧舍阅黎秘书游石室诸篇草隶","f":"五言律诗","c":["名山支策去，高咏复寻僧。","妙墨窥中秘，新诗得上乘。","给从斋后膳，讲忆佛前灯。","欲共桦皮出，操觚谢未能。"]},{"t":"送黄汝纶柳州寻明府弟","f":"五言律诗","c":["醉发江上棹，西游见白眉。","看云吟桂水，访古过罗池。","霜叶随行暮，江鸿独去迟。","羡君花萼好，到处有连枝。"]},{"t":"饮梁氏园亭 其一","f":"五言律诗","c":["与客搴芳至，林亭云沼间。","层轩皆面水，密树不障山。","露染桂枝碧，烟笼菊蕊斑。","淹留好情影，乘月憺忘还。"]},{"t":"饮梁氏园亭 其二","f":"五言律诗","c":["乐志惟兹园，长林隔市喧。","禽声隐翠筱，松色酿清樽。","夕水芙蓉媚，新霜薜荔繁。","小童行酒罢，双管月中翻。"]},{"t":"仲冬集梁氏园得江字","f":"五言律诗","c":["曲槛嘶群骑，平池泊小艭。","岚光迥夕嶂，雁影溯空江。","竹密烟沉径，藤疏月挂窗。","清言恋朋好，胜事狎花缸。"]},{"t":"同家兄舍弟谒文昌台","f":"五言律诗","c":["珠斗近中台，瑶琨拥化台。","溪疑曲水接，山似梓潼开。","紫雾花幢引，晴云宝盖来。","如闻登桂籍，同此荐椒杯。"]},{"t":"太平山庵访朱贞吉","f":"五言律诗","c":["霞踪成独往，弭棹访云林。","不识王孙路，惟看忍草深。","香厨分净供，松籁协幽吟。","却笑征途者，劳劳江海心。"]},{"t":"南都 其一","f":"五言律诗","c":["东吴初建国，四海此来同。","地跨六朝盛，江连三辅雄。","玉墀留夜月，金殿锁春风。","正睹周基茂，千龄咏镐丰。"]},{"t":"南都 其二","f":"五言律诗","c":["襟带河山是，规模南北同。","铜盘万岁露，玉井两秋桐。","江汉思明主，乾坤忆旧宫。","到来歌舞地，犹想太平风。"]},{"t":"南都 其三","f":"五言律诗","c":["汉家敦懿戚，周室重尊亲。","揖让劳明主，艰危仗节臣。","豪华卑六代，父老望三秦。","万古钟山气，长瞻旧紫宸。"]},{"t":"南都 其四","f":"五言律诗","c":["名都一何绮，钟阜据玄湖。","万国舟车辏，千官剑佩趋。","翠华游凤辇，碧殿想龙图。","盛德兴王地，元为天下枢。"]},{"t":"南都 其五","f":"五言律诗","c":["蓬莱閒綵仗，长乐罢霓旌。","白动吴江直，青连楚岫平。","暮云双阙凤，春竹万家莺。","故老思丰沛，抽毫赋两京。"]},{"t":"夏日偕同诸年友集于灵济宫","f":"五言律诗","c":["结驷情多暇，骖鸾路不赊。","偶携中圣酒，来过上清家。","解带褰瑶草，倾壶藉洞花。","相期炼灵液，携手五云车。"]},{"t":"初读书翰林作 其一","f":"五言律诗","c":["材馆抡多士，兰台出秘书。","紫庭储相日，黄阁礼贤初。","奏技颁银管，披文映玉除。","淩云自有赋，何必羡吹嘘。"]},{"t":"初读书翰林作 其二","f":"五言律诗","c":["旧事弘文馆，新恩翰墨林。","琼轩开丽泽，天路合朋簪。","岁月诸儒论，风云列圣心。","何人种桃李，于此欲成阴。"]},{"t":"初读书翰林作 其三","f":"五言律诗","c":["虞代收元凯，周廷引庶常。","今兼文体重，古以事功良。","礼乐从先进，鹓鸾接末行。","何当刷毛羽，云路共翱翔。"]},{"t":"送袁文瀫令富阳","f":"五言律诗","c":["海邑通秦望，春城过阖闾。","吏才三仕达，宦迹十年疏。","梅萼孤山雪，桐江隐士庐。","从来因好客，官俸惯无馀。"]},{"t":"冬至前一日斋居对雪 其一","f":"五言律诗","c":["缇室窥玄籥，清斋席白茅。","瑶光连北阙，璧彩近南郊。","砌迥檐花积，风回苑树交。","天心如可见，已映易中爻。"]},{"t":"冬至前一日斋居对雪 其二","f":"五言律诗","c":["迎气潜皇泽，飘霙下帝台。","兆从三白异，瑞应一阳回。","净色流坛树，轻飞逐管灰。","明朝郊祀赋，应待长卿才。"]},{"t":"诸客过集同送舍弟之东明 其一","f":"五言律诗","c":["努力向明时，悠然眷路歧。","之官怀弟别，对友念兄离。","夜雨黎阳树，春风濮水湄。","明朝棣华咏，应接芾棠诗。"]},{"t":"诸客过集同送舍弟之东明 其二","f":"五言律诗","c":["季弟难兄誉，仁风在播扬。","去天郎宿近，行县绶花香。","丹阙占凫影，青云起雁行。","顾惭采风史，抽笔伫循良。"]},{"t":"谷日雪","f":"五言律诗","c":["谷日偏宜雪，花天正起风。","春归瑶圃外，润洒玉田中。","阁迥飘还集，阶暄落易融。","螟蝗今岁少，野老喜年丰。"]},{"t":"早春长安道上","f":"五言律诗","c":["双阙丽朝霞，千门竞岁华。","苑云微带雪，宫柳半藏鸦。","结驷过平乐，扬鞭赴狭斜。","春风才几日，先发上林花。"]},{"t":"赋得云近蓬莱","f":"五言律诗","c":["蓬苑与天通，祥云杳霭封。","杂花开绛阙，接叶映霞峰。","日袅仙衣丽，风飘御盖重。","惟应常五色，朝暮自从龙。"]},{"t":"院中春日 其一","f":"五言律诗","c":["柳色连金阙，花香过玉楼。","林亭罗杂树，池馆带新流。","禽有迁乔望，人多选胜游。","谁怜看花伴，独自滞瀛洲。"]},{"t":"院中春日 其二","f":"五言律诗","c":["夜宿芸香阁，朝游竹素园。","花枝连苑密，莺语隔林喧。","对酒开新帙，看云过别轩。","仙情自有适，何必访桃源。"]},{"t":"院中夏日 其一","f":"五言律诗","c":["閟馆肃清芬，虚亭出五云。","石林藏雨气，霞岛辨峰文。","露影仙茎溢，莲香太液闻。","携琴扫萝径，闲坐咏南薰。"]},{"t":"院中夏日 其二","f":"五言律诗","c":["官暇抛章绶，朝回向薜萝。","风鸣幽涧竹，雨歇小池荷。","散帙鸟声至，窥潭鱼乐过。","自怜尘境寂，炎夏得凉多。"]},{"t":"九日偕馆中诸友集天宁寺","f":"五言律诗","c":["帝京重九日，朋旧共开樽。","地远城西寺，台高蓟北门。","云光移塔影，山势断河源。","忽睹南征雁，令予思故园。"]},{"t":"家人初至京置酒庭中对雪作","f":"五言律诗","c":["庭霰今朝集，家筵此日开。","不知燕地雪，犹讶故园梅。","玉袖承花出，珠帘卷絮回。","瑶华虽可赠，留赏上春来。"]},{"t":"瑞儿初见雪能为诗喜示 其一","f":"五言律诗","c":["白雪儿能咏，同看帝苑边。","乍连珠树密，已并玉堂悬。","影助层城月，光摇万里天。","更宜芸阁夕，映彩读新编。"]},{"t":"瑞儿初见雪能为诗喜示 其二","f":"五言律诗","c":["晓云双阙外，夕霰一庭中。","絮起犹含吹，花飞更舞空。","谢吟还汝共，郢曲为谁工。","往岁梅关北，寒深阻塞鸿。"]},{"t":"雪夕刘孙林庄四吉士过集同用梅字","f":"五言律诗","c":["暮雀归林尽，寒貂拥雪来。","捲帘如却月，连骑似探梅。","润重沾银管，花轻堕玉杯。","更饶今夕兴，差胜剡溪回。"]},{"t":"馆中杂咏 其一","f":"五言律诗","c":["英游真忝窃，胜地绝攀缘。","树色藏书阁，花香入讲筵。","岁售中秘帙，月费大官钱。","载笔惭恩遇，何能即掞天。"]},{"t":"馆中杂咏 其二","f":"五言律诗","c":["瑶圃为藏室，蓬莱即道山。","地幽尘境外，心远市朝间。","客至聊烹茗，书成但闭关。","何须拂衣去，身世已投闲。"]},{"t":"馆中杂咏 其三","f":"五言律诗","c":["春水通银汉，长桥跨玉河。","散衙人吏少，归院苑云多。","凤阁移新柳，龙池出小荷。","自惭多吉士，联步咏卷阿。"]},{"t":"馆中杂咏 其四","f":"五言律诗","c":["槐院披丹磴，芸窗网碧纱。","帘垂仙苑柳，墙压御沟花。","走墨和甘露，飞文散绮霞。","良时多载酒，谁过子云家。"]},{"t":"馆中杂咏 其五","f":"五言律诗","c":["侍史趋清禁，承恩下直庐。","瓶馀赊得酒，架积赐来书。","刻凤才何有，雕虫习未除。","由来少尘事，寂寞意何如。"]},{"t":"馆中杂咏 其六","f":"五言律诗","c":["儒雅先朝重，风云汉苑过。","琼章悬日月，银榜拂星河。","竹长成龙节，桐高集凤柯。","如闻访道日，重和白云歌。"]},{"t":"馆中杂咏 其七","f":"五言律诗","c":["依隐便山性，幽栖养谷神。","暂为芸阁吏，终作草堂人。","种竹消长夏，听莺过暮春。","林端有双鹤，潇洒类闲身。"]},{"t":"馆中杂咏 其八","f":"五言律诗","c":["徐步登云阁，栖心傍药阑。","院幽琴作伴，阶静鹤相看。","藜火分宵读，柴门过午餐。","儿童相顾笑，不省是何官。"]},{"t":"馆中杂咏 其九","f":"五言律诗","c":["经旬不出户，幽事亦何能。","汲水尝新茗，攀花引古藤。","避人常谢病，得酒便呼朋。","若问为官意，闲门寂似僧。"]},{"t":"馆中杂咏 其十","f":"五言律诗","c":["偶从方朔侍，颇识子云奇。","散帙尘来少，窥书鸟去迟。","囊中寻旧草，马上续新诗。","惟有江湖兴，闲窗独坐时。"]},{"t":"馆中杂咏 其十一","f":"五言律诗","c":["怅然不得意，隐几对前山。","谢病攀云出，寻僧累日还。","石泉留策听，竹户映花关。","忆与溪翁别，相期云水间。"]},{"t":"馆中杂咏 其十二","f":"五言律诗","c":["湖西数百寺，双屐屡追寻。","水绕芙蓉塔，山围薝卜林。","千钟流木杪，万宇结峰阴。","不为官多暇，知余空赏心。"]},{"t":"馆中杂咏 其十三","f":"五言律诗","c":["近得论文友，幽期竹下深。","风前同奏雅，天上待知音。","仙袂披云接，华轩带月临。","不能赓妙咏，端坐思瑶琴。"]},{"t":"馆中杂咏 其十四","f":"五言律诗","c":["簿领知无分，文章自有家。","忙时惟笔札，散地即烟霞。","褊性淮南橘，閒情杜曲花。","幽盟关物理，疲马恋休衙。"]},{"t":"游慈寿寺","f":"五言律诗","c":["金地出城布，琼檐绕塔回。","名花天女供，仙果御园来。","松荫谈经石，禽窥施饭台。","晚来清禁月，长照法轮开。"]},{"t":"题别山长老精舍","f":"五言律诗","c":["演法开精舍，焚香谒紫微。","隔林期鹤返，持钵咒龙归。","云表流天乐，宫中赐衲衣。","犹看卓锡处，松下玉泉飞。"]},{"t":"赠许太初","f":"五言律诗","c":["方书与素琴，共有古人心。","贻我青囊诀，聆君白雪音。","烟霞驱病色，山水涤烦襟。","何日炼金鼎，相携就竹林。"]},{"t":"春暮即事","f":"五言律诗","c":["春光今日暮，春恨此时长。","泉响过仙院，苔文蚀画墙。","庭馀一鸟啭，林剩几花香。","紫燕忙何事，衔泥向玉堂。"]},{"t":"慈寿寺","f":"五言律诗","c":["禅宫当径口，终日有轮蹄。","万宝栽为树，千花丛若蹊。","香分夷国贡，鸟亦禁林栖。","不识西来路，王城此向西。"]},{"t":"晚至碧云寺","f":"五言律诗","c":["松房碧云里，云壑昼凄凄。","山翠席间落，雨花檐外低。","清钟疏古木，香涧拂晴霓。","晚步泉亭月，分明到虎溪。"]},{"t":"辛卯中秋家人置酒亭中玩月","f":"五言律诗","c":["秋月正宜看，秋城夜未阑。","闺人张宴待，稚子捲帘欢。","东壁蟾光入，中庭练影寒。","年来种桂意，移傍五云端。"]},{"t":"辛卯重九城西禅林登眺 其一","f":"五言律诗","c":["燕郊载酒日，汉殿佩萸时。","强赴重阳会，元无三径资。","寒城淡古木，返景透疏篱。","寂寞龙山后，柴桑与我期。"]},{"t":"辛卯重九城西禅林登眺 其二","f":"五言律诗","c":["清霜涂峻坂，晚日下西岑。","客舍黄花满，关门红叶深。","亲朋九日饮，乡土百年心。","落帽胡为者，风流直至今。"]},{"t":"春郊即事","f":"五言律诗","c":["汉署逃名客，津桥行乐人。","云山一片紫，花树几重春。","章绶纷为累，琴樽且畅神。","啼莺与芳草，处处动游轮。"]},{"t":"晚春郊宴","f":"五言律诗","c":["柳外一纶巾，莺啼欲暮春。","鸣琴稀俗客，持酌劝佳宾。","四十无闻老，乾坤有限身。","试看花下宴，谁是百年人。"]},{"t":"病起客至言西郊花事已过怅然有作 其一","f":"五言律诗","c":["移疾动经旬，宁知花事新。","烟霞不惜赏，桃李可怜春。","底事催莺老，非关送酒频。","向来迟暮意，为此重伤神。"]},{"t":"病起客至言西郊花事已过怅然有作 其二","f":"五言律诗","c":["西郊万树杏，飘落任西东。","颇恨前朝雨，深愁昨夜风。","游蜂争堕蕊，舞蝶恋虚丛。","老鬓将残艳，相怜晓镜中。"]},{"t":"闻宁夏变起","f":"五言律诗","c":["近传宁夏卒，杀将乃横行。","养虎虽贻患，操戈亦有名。","预愁勾逆虏，遂恐失坚城。","柳外清笳曲，谁吹塞上声。"]},{"t":"梁武库经略河陇回","f":"五言律诗","c":["远闻乘障返，遽睹入关行。","出塞三边静，归朝万户轻。","偏师全汉地，间道走胡兵。","不听从军曲，谁知苦乐情。"]},{"t":"柬张太仆质卿","f":"五言律诗","c":["昔会即分离，追欢能几时。","风尘一诺重，湖海十年思。","绿发君先达，青云我后期。","匣中龙气在，曾辱茂先知。"]},{"t":"送韩伯仪守高邮","f":"五言律诗","c":["使君朝拥传，筮仕即专城。","隔座见摇楫，开堂闻濯缨。","湖光连海阔，河润过淮明。","莫厌逢迎地，中和听颂声。"]},{"t":"林开先内翰宅酌别孙令之修仁","f":"五言律诗","c":["华堂一樽酒，叙此平生心。","赠以歌前扇，聆君花下琴。","湘山入县远，漓水过家深。","莫畏冲炎瘴，清风在桂林。"]},{"t":"雨后过张太仆","f":"五言律诗","c":["高斋双塔下，来往惬幽期。","近寺鸣钟夕，遥林过雨时。","马蹄冲溜滑，蝉响入秋悲。","莫下忧时泪，朝骖我自疲。"]},{"t":"立秋日雨中","f":"五言律诗","c":["旧侣惬相寻，凉飙动禁林。","秋因一叶早，交以十年深。","片雨生幽事，层城下夕阴。","瑶琴多逸思，长愿嗣徽音。"]},{"t":"初秋夜同林太史过萧太史书斋","f":"五言律诗","c":["结庐虽傍市，种竹近成林。","乍到安禅地，终谐大隐心。","开轩迎苑月，隔牖度城砧。","已惬山泉赏，何须云壑寻。"]},{"t":"秋日同开先正甫出郭行经郊坛","f":"五言律诗","c":["清秋原野旷，旷望极瑶岑。","七月郊坛路，千年松桧林。","听鸡知洞浅，别鹤入山深。","辇道苔生处，遥思羽盖临。"]},{"t":"送胡孟韬之沅江 其一","f":"五言律诗","c":["萧条官舍远，况值楚山秋。","杜牧言何罪，长沙涕自流。","澧兰清客思，沅芷动乡愁。","词赋从来地，君无薄此游。"]},{"t":"送胡孟韬之沅江 其二","f":"五言律诗","c":["浮湘明日事，江畔莫行吟。","易动骚人怨，难为国士心。","秋风吹芷岸，落日暗枫林。","知有还家梦，浔阳九派深。"]},{"t":"西风","f":"五言律诗","c":["西风动万里，羁客不禁秋。","送雁过关塞，惊尘上戍楼。","乍嘶胡马动，谩捲汉旌愁。","辛苦防秋卒，黄沙战未休。"]},{"t":"送薛行人宣慰朝鲜 其一","f":"五言律诗","c":["我皇元慎德，夷服自交侵。","受命存箕国，持诏去鸡林。","风烟辽海阔，雨露绿江深。","莫使楼船将，功名传至今。"]},{"t":"送薛行人宣慰朝鲜 其二","f":"五言律诗","c":["夷君沦草莽，归命似穷猿。","辍食天朝义，持危明主恩。","饮冰将去节，航海望归轩。","职贡周封旧，长令守外藩。"]},{"t":"九日偕诸客八里庄登眺饮非幻上人众芳亭","f":"五言律诗","c":["陶公爱九日，而我一樽随。","郊寺隐松叶，主僧开菊篱。","背人南雁疾，留客晚钟迟。","莫上高台望，台高多所思。"]},{"t":"送薛行人持诏南楚便归岭外 其一","f":"五言律诗","c":["西夏昨纵横，王师命有征。","三时疲士马，四海望升平。","朔雪吹饶入，江云拥传行。","王程君莫缓，拜舞万方情。"]},{"t":"送薛行人持诏南楚便归岭外 其二","f":"五言律诗","c":["边事劳行役，秋冬两戒辀。","方回辽左使，复作楚南游。","雪树江关驿，云帆海国楼。","仍闻下诏日，父老共销忧。"]},{"t":"送曾中舍持诏南归 其一","f":"五言律诗","c":["龙庭收羽檄，凤沼出丝纶。","正睹三边静，还同四海春。","别筵梅送雪，归骑柳窥人。","遥想逢迎处，普天无战尘。"]},{"t":"送曾中舍持诏南归 其二","f":"五言律诗","c":["汉诏下甘泉，宣传定朔边。","马随龙节远，莺待凤池迁。","草暖江南路，冰消蓟北天。","帝城风日好，会报使车旋。"]},{"t":"以诗代书寄张羽王 其一","f":"五言律诗","c":["美人家何在，言住湘川湄。","独立叹无与，采芳何所遗。","春情寄瑶瑟，幽怨结江蓠。","频夜寻君梦，云山九处疑。"]},{"t":"以诗代书寄张羽王 其二","f":"五言律诗","c":["所思在桂林，欲往隔湘阴。","岁暮书仍阻，春来水更深。","无由展言宴，何以托飞沉。","不见倾城色，空传绝代音。"]},{"t":"送张仆卿还桂林","f":"五言律诗","c":["还朝能几日，去国逼残年。","别路春前酒，离亭雪后天。","衡阳随去雁，湘浦问归船。","未是投闲日，东山卧莫坚。"]},{"t":"林咨伯太史移居北邻作此奉简","f":"五言律诗","c":["近卜宫西宅，君来就竹扉。","门同垂苑柳，壁共挂朝衣。","联骑寻花出，双星伴月归。","天涯好邻并，不觉宦情微。"]},{"t":"田家即事","f":"五言律诗","c":["自从服官后，耕稼废田园。","偶出看农事，高谈坐树根。","暝云捎雨急，归雀掠檐喧。","立望牛羊径，依然谷口村。"]},{"t":"晚渡浑河寻宝林寺","f":"五言律诗","c":["人天若远近，欲往更沉沉。","问水寻沙界，看山入宝林。","板桥昏骇马，松径晚惊禽。","此是西来路，恒河更几深。"]},{"t":"暮投宝林禅室赠彻上人","f":"五言律诗","c":["平明驱下泽，昏黑渡危桥。","只为迷方久，非关觉路遥。","莲灯明丈室，香饭具僧瓢。","不待闻钟梵，先令尘虑消。"]},{"t":"题宝林寺宾上人兰若","f":"五言律诗","c":["老僧延客处，松色映袈裟。","禅坐栖山鸟，经行踏涧花。","烟萝侵径狭，溪水到门斜。","莫谓无车马，津梁涉更赊。"]},{"t":"香山寺","f":"五言律诗","c":["云门披雾磴，石脉响流泉。","殿阁衔山转，香萝拂径悬。","盘松低覆地，复道上摩天。","向晚生幽思，长林起夕烟。"]},{"t":"登来青轩","f":"五言律诗","c":["层轩翠微里，宸翰此高题。","仰见星辰列，平看云雾低。","路盘陵树北，山拥帝城西。","万乘来游地，应无七圣迷。"]},{"t":"碧云寺水亭晚坐","f":"五言律诗","c":["落日松亭上，疏钟云外清。","泉源随径转，溪月枕流明。","洗钵闻花气，开林散鸟声。","坐来尘境寂，弥觉世缘轻。"]},{"t":"送陈任夫司训天台","f":"五言律诗","c":["闻子谈经处，高斋连翠微。","明霞胜绛帐，飞瀑浣儒衣。","白日松坛静，春风鼓瑟希。","闲携童冠出，华顶咏而归。"]},{"t":"得舍弟春来行县诸诗","f":"五言律诗","c":["政暇元吾弟，乘春或下堂。","弦歌为宰遍，布令出郊长。","绕郭为驯雉，他时必爱棠。","采风何日至，勿剪和歌章。"]},{"t":"中秋诸客过集是夕余病初起","f":"五言律诗","c":["主人今强起，众客且为欢。","共是天涯望，谁堪枕上看。","香风出桂苑，冷露濯金盘。","乞取长生药，何人住广寒。"]},{"t":"闻郡国被灾东明弟拮据荒政百尔劳瘁遥有此寄","f":"五言律诗","c":["忆弟心如岁，忧时发欲星。","衣裳带月入，涕泪及秋零。","小邑歌鸿雁，高原起鹡鸰。","忽闻颂声作，频使客愁醒。"]},{"t":"送梁进士宰零陵","f":"五言律诗","c":["潇湘新试令，家在潇湘南。","雁去犹逾岭，凫来不假骖。","琴声二水月，厅事九疑岚。","莫以零陵草，还轻玳瑁簪。"]},{"t":"癸巳九日同焦弱侯周季平吴会甫董玄宰林咨伯庄得全六太史携酒兴德寺后池台 其一","f":"五言律诗","c":["野寺堆红叶，秋原隐白蒿。","乡遥愁望远，病起强登高。","为客惭乌帽，随人试浊醪。","逢时聊引兴，能赋愧词曹。"]},{"t":"癸巳九日同焦弱侯周季平吴会甫董玄宰林咨伯庄得全六太史携酒兴德寺后池台 其二","f":"五言律诗","c":["杖屦侵霜叶，壶觞就径花。","高风疏薜荔，薄雾隐蒹葭。","山绕层城暮，桥通小苑斜。","正逢边雁下，西北有尘沙。"]},{"t":"秋望","f":"五言律诗","c":["野兴因高发，羁怀逐望舒。","暮霞红蓟叶，秋水白漳渠。","去雁冲风尽，寒花对酒疏。","三年频忆处，赢得数行书。"]},{"t":"寄梁兵宪天津 其一","f":"五言律诗","c":["碣石横燕甸，天津控海门。","梯航万国会，貔虎五营屯。","远浪含夷岛，长沙接塞垣。","人传新节制，清啸似刘琨。"]},{"t":"寄梁兵宪天津 其二","f":"五言律诗","c":["鸣笳归陇坂，悬旆度天津。","朔气临河尽，军容入塞新。","蜃楼清海月，狐岭静边尘。","要取黄金印，归图紫阁麟。"]},{"t":"三月十五月食大风","f":"五言律诗","c":["月食今宵异，风威特地狂。","直吹阴曀灭，休遣恶氛扬。","桂满摧虞折，轮移急虑伤。","时祲兼贼盗，沾洒望清光。"]},{"t":"昌平道中","f":"五言律诗","c":["山家未夕昏，半已掩柴门。","车马争途疾，牛羊下坂喧。","春阴入陵树，雨色过湖村。","谁道相如病，犹堪守汉园。"]},{"t":"朝陵遇雨 其一","f":"五言律诗","c":["柏寝参玄漠，松区俯泬寥。","威灵群帝接，风雨百神朝。","穴地重关阻，升天此路遥。","攀龙无处所，遗泽下丹霄。"]},{"t":"朝陵遇雨 其二","f":"五言律诗","c":["言避崤陵雨，翻行大壑云。","微风清树气，积润洗山文。","银海春波阔，龙池细涧分。","九陵松柏路，香霭日氤氲。"]},{"t":"供事长陵 其一","f":"五言律诗","c":["文皇鼎成后，此地葬衣冠。","日月神宫閟，山河帝寝安。","塞云疑扈跸，关树想回銮。","寂寞犁庭事，深知创业难。"]},{"t":"供事长陵 其二","f":"五言律诗","c":["弓剑思轩后，山川会禹陵。","翠旗何日返，龙驭几时升。","寝殿行春草，幽宫寂夜灯。","万年关路北，神武至今称。"]},{"t":"雨中祀长陵柬同事孙给谏林内翰诸公","f":"五言律诗","c":["冒雨祠官肃，山园禁漏稀。","云轻沉穗帐，风细飒灵衣。","淅沥松阶静，深沉燎火微。","群公攀望处，入夜有龙归。"]},{"t":"山陵对雨同孙林二子","f":"五言律诗","c":["春雨忽成霖，春山不可寻。","稍孤登陟兴，翻惬卧游心。","香涧停呦鹿，新波带浴禽。","看君幽事足，为我弹鸣琴。"]},{"t":"宿巩华城王将军宅","f":"五言律诗","c":["将军躩跞翁，壮岁事从戎。","枥敝闲嘶骑，尘韬久挂弓。","笳声来远塞，树影过离宫。","只为时平久，农谈终夕同。"]},{"t":"四月朔己酉日食","f":"五言律诗","c":["日月频见食，阴阳春夏更。","岂应恒失度，无乃暂伤明。","白昼麒麟斗，青天河汉横。","何劳问徵应，宵旰是皇情。"]},{"t":"赠关羽客还罗浮","f":"五言律诗","c":["频夜瑶台梦，君今采药还。","终须去天上，常见在人间。","葛令炉边宅，安期海上山。","暂离亦千岁，记取别时颜。"]},{"t":"花朝忆故园","f":"五言律诗","c":["故里花开日，壶觞特地忙。","朝携东郭饮，暮宴西家庄。","常恐人事累，兼愁风雨妨。","如何系簪绂，端坐阅时芳。"]},{"t":"闲斋春日","f":"五言律诗","c":["长啸即山林，閒庭步绿阴。","落花时有径，流水恨无琴。","把酒宫莺乱，看云苑树深。","寄言朝市者，知予大隐心。"]},{"t":"游宗谦老年出塞壮之","f":"五言律诗","c":["嗟君垂老日，策马蓟门东。","易酒颜犹壮，燕歌气尚雄。","敝裘经积雪，颓鬓逐秋蓬。","寄谢行间客，无轻塞上翁。"]},{"t":"送何仪部稚孝谪桂林","f":"五言律诗","c":["长沙非不远，南去更萧森。","谪宦楚山尽，独行湘水深。","乡书同雁少，官舍共猿吟。","今夕怀人梦，随君到桂林。"]},{"t":"游满井同林检讨咨伯谭光禄子文","f":"五言律诗","c":["红亭罗灌木，碧甃泻银塘。","仰面飞流洒，翻阶瀑水凉。","居人闲抱瓮，游女竞明妆。","似得持盈戒，还令机事忘。"]},{"t":"赠刘武库玄子","f":"五言律诗","c":["楼船横海日，属国护羌年。","身保命不辱，名高谤愈全。","乱蝉出深树，独鹤下秋烟。","长揖去林壑，汝南多昔贤。"]},{"t":"苑西楼客至","f":"五言律诗","c":["小楼仙苑外，芳树碧城隅。","留客因题竹，闲吟且据梧。","浊醪过近市，粗饭具中厨。","谑浪金门隐，风流即我徒。"]},{"t":"汝纶将归南暂往吴门酒后赋此","f":"五言律诗","c":["万里狂歌客，三年混酒徒。","掉头金马诏，携手玉人酤。","夜月拈鹦鹉，春风泣鹧鸪。","偶然不得意，长啸去游吴。"]},{"t":"秋夕家人宴","f":"五言律诗","c":["金宫珠树侧，凤阁绣屏东。","月隐檐边桂，风来井上桐。","晚凉清枕簟，秋色净房栊。","楼外谁家妇，停砧思朔鸿。"]},{"t":"忆山中","f":"五言律诗","c":["偶忆山中侣，连朝隔采薇。","竹根棋局冷，松下酒杯稀。","道路悠悠惯，风尘事事违。","才微将宦薄，何日不堪归。"]},{"t":"游宗谦至自塞上别归莆","f":"五言律诗","c":["木兰陂上客，还泛木兰舟。","芳草还家路，黄榆入塞秋。","海鸥翔不下，野鹤暮何求。","莫讶游归晚，山人本姓游。"]},{"t":"喜四家兄至","f":"五言律诗","c":["远道风和雪，连朝弟忆兄。","三年此重见，万里独长征。","翅接云鸿早，枝连苑树荣。","所期对策后，鹓序拟随行。"]},{"t":"七舍弟以东明令入觐遂拜徵命 其一","f":"五言律诗","c":["三年重挹袂，几度各沾裳。","问子容何减，忧时鬓欲苍。","赤墀求直谏，青史纪循良。","无恙图书在，萧然去日装。"]},{"t":"七舍弟以东明令入觐遂拜徵命 其二","f":"五言律诗","c":["凫来丹灶令，凤去紫泥书。","出宰贤声遍，还朝清问馀。","鹓鸿班并入，台省席元虚。","努力期同气，丹诚问玉除。"]},{"t":"送邓德咸复任上杭","f":"五言律诗","c":["双凫明日远，斗酒为君倾。","柳色宫城浅，桃花山县明。","南人新□□，□□又销兵。","别后闻为政，春江二月莺。"]},{"t":"酬少司空沈纯父春日见忆","f":"五言律诗","c":["同居凤城内，何事阻相期。","忽枉看花句，翻成伐木诗。","池光初解冻，莺语渐依枝。","伫立碧云暮，如何慰所思。"]},{"t":"经玉河堤上望瀛洲亭 其一","f":"五言律诗","c":["环岛疑无路，迢迢隔紫氛。","池分太液水，亭出五城云。","风静莺迁和，天高鹤散群。","尘踪不到处，长日有论文。"]},{"t":"经玉河堤上望瀛洲亭 其二","f":"五言律诗","c":["隔浦望仙瀛，开林接凤城。","云藏珠玉字，风引佩环声。","把酒思文友，临池想墨卿。","盈盈一水隔，谁见有逢迎。"]},{"t":"咏窗月梅影","f":"五言律诗","c":["窗月照梅花，梅影印窗纱。","乍恍临风动，谁知逐桂斜。","美人问镜立，暗忆寄瑶华。","不是香难掩，潏楼路复赊。"]},{"t":"早春送乡人南还","f":"五言律诗","c":["京华七日酒，岭树百重春。","终朝念乡土，是日送交亲。","嗟予久为客，因子访比邻。","溪上一茅宇，山南松桂新。"]},{"t":"送大田令张","f":"五言律诗","c":["行人二月去，雨雪尚春明。","闻道大田郭，终朝布谷声。","山晴公事少，溪晚客吟清。","借问舄凫出，何时车鹭迎。"]},{"t":"送庄得全编修予告还湘川","f":"五言律诗","c":["春风黄鸟期，春日复多思。","况当千里别，更作几重悲。","绿蘋通远意，白芷动芳词。","离恨樽前在，纷纷看柳丝。"]},{"t":"别山上人房看牡丹","f":"五言律诗","c":["净土幻名花，春藏大士家。","药王施法雨，天女散朝霞。","妙相都无染，空香亦自奢。","此真色色界，不是竞繁华。"]},{"t":"午日张家湾舟中即事","f":"五言律诗","c":["绿树移官舫，清波蘸客衣。","岁明行处见，采拾望中违。","汉节新恩是，湘累旧俗非。","自然爽意惬，纨扇不须挥。"]},{"t":"初发潞河","f":"五言律诗","c":["舟行才几里，已觉清心魂。","高岸隐遥郭，平沙出远村。","鹤行汀有迹，云过水无痕。","渐喜闻渔榜，程程近故园。"]},{"t":"望月有怀侍御弟","f":"五言律诗","c":["昨夜西楼月，同欢对凤池。","今来千里望，复值再圆期。","思切披帷屡，情多度汉迟。","乌栖知向府，鹊绕定何枝。"]},{"t":"发卫水","f":"五言律诗","c":["鸣钲辞北渚，持节下南藩。","历国方询俗，寻河尚识源。","津妃歌自远，漕卒晚犹喧。","行役今如此，羁怀未敢论。"]},{"t":"舟中对月","f":"五言律诗","c":["桂月宜芳夜，兰桡爱晚洲。","镜随菱水泛，弦逐箭波流。","岸白非关雪，沙明不辨鸥。","移家方此夕，谁解有离愁。"]},{"t":"次故城谒澹台董子祠","f":"五言律诗","c":["问俗经遗里，钦贤得并祠。","知人孔圣叹，策士汉皇私。","径寂榛从塞，园荒鸟任窥。","平生守正意，景行必于斯。"]},{"t":"过武城","f":"五言律诗","c":["言子留遗邑，经过挹素芬。","林光川上见，城影渡头分。","政以得人美，官应学道闻。","弦歌问遗俗，客思坐氛氲。"]},{"t":"咏分水","f":"五言律诗","c":["此水何南北，当由人所为。","引来元共派，分去必因卑。","顺逆流中判，盈虚浪乍移。","从来歧路叹，逝者亦如斯。"]},{"t":"济上酒楼","f":"五言律诗","c":["我忆任城会，风流贺季真。","停杯待来客，果得谪仙人。","万古此风月，千秋成主宾。","良游不可再，何处访遗尘。"]},{"t":"偶到南池旋即登舟同咨伯检讨","f":"五言律诗","c":["南池好风景，行侣赏心违。","地静日光薄，亭深花气微。","鱼知寻藻乐，燕喜傍人飞。","不见昔游辈，高吟倚棹归。"]},{"t":"题金山寺","f":"五言律诗","c":["万古金山寺，烟波四望分。","对江吴共楚，终日水和云。","灯影摇鲛室，香烟触雁群。","最宜禅诵处，船客夜深闻。"]},{"t":"游焦山 其一","f":"五言律诗","c":["碧岫沧波上，幽人旧隐称。","云藏三诏洞，林寂四禅僧。","岸火分京口，江涛接广陵。","岂徒中泠水，能使客心澄。"]},{"t":"游焦山 其二","f":"五言律诗","c":["绀宇写澄瀛，丹台接化城。","岸形临水断，楼势倚江清。","潭月窥僧定，风潮杂梵声。","禅居得清静，况乃事长生。"]},{"t":"谒焦君祠","f":"五言律诗","c":["言乘扬子渡，遂访焦君庐。","天地一鸿羽，江山几鹤书。","松阴入洞古，帆影过窗虚。","因谢区中想，道心闲有馀。"]},{"t":"惠山泉","f":"五言律诗","c":["问讯惠山寺，因知第二泉。","饮冰当夏日，沸雪散炎烟。","远汲通殊域，分流灌野田。","何人漱玉齿，细读品茶篇。"]},{"t":"使过杭州船中七夕","f":"五言律诗","c":["南国秋砧起，西湖夕泛归。","桥文依鹊远，槎影入河微。","粉席连堤幕，针楼动水扉。","明朝访卜肆，定自识支机。"]},{"t":"出钱塘门览古作 其一","f":"五言律诗","c":["驻马钱塘路，逢人说胜游。","湖光吴苑晚，山色宋陵秋。","岩桂密连寺，渚花高映楼。","伤心六桥月，不照汴河洲。"]},{"t":"出钱塘门览古作 其二","f":"五言律诗","c":["花月迷人去，江山胜事存。","由来耽乐土，不复问中原。","歌舞喧南渡，风尘暗北辕。","祇馀湖上草，岁岁为王孙。"]},{"t":"泊严滩寄桐庐刘宰","f":"五言律诗","c":["泠泠此滩水，尚有古人名。","闻道桐江宰，鸣琴相与清。","树笼芳霭淡，鸥泛晚波轻。","俯仰情何限，临流一寄声。"]},{"t":"晚霁玉峡驿望玉笥山","f":"五言律诗","c":["峡束江流窄，山欹堞影低。","玉梁沉宿雾，金涧落晴霓。","水鸟窥鱼下，林猿摘果啼。","灵峰不可到，矫首问丹梯。"]},{"t":"题环山楼","f":"五言律诗","c":["小楼通四望，面面惟烟霞。","为爱群峰入，何曾半壁遮。","翻疑岸岫矮，不觉磴途赊。","最快清秋目，林林赤似花。"]},{"t":"自怡园为东君题","f":"五言律诗","c":["闻学华阳隐，为园取自怡。","白云难赠客，芳草更遗谁。","果熟禽来早，花疏蝶去迟。","祇馀瑶瑟调，犹为美人思。"]},{"t":"刘东君招游家园","f":"五言律诗","c":["卿家好园馆，近郭复经廛。","云沼野光润，林峦秋气鲜。","广庭不直达，幽榭或斜穿。","招我云鸿曲，酬之岩桂篇。"]},{"t":"独游兴教寺","f":"五言律诗","c":["野寺平郊隐，幽人独骑过。","旱田秋穫少，近郭晚樵多。","树动霜摇橘，池荒风捲荷。","安知花院里，不有病维摩。"]},{"t":"宝界寺东廊有东坡画竹壁间年久剥落过半其存者笔气如生立玩移时","f":"五言律诗","c":["画竹僧廊在，尘埃年代深。","捎檐随笔爽，穿石竞毫森。","古壁烟云湿，晴天风雨吟。","山灵亦爱惜，劲直到如今。"]},{"t":"自大庾度岭","f":"五言律诗","c":["肩舆历翠微，马首十年违。","旧垒仍馀壁，新松又几围。","林香木犀发，山晚翠禽飞。","莫问符繻在，关云拥传归。"]},{"t":"平圃妇 其一","f":"五言律诗","c":["山途亦自别，恒避使君车。","蛮结双环出，吴罗半面遮。","定言长礼族，不必问谁家。","何似长安道，香车竞狭斜。"]},{"t":"平圃妇 其二","f":"五言律诗","c":["问俗怜兹朴，观风羡彼姝。","远嫌兼达礼，薄粉且施朱。","露叶翠迎鬓，山花红趁襦。","定知夫婿异，不笑使君愚。"]},{"t":"谒张文献祠","f":"五言律诗","c":["一代孤忠在，千秋大雅存。","诗才推正始，相业忆开元。","曝日陈金鉴，蒙尘想剑门。","更吟羽扇赋，摇夺不堪论。"]},{"t":"游清远峡山寺","f":"五言律诗","c":["香刹住峰头，花宫俯夕流。","猿吟丹嶂静，鹤坐小松幽。","片石窥僧榻，归云碍佛楼。","迟回无不可，乘月上方留。"]},{"t":"还至胥江顺庆儒懿嘉贞恭慈国诸侄来迎 其一","f":"五言律诗","c":["八年思见汝，万里暂还人。","兄弟皆成长，悲欢各自陈。","山田数亩在，庭桂几枝新。","闻道竹林宴，依然南阮贫。"]},{"t":"还至胥江顺庆儒懿嘉贞恭慈国诸侄来迎 其二","f":"五言律诗","c":["远道能怜叔，相将短棹迎。","书常隔岁至，学有十年成。","欢剧追儿戏，情多唤小名。","东山棋局在，或可谢苍生。"]},{"t":"还至胥江顺庆儒懿嘉贞恭慈国诸侄来迎 其三","f":"五言律诗","c":["楚楚几家驹，相迎万里途。","别时犹稚小，归略具髭须。","见汝知吾老，逢人笑客迂。","勋名休借问，终日愧驰驱。"]},{"t":"秋日还山 其一","f":"五言律诗","c":["秋山久不到，每与秋风期。","绝涧倒槎碍，悬崖枯蔓垂。","马疲知旧路，松古发新枝。","遂欲投簪绂，长歌与世辞。"]},{"t":"秋日还山 其二","f":"五言律诗","c":["村边黄叶路，溪上白云岑。","草屋山家浅，松门野寺深。","群鱼依密藻，独鹤返高林。","若问还山事，多应负此心。"]},{"t":"秋日还山 其三","f":"五言律诗","c":["频年寄书意，及此返柴关。","泉响竹间石，霞明林外山。","无人共长往，有客暂投闲。","何事金门老，风尘却忘还。"]},{"t":"谒先墓 其一","f":"五言律诗","c":["久宦抛庐舍，衔恩展墓田。","岁时违洒拂，霜露几凄然。","马踏残秋草，乌啼古树烟。","孤忠犹未白，何敢报重泉。"]},{"t":"谒先墓 其二","f":"五言律诗","c":["地下音容在，人间岁月侵。","年将世泽远，江与泪痕深。","鸟雀荒村路，松楸久客心。","空劳岵屺咏，终废蓼莪吟。"]},{"t":"再宿溪上楼三兄读书处 其一","f":"古风","c":["弭节上兹楼，风光异昔游。","芸香充故栋，帘影上新钩。","雁序中年断，鸰原此日秋。","藏舟不可问，?水恨悠悠。"]},{"t":"再宿溪上楼三兄读书处 其二","f":"五言律诗","c":["书带草新绿，阶钱苔半生。","尘埃展旧榻，鸟雀聚虚楹。","有弟官皆达，群儿学渐成。","人琴竟已矣，含叹几时平。"]},{"t":"自横槎泛端溪","f":"五言律诗","c":["竹岸收残市，花源访故津。","里将仁共美，俗以德为邻。","土布芭蕉盛，林香橘柚新。","何须会稽守，方作锦衣人。"]},{"t":"黎惟仁梁少仲麦仲张黎君玺邀集浮丘 其一","f":"五言律诗","c":["洞府何年别，烟霞此会同。","白云期乍返，沧海信常通。","谒帝留双舄，宾王遇八公。","还持鸿宝术，归访葛仙翁。"]},{"t":"黎惟仁梁少仲麦仲张黎君玺邀集浮丘 其二","f":"五言律诗","c":["闻有辽东鹤，千年始一还。","我来仍未远，遗迹尚堪攀。","访旧期餐液，求仙忆住山。","沧桑何足问，小别鬓成斑。"]},{"t":"宿西南驿即事","f":"五言律诗","c":["未晚商船集，将昏戍鼓多。","驿楼翔水雾，村火漏烟萝。","夜柝迎风急，寒潮候晚过。","常因白雉入，忆得海无波。"]},{"t":"送游宗谦归闽","f":"五言律诗","c":["贫交怜此别，昨别是京华。","身老常为客，年残未到家。","海风吹鬓短，江雁背人斜。","不用忧荒岁，归餐洞口霞。"]},{"t":"正月三日黎惟仁诸公携酒见过得供字","f":"五言律诗","c":["暂着还山屐，闲扶采药筇。","年新堤柳发，春暖砌桃秾。","客至携尊酒，家贫少馔供。","临池觞屡进，但觉野情浓。"]},{"t":"重至濠上旧居 其一","f":"五言律诗","c":["濠西一亩宅，伊昔下帷馀。","壁暗曾题字，园荒旧读书。","闲禽歌后院，流水绕前除。","旧识邻家叟，无惊驷马车。"]},{"t":"重至濠上旧居 其二","f":"五言律诗","c":["树回通委巷，花发识前津。","昔去荒三径，今来访四邻。","庭闲侵履藓，架掩积书尘。","旧种墙东竹，年年待主人。"]},{"t":"山馆春日","f":"五言律诗","c":["春园桃李月，山馆桂松烟。","竹影壁间翠，花光池上燃。","楮芳初剪玉，榆小未铺钱。","节物信为悦，簪绅徒自牵。"]},{"t":"新成草堂之卜暇日漫兴 其一","f":"五言律诗","c":["偶洽林泉赏，端居意绪闲。","阶兰差可掇，庭桂即堪攀。","风扫留宾榻，云来傍舍山。","居然松菊主，堪作挂冠还。"]},{"t":"新成草堂之卜暇日漫兴 其二","f":"五言律诗","c":["疏豁称吾庐，仍惭仁智居。","颓墉粗补葺，荒蔓颇芟除。","檐影交苔静，池光映竹虚。","小童灌园罢，花下报朋车。"]},{"t":"新成草堂之卜暇日漫兴 其三","f":"古风","c":["濠上昔垂钓，?东昨耦耕。","未知投老地，聊快著书情。","兰蕙思君子，棠花识弟兄。","闲携竹林兴，驻屐听流莺。"]},{"t":"新成草堂之卜暇日漫兴 其四","f":"五言律诗","c":["园林多暇日，簪绂忝明时。","独负烟霞癖，谁图丘壑姿。","春花披露摘，冬果带霜移。","有客荷锄至，囊中得紫芝。"]},{"t":"园内小台","f":"五言律诗","c":["桃李夹池栽，丛丛出小台。","共跻明月上，独步清风来。","看山聊隐几，临水屡挥杯。","胜友频过此，高轩醉不回。"]},{"t":"草堂新开四家兄携诸侄自?川移舫志喜 其一","f":"五言律诗","c":["自枉移舟约，先令扫户迎。","入林仍共侄，举步即随兄。","园蕊连枝发，池篁迸砌生。","殷勤此酬劝，弥畅友于情。"]},{"t":"草堂新开四家兄携诸侄自?川移舫志喜 其二","f":"古风","c":["虽居穗城北，常忆?川东。","胜怀因物寓，芳意与君同。","小酌花间露，高谈竹下风。","时闻棠棣咏，来对玉兰丛。"]},{"t":"山馆漫兴兼柬黎惟仁梁少仲","f":"五言律诗","c":["良辰追胜事，高论集清流。","买宅因林僻，为邻取寺幽。","在家称长者，出户访比丘。","终愿与君辈，相将鸾鹤游。"]},{"t":"将有报使之役山馆寓怀","f":"五言律诗","c":["年芳非一事，对此独怡神。","小院烟霞色，幽庭松桂春。","浊醪兼养性，丹壑且全真。","懒出元吾意，何曾说向人。"]},{"t":"浮丘洞中宴","f":"五言律诗","c":["洞府游仙入，楼台望气通。","焚香来桂女，行酒命芝童。","鹤舞春池月，莺啼碧树风。","何当倚长袖，共挹浮丘公。"]},{"t":"拟佳人年十五","f":"五言律诗","c":["艳质正婵娟，韶光复可怜。","能歌初按拍，学弹始调弦。","柔意才含蕙，芳心半吐莲。","惟应三五夜，璧月此长圆。"]},{"t":"舟夜别何孔参","f":"五言律诗","c":["行舟仍暂舣，握手暝前湾。","岸火连星出，春潮带月还。","居人感白首，游子叹红颜。","且恋离杯数，严城未上关。"]},{"t":"初发珠江","f":"五言律诗","c":["芳菲已满目，洲渚复含情。","别路千程始，离愁百念生。","简书催远去，行役惮孤征。","为问辞家屡，劳劳何所成。"]},{"t":"晚发三水溯北江","f":"五言律诗","c":["行客才经宿，离愁已不堪。","邮亭数长短，江路背西南。","里树春烟断，山城夕照衔。","何时已行役，归结桂松庵。"]},{"t":"将至胥江与兄侄别 其一","f":"五言律诗","c":["客游非不好，奈此别情何。","连雁沙边久，离杯竹下多。","中流忽判袂，芳渚遂分波。","相望徒相失，谁能听榜歌。"]},{"t":"将至胥江与兄侄别 其二","f":"五言律诗","c":["贤兄怜此别，小侄复沾襟。","浦叶初辞树，汀鸿忽异林。","江空数帆影，岸转失挐音。","知逐回波去，何由返棹寻。"]},{"t":"酬别梁少仲黎君玺兄弟","f":"五言律诗","c":["梁公松柏质，黎子璠玙姿。","对酒惜长别，临风扬妙词。","兰香发深谷，莺啭上高枝。","明旦怀亲友，山川遥梦思。"]},{"t":"渡浈阳","f":"五言律诗","c":["岭路多奇绝，浈江境最幽。","窥潭竹影净，披霭树光流。","云气常凝夏，猿声尽带秋。","投竿未忍去，辍棹且夷犹。"]},{"t":"晚次清溪驿","f":"五言律诗","c":["古驿清溪上，溪声净掩扉。","沙昏商舸集，村响晚樵归。","旅食沾松粉，邮亭挂薜衣。","临流饶怪石，时忆旧渔矶。"]},{"t":"自清溪驿趋曲江山行作","f":"五言律诗","c":["晓障陟崔嵬，淩晨石路开。","鸟啼皆应谷，涧影半含苔。","林霭吹花度，溪烟杂雨来。","王程若可缓，幽赏更迟徊。"]},{"t":"过曹溪 其一","f":"五言律诗","c":["闻道南华寺，寻源向此溪。","水香浮钵远，山翠入檐低。","樵路春游鹿，松房午放鸡。","津梁云不远，过此识前迷。"]},{"t":"过曹溪 其二","f":"五言律诗","c":["相传此溪胜，来渡莫辞频。","一派澄心水，千年说法人。","松门数里寺，茅屋几家邻。","愿假慈航力，长成利涉津。"]},{"t":"见舆人妇携儿女馈饷其夫","f":"五言律诗","c":["岂是春田馌，将无玉案齐。","应怜齐相御，好谢买臣妻。","路李枝多子，山梅花满蹊。","此时闺中望，玉箸几行啼。"]},{"t":"次始兴江口驿舍","f":"五言律诗","c":["秋杪曾驱传，春深复此行。","携家殊往日，独客倦长征。","鸟雀荒村暮，风烟古路平。","寒衣犹未脱，肠断望乡情。"]},{"t":"客中听刘季德吹箫","f":"五言律诗","c":["昔有秦台客，遗氛住绛霄。","忽传飞凤引，独下彩云朝。","奈此远游意，怅然仙路遥。","乘鸾无处所，瑶管若为调。"]},{"t":"于曲江逢高正甫奉使南还","f":"五言律诗","c":["相逢一杯酒，与子暂绸缪。","以我北来信，付君南下舟。","乡心沧海上，客泪曲江头。","为问乘槎使，何时到广州。"]},{"t":"寒食后晚投驿馆作","f":"五言律诗","c":["春事行将暮，羁愁殊未宣。","兰肴过冷食，槐火试新烟。","吏立松花下，马嘶藤叶前。","东郊斗鸡道，遥忆帝城边。"]},{"t":"晚至圆通寺","f":"五言律诗","c":["入寺一钟鸣，悠然幽思生。","泉声和梵语，林影共僧行。","藤叶溪烟积，松花石路平。","禅房暂栖息，已觉旅魂清。"]},{"t":"暮至天池寺","f":"五言律诗","c":["晓策淩晨磴，昏钟叩暝萝。","天文上界近，梵语半空多。","河迥横窗落，云低俯槛过。","预愁筋力少，最奈胜游何。"]},{"t":"佛手岩有竹林寺遗迹","f":"五言律诗","c":["僧言翠微顶，剩有一岩幽。","异境客难到，诸天人罕求。","崖悬几屋险，猿啸半山秋。","不见竹林隐，时传钟梵留。"]},{"t":"大林寺","f":"五言律诗","c":["大林何代寺，花木尚馀芬。","僧老艺松竹，鹤闲眠洞云。","石苔微雨滑，泉涧细流分。","天外猿声断，寂寥几客闻。"]},{"t":"东林寺","f":"五言律诗","c":["昔读高僧传，兼怀逸士踪。","停车虎溪水，对面香炉峰。","旧殿丹青落，荒池蔓草茸。","我来松下坐，日暮但闻钟。"]},{"t":"僧言远公池上忽开白莲","f":"五言律诗","c":["远公开社后，池废已千年。","见说金仙降，俄然涌白莲。","空香千叶散，妙相一花研。","本自心无染，谁将半偈传。"]},{"t":"浔阳渡江","f":"五言律诗","c":["天浮三楚渡，城压九江浔。","远堑分南北，中流见古今。","桃花经汉渚，兰气下湘阴。","为问朝宗意，应知望阙心。"]},{"t":"破额山道场","f":"五言律诗","c":["为问西来信，灯凡几叶传。","林端千梵接，象外二峰悬。","演法开三乘，观空出四天。","何时解尘缚，来此共栖禅。"]},{"t":"丙申三月十五日食寓西河驿作","f":"五言律诗","c":["月本为阴象，辉盈有蚀时。","照临终不灭，圆景得无亏。","小驿冠裳少，荒村鼓角迟。","伫看光复处，始解万方疑。"]},{"t":"纡途过光州访故友刘职方园池","f":"五言律诗","c":["为践今生约，何言隔世期。","云林应识我，鸡黍到因谁。","花蕊经春落，禽声入暮悲。","惟馀昔时剑，凄断挂何枝。"]},{"t":"面壁洞","f":"五言律诗","c":["震旦初来日，烟霞启洞扉。","苔生面壁石，云湿坐禅衣。","五叶灯前度，三花顶上飞。","不知传教后，何事又西归。"]},{"t":"春日游岳祠","f":"五言律诗","c":["丹台悬碧落，紫阁上空濛。","兴发烟霞外，春归天地中。","瑶林披霁雪，香霭飏微风。","仙路逢迎处，纷纷羽节同。"]},{"t":"铜雀妓","f":"五言律诗","c":["铜台朝夕望，玉座掩流尘。","园馆沦长夜，恩情无复春。","铅华是日落，眉黛逐愁新。","惟见西陵月，殊非欢宴辰。"]},{"t":"使还京邸有怀一时放逐诸君子","f":"五言律诗","c":["往来方岁隔，时事忽朝更。","吾弟得罪去，诸君胡为行。","悬巢无过燕，倚树独听莺。","已采场驹咏，将何达圣明。"]},{"t":"送梁同年赴越西幕名炫","f":"五言律诗","c":["漓江西上寻，向下动乡心。","借问莲花府，人言桂树林。","地形三楚尽，山色九疑深。","幕下由来重，多才独见今。"]},{"t":"送霍明府左迁河东转运从事名与瑺","f":"五言律诗","c":["才人新人幕，邑宰旧鸣琴。","何事太行坂，能摧赤骥心。","关危通马邑，地广实鸡林。","莫道盐官小，今年国计深。"]},{"t":"得故园亲友书","f":"五言律诗","c":["故园书札至，未读已伤神。","乡国离三月，亲知少两人。","红颜因别灭，白发伴愁新。","待到归田舍，衰翁几个邻。"]},{"t":"汪和叔新种庭竹索题","f":"五言律诗","c":["种君庭下竹，邀我中林人。","入牖摇疏翠，临阶扫俗尘。","秋声风际劲，寒色雨中新。","万个沧江上，茅斋滋绿筠。"]},{"t":"送混成子 其一","f":"五言律诗","c":["夫子富道术，世人无不闻。","徒闻不能用，长啸空青云。","丹簏烟霞记，玉钤龙虎文。","西山有鸾鹤，应共尔为群。"]},{"t":"送混成子 其二","f":"五言律诗","c":["再坐广文席，一弹邑宰弦。","弦为新绿绮，席是旧青毡。","歇马榴花酒，过江莲叶船。","行藏不自意，何问沧浪天。"]},{"t":"孝安陈太后挽词 其一","f":"五言律诗","c":["内朝倦临御，中禁罢晨昏。","后德千龄茂，母仪三纪存。","永辞长乐仗，去上昭陵园。","嫔御一哀送，悲风动国门。"]},{"t":"孝安陈太后挽词 其二","f":"五言律诗","c":["桂寝沦阴夕，椒涂启殡时。","人怀丧妣慕，帝轸殒慈悲。","宫女收遗事，词臣纪令仪。","至今称马邓，惟绝外家私。"]},{"t":"孝安陈太后挽词 其三","f":"五言律诗","c":["惨淡兰陔寂，阴沉桂殿空。","鸾旌犹往日，龙綍已新宫。","银海人难渡，瑶台路不穷。","惟应彤管德，千载冠椒风。"]},{"t":"孝安陈太后挽词 其四","f":"五言律诗","c":["仙舆披素帟，绛旐发皇畿。","仪卫平生是，山川临幸非。","玉衣迁隧馆，宝镜掩泉扉。","万姓何劳慕，瑶池此日归。"]},{"t":"十六夜高正甫寺居对月","f":"五言律诗","c":["爱月愿长满，披云复共娱。","光翻祇树静，影傍塔轮孤。","入座悬灯暗，穿林宿鸟呼。","圆辉殊未灭，讵假法尼珠。"]},{"t":"送别驾之肇庆","f":"五言律诗","c":["小郡秋江上，新恩别驾中。","封圻兼岭海，襟带尽西东。","驱马朔风疾，佩刀寒色雄。","长途日未暮，邦国急论功。"]},{"t":"送孝安皇太后梓宫出还登蓟丘","f":"五言律诗","c":["象卫灵风送，鸾舆卜日升。","徒劳素绋慕，正睹白云乘。","寂寂原野旷，凄凄霜露凝。","何人共愁望，烟雾隔昭陵。"]},{"t":"二月梅花","f":"五言律诗","c":["春色满瑶台，梅花犯雪开。","不言芳意晚，乃发艳阳来。","桃李宜相照，冰霜幸未摧。","因君正留赏，度曲且迟回。"]},{"t":"送王行甫","f":"五言律诗","c":["朝来对酒处，白发几茎丝。","复此送行客，翻然感路歧。","汉宫妒眉黛，楚苑擅腰肢。","赠子幽兰曲，还予芳杜期。"]},{"t":"效陈隋闺情","f":"五言律诗","c":["初莺一两啭，嫩叶数重围。","喜子寻窗织，宜男傍砌菲。","宁辞挑锦字，暂下流黄机。","眉黛看重拂，边书昨夜归。"]},{"t":"仲春郊外游眺","f":"五言律诗","c":["东郊迟马埒，南院看花帏。","皋响清游佩，风香动过衣。","鸣鸠双翅拂，喧雁几行归。","纤柳裁堪折，含桃未可飞。"]},{"t":"荣庄李贵妃挽词 其一 内制","f":"五言律诗","c":["鱼贯方仪茂，椒涂惠问崇。","承恩辞并辇，随御忆当熊。","贵幸全无比，荣华亦易空。","只馀团扇咏，犹似怨秋风。"]},{"t":"荣庄李贵妃挽词 其二 内制","f":"五言律诗","c":["平生宠未歇，兹夕来何迟。","寂寂云光落，姗姗仙步疑。","授环徒有眷，傍辇更无期。","何异姑繇水，凄然望乐池。"]},{"t":"荣庄李贵妃挽词 其三 内制","f":"五言律诗","c":["灵卫陈金册，仙舆导桂旗。","言随王母去，独御彩云归。","尘满新辞幄，香残旧赐衣。","圣君希女谒，徒惜此贤妃。"]},{"t":"送蒲州张尚宝使蜀便道过家","f":"五言律诗","c":["忽闻歌蜀道，星使出天津。","家在龙门上，途经汾水春。","锦流潆去栈，蒲坂望归人。","不作昼游客，何名贵近臣。"]},{"t":"初夏过沈道士房","f":"五言律诗","c":["碧玉风前树，红泉雨后霞。","偶寻松子约，来醉羽人家。","叶暗桃初实，林香枣始花。","仙书若有访，知我在金华。"]},{"t":"送卢长乐","f":"五言律诗","c":["榴花不及春，照客出城闉。","麦秀想行县，凫惊由畏人。","车轮登路熟，琴曲改弦新。","持子寸心在，坚乎不可磷。"]},{"t":"待月有怀","f":"五言律诗","c":["留步待婵娟，空庭白露漙。","含情望云汉，彼美隔云端。","桂气微风发，珠晖素箔寒。","殷勤洞房色，罗帐不成欢。"]},{"t":"七夕有怀","f":"五言律诗","c":["银汉鹊停飞，星桥妇下机。","月华移宝扇，云彩动仙衣。","天作经年合，人怜此会稀。","无由展情恨，独步后庭归。"]},{"t":"中秋夜独步小台望月","f":"五言律诗","c":["就枕未能安，披帏坐夜阑。","阴晴万里共，光景百年看。","寂寂此愁望，迢迢怀旧欢。","莫将罗袂色，来照客衾寒。"]},{"t":"杨义叔宪副入贺同袁仲奎少参高正甫比部集天坛道院","f":"五言律诗","c":["欣逢朝玉阙，嬉戏出丹房。","暂到偕鸾鹤，重游□海桑。","天居云自迥，辇路草堪长。","且共探琼液，来朝和柏梁。"]},{"t":"院菊初开诸客过酌","f":"五言律诗","c":["锦石带寒英，秋光澹客情。","色增蓬鬓逸，香泛酒筵清。","细雨看仍立，深杯坐复倾。","可知三径意，不是为逃名。"]},{"t":"送罗敬叔归江上田舍 其一","f":"五言律诗","c":["菊黄稻又熟，秋事满郊墟。","正睹过江雁，因思纵壑鱼。","山瓢促家酝，野饭饱园蔬。","问子归何乐，躬耕仍读书。"]},{"t":"送罗敬叔归江上田舍 其二","f":"五言律诗","c":["山明远空静，日落秋江深。","独住江云里，谁沿江岸寻。","雾霞寒映水，霜鹤晚归林。","予亦思田舍，相期衡泌吟。"]},{"t":"送黄平倩太史还蜀 其一","f":"五言律诗","c":["黄叶散秋氛，参差远近分。","几群燕塞雁，万叠蜀山云。","旅服行中换，边书别后闻。","此时折杨柳，摇落为思君。"]},{"t":"送黄平倩太史还蜀 其二","f":"五言律诗","c":["梁山横碧烟，巴水流青天。","来往人情异，苍茫鸟道悬。","猿啼绿云里，雁叫秋风前。","遥见单栖羽，归向锦城边。"]},{"t":"岁除日立春对酒 其一","f":"五言律诗","c":["不觉韶年赏，都从暮节欢。","綵花明腊酒，生菜上辛盘。","岁里逢春易，春前守岁难。","欲知新旧鬓，倩为镜中看。"]},{"t":"岁除日立春对酒 其二","f":"五言律诗","c":["冬尽春先入，年还岁欲除。","瑶林初变鸟，冰沼未窥鱼。","柳发辞寒蚤，梅芳过雪馀。","韶光不恨晚，明旦拭簪裾。"]},{"t":"元旦阁中对雪 其一","f":"五言律诗","c":["初年看丽景，御柳已芳菲。","佳景玉京满，恩光瑶殿归。","林先六花发，瑞应初蓂飞。","今日皇心豫，天歌出禁闱。"]},{"t":"元旦阁中对雪 其二","f":"五言律诗","c":["天泽迎初节，祥图启曙晖。","乍披银霰集，更拂素云飞。","柏叶犹封翠，梅香共入衣。","欲裁元会曲，并和郢歌归。"]},{"t":"上元夜看游者和公干 其一","f":"五言律诗","c":["芳年乐事新，月色映灯轮。","九陌歌钟动，千门火树春。","粉香吹作雾，衫影乱飘尘。","愿假千场戏，淹留巧笑人。"]},{"t":"上元夜看游者和公干 其二","f":"五言律诗","c":["相携游伴出，南陌又东城。","永夜鱼龙戏，高楼弦管声。","催春花并放，留赏月偏明。","别有娱情处，酣歌达曙更。"]},{"t":"芳树","f":"五言律诗","c":["芳树初芳日，与君同上春。","最蒙瑶席赏，俱照玉台新。","叶暗萦歌袖，花飞承舞巾。","从来攀折意，都在艳阳辰。"]},{"t":"和四兄咏瓶中芍药","f":"五言律诗","c":["攀翻出兰砌，香霭入帘栊。","滋艳宜添水，障容更怯风。","幸逢纤手摘，得厕绮筵中。","犹胜微丛下，春枝夜夜空。"]},{"t":"宿慈恩寺","f":"五言律诗","c":["东岩吐月光，高论支公房。","松露滴阶响，荷风度水香。","钟声上界静，鹤梦寥天长。","觉后闻清梵，弥令心境忘。"]},{"t":"听无弦上人琴","f":"五言律诗","c":["上人无弦意，寄在有弦琴。","静室遣群妄，诸天聆妙音。","泠泠花上露，寂寂枝间禽。","永日竹林下，清风时满襟。"]},{"t":"听莺","f":"五言律诗","c":["苑外柳枝黄，莺啼出建章。","穿花如觅侣，隔叶似调簧。","雨过声犹湿，风来曲更长。","流黄机上妾，听罢拭啼妆。"]},{"t":"咏庭中槐和四家兄兼邀诸客同和 其一","f":"五言律诗","c":["幸植华轩下，敷荣自上春。","叶稠欺暑散，枝迥带烟新。","秀色过仙院，浓阴覆四邻。","谬承嘉树誉，滥许映台辰。"]},{"t":"咏庭中槐和四家兄兼邀诸客同和 其二","f":"五言律诗","c":["团圞阴广砌，旖旎发芳年。","复兹炎夏月，散影日华前。","高送吟风鸟，凉思饮露蝉。","南薰此披拂，留客和朱弦。"]}]};